select public.admin_save_lesson($lumi${"id":"mat-sistema-decimal","subject":"matematica","title":"Sistema de numeração decimal","levels":["fund1"],"grade":"1º ao 3º ano","topic":"Números","subtopic":"Valor posicional","aliases":["sistema decimal","unidade dezena centena","valor posicional","valor do algarismo","ordens e classes","milhar","decompor numero","numeros naturais"],"summary":"Entenda unidades, dezenas, centenas e milhares e por que o lugar de cada algarismo muda o seu valor.","intro":"Com apenas dez algarismos (0 a 9) escrevemos qualquer número. O segredo está no lugar de cada um!","objective":"Ler, escrever e decompor números, identificando o valor de cada algarismo pela sua posição.","next":["mat-adicao-subtracao"],"skills":{"agrupamento":"Agrupar de 10 em 10","posicao":"Valor posicional","decomposicao":"Decompor números","leitura":"Ler e escrever números"},"blocks":[{"skill":"agrupamento","title":"Grupos de 10","text":"No nosso sistema, contamos em grupos de 10: 10 unidades formam 1 dezena, 10 dezenas formam 1 centena e 10 centenas formam 1 milhar.","example":"Com 23 palitos você faz 2 montinhos de 10 (2 dezenas) e sobram 3 palitos soltos (3 unidades).","variants":{"simples":"Junte de 10 em 10. Cada montinho de 10 é uma dezena.","exemplo":"Pense em ovos: uma caixa com 10 ovos é uma dezena de ovos. Dez caixas cheias são 100 ovos: uma centena.","passos":"1. Conte os objetos.\n2. Faça grupos de 10 — cada grupo é 1 dezena.\n3. Se juntar 10 grupos de 10, você tem 1 centena.\n4. O que sobrar sem grupo são as unidades."},"id":"b1"},{"skill":"posicao","title":"O lugar muda o valor","text":"O valor de um algarismo depende da posição que ele ocupa. Da direita para a esquerda: unidades, dezenas, centenas, milhares.","example":"Em 352, o 3 vale 300 (3 centenas), o 5 vale 50 (5 dezenas) e o 2 vale 2 unidades.","variants":{"simples":"O mesmo número vale mais quando está mais para a esquerda. O 3 de 352 vale 300!","exemplo":"Em 44, os dois algarismos são iguais, mas o da esquerda vale 40 e o da direita vale 4.","passos":"1. Olhe o algarismo da direita: são as unidades.\n2. O do meio: dezenas (vale 10 vezes mais).\n3. O da esquerda: centenas (vale 100 vezes mais).\n4. Multiplique o algarismo pelo valor da casa."},"id":"b2"},{"skill":"decomposicao","title":"Decompor números","text":"Decompor é separar o número em partes pelo valor de cada algarismo. Assim fica fácil ver quanto cada um vale.","example":"4.726 = 4.000 + 700 + 20 + 6.","variants":{"simples":"Decompor é \"abrir\" o número: 58 = 50 + 8.","exemplo":"Se você tem 1 nota de R$ 100, 2 notas de R$ 10 e 5 moedas de R$ 1, tem 100 + 20 + 5 = R$ 125.","passos":"1. Separe cada algarismo.\n2. Escreva quanto ele vale pela posição.\n3. Some tudo com o sinal +.\n4. Confira: a soma tem que dar o número original."},"id":"b3"},{"skill":"leitura","title":"Ler e escrever números","text":"Para ler um número grande, separamos em grupos de três algarismos a partir da direita (classes). Lemos cada grupo e dizemos o nome da classe: mil, milhão…","example":"12.305 lê-se \"doze mil, trezentos e cinco\". O zero indica que não há dezenas.","variants":{"simples":"O ponto separa os milhares: 3.200 é \"três mil e duzentos\".","exemplo":"No preço de uma bicicleta, R$ 1.250, lemos \"mil duzentos e cinquenta reais\".","passos":"1. Separe de três em três algarismos, da direita para a esquerda.\n2. Leia o grupo da esquerda e diga \"mil\".\n3. Leia o grupo da direita.\n4. Se aparecer zero, é porque aquela casa está vazia."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"agrupamento","prompt":"Quantas unidades formam 1 dezena?","options":["5","10","100","12"],"answer":1,"hints":["Pense em grupos.","Uma dezena é um grupo de…","Dezena lembra \"dez\"."],"explanation":"1 dezena = 10 unidades.","id":"q1"},{"type":"mc","difficulty":1,"skill":"posicao","prompt":"No número 352, quanto vale o algarismo 5?","options":["5","50","500","35"],"answer":1,"hints":["Em que posição está o 5?","Ele está na casa das dezenas.","5 dezenas = 5 × 10."],"explanation":"O 5 está nas dezenas: vale 50.","id":"q2"},{"type":"tf","difficulty":1,"skill":"agrupamento","prompt":"10 dezenas formam 1 centena.","answer":true,"hints":["Quanto é 10 grupos de 10?","10 × 10.","= 100."],"explanation":"Verdadeiro: 10 dezenas = 100 unidades = 1 centena.","id":"q3"},{"type":"fill","difficulty":1,"skill":"decomposicao","prompt":"Complete: 58 = 50 + ____","answers":["8"],"hints":["Separe dezenas e unidades.","58 tem 5 dezenas e algumas unidades.","Quantas unidades sobram depois do 50?"],"explanation":"58 = 50 + 8.","id":"q4"},{"type":"mc","difficulty":2,"skill":"decomposicao","prompt":"Qual é a decomposição de 4.726?","options":["4 + 7 + 2 + 6","4.000 + 700 + 20 + 6","400 + 70 + 26","4.000 + 726 + 6"],"answer":1,"hints":["Cada algarismo vale conforme a posição.","O 4 está nos milhares.","Escreva quanto vale cada algarismo."],"explanation":"4.726 = 4.000 + 700 + 20 + 6.","id":"q5"},{"type":"match","difficulty":2,"skill":"posicao","prompt":"No número 2.839, ligue cada algarismo ao seu valor.","pairs":[["2","2.000"],["8","800"],["3","30"],["9","9"]],"hints":["Comece pela direita: unidades.","Depois dezenas e centenas.","O da esquerda está nos milhares."],"explanation":"2 → 2.000 · 8 → 800 · 3 → 30 · 9 → 9.","id":"q6"},{"type":"mc","difficulty":2,"skill":"leitura","prompt":"Como se lê 12.305?","options":["Doze mil, trezentos e cinco","Mil duzentos e trinta e cinco","Doze mil, trinta e cinco","Cento e vinte e três mil e cinco"],"answer":0,"hints":["Separe: 12 | 305.","O 12 é da classe dos milhares.","Depois leia 305."],"explanation":"12.305 = doze mil, trezentos e cinco.","id":"q7"},{"type":"fill","difficulty":2,"skill":"leitura","prompt":"Escreva com algarismos: \"três mil e quarenta\".","answers":["3040","3.040"],"hints":["São 3 milhares.","Não há centenas.","Há 4 dezenas e nenhuma unidade."],"explanation":"3.040: o zero ocupa a casa das centenas e a das unidades.","id":"q8"},{"type":"order","difficulty":2,"skill":"posicao","prompt":"Coloque os números do MENOR para o MAIOR.","items":["209","290","902","920"],"hints":["Compare primeiro as centenas.","Com centenas iguais, compare as dezenas.","2 centenas é menos que 9 centenas."],"explanation":"209 < 290 < 902 < 920.","id":"q9"},{"type":"tf","difficulty":3,"skill":"posicao","prompt":"Em 505, os dois algarismos 5 valem a mesma coisa.","answer":false,"hints":["Veja a posição de cada 5.","Um está nas centenas e outro nas unidades.","500 é igual a 5?"],"explanation":"Falso: o da esquerda vale 500 e o da direita vale 5.","id":"q10"},{"type":"mc","difficulty":3,"skill":"agrupamento","prompt":"Ana tem 3 caixas com 10 lápis e 7 lápis soltos. Quantos lápis ela tem?","options":["10","37","307","73"],"answer":1,"hints":["Cada caixa é uma dezena.","3 dezenas = 30.","Some os soltos."],"explanation":"3 dezenas + 7 unidades = 37 lápis.","id":"q11"},{"type":"open","difficulty":3,"skill":"posicao","prompt":"Explique por que o 7 em 70 vale mais do que o 7 em 17.","modelAnswer":"Porque no 70 o 7 está na casa das dezenas e vale 70, enquanto no 17 ele está na casa das unidades e vale apenas 7.","keywords":["dezena","unidade","posicao","lugar","casa"],"hints":["Onde está o 7 em cada número?","Um está nas dezenas, outro nas unidades.","Fale da posição (casa) do algarismo."],"explanation":"O valor depende da posição: dezenas valem 10 vezes mais que unidades.","id":"q12"}],"review":["10 unidades = 1 dezena · 10 dezenas = 1 centena · 10 centenas = 1 milhar","O valor do algarismo depende da posição","Decompor: 352 = 300 + 50 + 2","Leia separando de três em três algarismos"],"relatedQuestions":["O que é unidade, dezena e centena?","Como decompor um número?","O que é valor posicional?"],"equivalentQuestions":["o que é dezena","quanto vale uma centena","quantas dezenas tem uma centena","como saber o valor de um algarismo","por que o número muda de valor","como decompor 352","o que significa decompor um número","como escrever número por extenso","como ler números grandes","o que é milhar","quantas unidades tem um milhar","como separar unidade dezena e centena","o que é ordem e classe dos números","para que serve o ponto no número 1.000","como saber qual número é maior","me explica sistema decimal","por que contamos de 10 em 10","o que é algarismo","qual a diferença entre número e algarismo","como montar número com unidades e dezenas","o zero vale alguma coisa no número","como fazer quadro de ordens"],"commonDoubts":[{"q":"Qual a diferença entre número e algarismo?","a":"Algarismos são os símbolos 0 a 9. Números são formados por algarismos: 352 é um número com três algarismos."},{"q":"Se o zero não vale nada, por que escrevê-lo?","a":"O zero marca que aquela casa está vazia. Sem ele, 305 viraria 35 — outro número!"}],"commonErrors":["Achar que um algarismo vale sempre o mesmo, em qualquer posição","Esquecer o zero ao escrever números como 3.040","Ler da esquerda para a direita sem separar as classes"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-adicao-subtracao","subject":"matematica","title":"Adição e subtração","levels":["fund1"],"grade":"1º ao 4º ano","topic":"Operações","subtopic":"Adição e subtração","aliases":["adicao","subtracao","soma","somar","conta de mais","conta de menos","subtrair","emprestar na subtracao","vai um","reserva","troco"],"summary":"Aprenda a somar e subtrair, inclusive com \"vai um\" e \"empresta\", e a usar essas contas no dia a dia.","intro":"Somar é juntar. Subtrair é tirar ou comparar. Vamos ver como fazer as duas contas sem errar.","objective":"Resolver adições e subtrações com e sem reagrupamento e aplicá-las em problemas.","prerequisites":["mat-sistema-decimal"],"next":["mat-multiplicacao"],"skills":{"adicao":"Adição","reagrupar":"Vai um e empréstimo","subtracao":"Subtração","problemas":"Problemas com adição e subtração"},"blocks":[{"skill":"adicao","title":"Somar é juntar","text":"Na adição juntamos quantidades. Os números somados são as parcelas e o resultado é a soma (ou total). A ordem das parcelas não muda a soma.","example":"12 + 5 = 17: 12 figurinhas mais 5 figurinhas dão 17.","variants":{"simples":"Somar é juntar tudo e contar quanto ficou.","exemplo":"Você tem 8 balas e ganha 4. Agora tem 8 + 4 = 12 balas.","passos":"1. Escreva os números um embaixo do outro, unidade embaixo de unidade.\n2. Some a coluna das unidades.\n3. Some a coluna das dezenas.\n4. Escreva o resultado."},"id":"b1"},{"skill":"reagrupar","title":"Vai um e empresta","text":"Quando a soma de uma coluna passa de 9, trocamos 10 unidades por 1 dezena (\"vai um\"). Na subtração, se não dá para tirar, pegamos 1 dezena emprestada, que vira 10 unidades.","example":"48 + 35: 8 + 5 = 13 → escreve 3, vai 1. Depois 4 + 3 + 1 = 8. Resultado: 83.","variants":{"simples":"Passou de 9? Fica o número da direita e o 1 \"vai\" para a próxima coluna.","exemplo":"É como trocar 10 moedas de R$ 1 por uma nota de R$ 10: a quantidade de dinheiro é a mesma.","passos":"1. Some (ou subtraia) as unidades.\n2. Se na soma deu 10 ou mais, escreva só as unidades e leve 1 para as dezenas.\n3. Na subtração, se o de cima é menor, pegue 1 dezena emprestada: ela vale 10 unidades.\n4. Continue nas dezenas lembrando do que foi levado ou emprestado."},"id":"b2"},{"skill":"subtracao","title":"Subtrair é tirar ou comparar","text":"Na subtração tiramos uma quantidade de outra ou descobrimos a diferença entre elas. O resultado se chama diferença (ou resto). Para conferir, somamos o resultado com o número tirado.","example":"52 − 17 = 35. Conferindo: 35 + 17 = 52 ✓.","variants":{"simples":"Subtrair é tirar e ver quanto sobra.","exemplo":"Tinha R$ 20 e gastei R$ 13. Sobraram 20 − 13 = R$ 7 de troco.","passos":"1. Coloque o maior número em cima.\n2. Subtraia as unidades (empreste se precisar).\n3. Subtraia as dezenas.\n4. Confira somando o resultado com o número de baixo."},"id":"b3"},{"skill":"problemas","title":"Qual conta usar?","text":"Palavras como \"juntar\", \"ganhar\", \"total\" indicam adição. \"Tirar\", \"gastar\", \"sobrou\", \"quanto falta\", \"diferença\" indicam subtração.","example":"Pedro tem 15 anos e a irmã tem 9. A diferença de idade é 15 − 9 = 6 anos.","variants":{"simples":"Juntou? É mais. Tirou ou quer saber quanto falta? É menos.","exemplo":"No supermercado: somamos os preços para saber o total e subtraímos do dinheiro para saber o troco.","passos":"1. Leia o problema com calma.\n2. Descubra o que ele pergunta.\n3. Veja se a situação é de juntar (mais) ou tirar/comparar (menos).\n4. Faça a conta e responda com a unidade (balas, reais…)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"adicao","prompt":"Quanto é 12 + 5?","options":["7","17","15","125"],"answer":1,"hints":["Comece pelo 12.","Conte mais 5.","13, 14, 15, 16…"],"explanation":"12 + 5 = 17.","id":"q1"},{"type":"fill","difficulty":1,"skill":"subtracao","prompt":"Quanto é 20 − 13?","answers":["7"],"hints":["Pense no troco de 20.","Quanto falta de 13 para 20?","13 + ? = 20."],"explanation":"20 − 13 = 7, porque 13 + 7 = 20.","id":"q2"},{"type":"tf","difficulty":1,"skill":"adicao","prompt":"3 + 8 dá o mesmo resultado que 8 + 3.","answer":true,"hints":["A ordem muda a soma?","Faça as duas contas.","As duas dão 11."],"explanation":"Verdadeiro: a ordem das parcelas não altera a soma.","id":"q3"},{"type":"mc","difficulty":2,"skill":"reagrupar","prompt":"Quanto é 48 + 35?","options":["73","83","713","82"],"answer":1,"hints":["8 + 5 passa de 9.","8 + 5 = 13: escreve 3 e vai 1.","4 + 3 + 1 = ?"],"explanation":"8 + 5 = 13 (vai 1); 4 + 3 + 1 = 8. Total 83.","id":"q4"},{"type":"mc","difficulty":2,"skill":"reagrupar","prompt":"Quanto é 52 − 17?","options":["45","35","25","39"],"answer":1,"hints":["2 − 7 não dá: precisa emprestar.","12 − 7 = 5.","Nas dezenas: 4 − 1."],"explanation":"12 − 7 = 5; 4 − 1 = 3. Resultado 35.","id":"q5"},{"type":"fill","difficulty":2,"skill":"subtracao","prompt":"Para conferir 52 − 17 = 35, somamos 35 + 17. O resultado deve ser ____.","answers":["52"],"hints":["A conta de conferir desfaz a subtração.","Some 35 e 17.","Deve voltar ao número inicial."],"explanation":"35 + 17 = 52: a conta está certa.","id":"q6"},{"type":"match","difficulty":2,"skill":"problemas","prompt":"Ligue cada situação à conta certa.","pairs":[["Ganhei mais figurinhas","Adição"],["Gastei parte do dinheiro","Subtração"],["Quanto falta para chegar a 100?","Subtração (quanto falta)"],["Qual o total de alunos das duas turmas?","Adição (total)"]],"hints":["Ganhar e total: juntar.","Gastar: tirar.","Quanto falta: diferença."],"explanation":"Juntar/total → adição · tirar/quanto falta → subtração.","id":"q7"},{"type":"mc","difficulty":2,"skill":"problemas","prompt":"Pedro tem 15 anos e a irmã tem 9. Qual é a diferença de idade?","options":["24 anos","6 anos","5 anos","9 anos"],"answer":1,"hints":["Diferença indica qual conta?","Subtração.","15 − 9."],"explanation":"15 − 9 = 6 anos.","id":"q8"},{"type":"fill","difficulty":3,"skill":"reagrupar","prompt":"Quanto é 305 − 128?","answers":["177"],"hints":["5 − 8 não dá: empreste das dezenas.","As dezenas estão zeradas: empreste das centenas.","305 = 2 centenas + 9 dezenas + 15 unidades."],"explanation":"15 − 8 = 7; 9 − 2 = 7; 2 − 1 = 1 → 177. Confira: 177 + 128 = 305.","id":"q9"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Uma escola tem 238 alunos de manhã e 175 à tarde. Quantos alunos tem ao todo?","options":["413","313","403","63"],"answer":0,"hints":["\"Ao todo\" pede adição.","8 + 5 = 13, vai 1.","3 + 7 + 1 = 11, vai 1; 2 + 1 + 1 = 4."],"explanation":"238 + 175 = 413 alunos.","id":"q10"},{"type":"tf","difficulty":3,"skill":"subtracao","prompt":"Na subtração, a ordem dos números não importa: 9 − 4 é igual a 4 − 9.","answer":false,"hints":["Tente tirar 9 de 4 com objetos.","Não dá para tirar 9 de 4 em números naturais.","Na subtração a ordem importa."],"explanation":"Falso: 9 − 4 = 5, mas 4 − 9 não é 5. Na subtração a ordem importa.","id":"q11"},{"type":"open","difficulty":3,"skill":"problemas","prompt":"Invente um problema de subtração sobre troco e resolva.","modelAnswer":"Exemplo: comprei um lanche de R$ 13 e paguei com R$ 20. O troco é 20 − 13 = R$ 7.","keywords":["troco","paguei","custa","sobrou","menos","reais"],"hints":["Pense numa compra.","Quanto custou e quanto você pagou?","O troco é a diferença."],"explanation":"Troco = valor pago − preço.","id":"q12"}],"review":["Adição junta: parcelas → soma","Passou de 9 na coluna: \"vai um\"","Subtração tira ou compara; empreste quando precisar","Confira a subtração somando"],"relatedQuestions":["Como fazer conta de mais com vai um?","Como fazer conta de menos emprestando?","Como saber se é conta de mais ou de menos?"],"equivalentQuestions":["como somar numeros","como fazer conta de mais","o que é vai um","como fazer conta de menos","como subtrair emprestando","por que emprestar na conta de menos","como fazer 52 menos 17","como calcular o troco","como saber quanto falta","o que é diferença na matematica","como conferir uma subtração","o que são parcelas","qual o nome do resultado da soma","como armar a conta de mais","como somar numeros grandes","problema de somar ou subtrair como saber","me explica adição","me explica subtração","nao sei fazer conta de menos","como fazer conta de menos com zero","como calcular o total de duas coisas","soma e subtração exemplo"],"commonDoubts":[{"q":"Por que na conta de menos eu \"empresto\"?","a":"Porque trocamos 1 dezena por 10 unidades. O número continua o mesmo, só está escrito de outra forma para dar para tirar."},{"q":"Como sei se o problema é de mais ou de menos?","a":"Juntar, ganhar, total → mais. Tirar, gastar, sobrar, quanto falta, diferença → menos."}],"commonErrors":["Esquecer de somar o \"vai um\" na coluna seguinte","Tirar o menor do maior dentro da coluna (fazer 7 − 2 em vez de 12 − 7)","Desalinhar unidades e dezenas ao armar a conta"],"formulas":[{"name":"Prova da subtração","expression":"diferença + subtraendo = minuendo","variables":[{"symbol":"minuendo","meaning":"número de onde se tira"},{"symbol":"subtraendo","meaning":"número que se tira"},{"symbol":"diferença","meaning":"resultado"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-multiplicacao","subject":"matematica","title":"Multiplicação e tabuada","levels":["fund1"],"grade":"2º ao 4º ano","topic":"Operações","subtopic":"Multiplicação","aliases":["multiplicacao","tabuada","vezes","multiplicar","conta de vezes","produto","dobro","triplo"],"summary":"Entenda a multiplicação como soma de parcelas iguais e aprenda truques da tabuada.","intro":"Multiplicar é um jeito rápido de somar números iguais. Vamos descobrir como!","objective":"Compreender a multiplicação como adição de parcelas iguais, usar a tabuada e resolver problemas.","prerequisites":["mat-adicao-subtracao"],"next":["mat-divisao"],"skills":{"conceito":"Multiplicação como soma repetida","tabuada":"Tabuada","propriedades":"Propriedades da multiplicação","problemas":"Problemas com multiplicação"},"blocks":[{"skill":"conceito","title":"Multiplicar é somar parcelas iguais","text":"Quando somamos o mesmo número várias vezes, usamos a multiplicação. 3 × 4 quer dizer \"3 grupos de 4\": 4 + 4 + 4 = 12. Os números multiplicados são os fatores e o resultado é o produto.","example":"Três pacotes com 4 figurinhas cada: 3 × 4 = 12 figurinhas.","variants":{"simples":"Vezes é contar grupos iguais. 2 × 5 são dois grupos de 5 coisas: 10 coisas.","exemplo":"Uma bicicleta tem 2 rodas. 5 bicicletas têm 5 × 2 = 10 rodas.","passos":"1. Descubra quantos grupos existem.\n2. Descubra quantos há em cada grupo.\n3. Multiplique os dois números.\n4. Se quiser conferir, some o grupo tantas vezes quanto indicado."},"id":"b1"},{"skill":"tabuada","title":"Truques da tabuada","text":"Na tabuada do 2, é só dobrar. Na do 10, coloque um zero no fim. Na do 5, os resultados terminam sempre em 0 ou 5. Na do 9, os algarismos do resultado somam 9 (até 9 × 10).","example":"7 × 2 = 14 · 6 × 10 = 60 · 5 × 3 = 15 · 9 × 4 = 36 (3 + 6 = 9).","variants":{"simples":"× 2 é o dobro. × 10 é pôr um zero no fim. × 5 termina em 0 ou 5.","exemplo":"Para saber quantos dedos há em 6 mãos: 6 × 5 = 30.","passos":"1. Veja se o número é 2, 5, 9 ou 10 — use o truque.\n2. Se não souber, troque a ordem (7 × 3 = 3 × 7).\n3. Ou quebre: 7 × 6 = 7 × 5 + 7 = 35 + 7 = 42.\n4. Confira com a soma repetida."},"id":"b2"},{"skill":"propriedades","title":"Regras que ajudam","text":"Trocar a ordem dos fatores não muda o produto: 3 × 4 = 4 × 3. Qualquer número vezes 1 é ele mesmo, e qualquer número vezes 0 é zero.","example":"8 × 1 = 8 · 8 × 0 = 0 · 2 × 9 = 9 × 2 = 18.","variants":{"simples":"3 × 4 e 4 × 3 dão o mesmo: 12. Vezes 1 não muda nada. Vezes 0 dá sempre 0.","exemplo":"3 fileiras de 4 cadeiras ou 4 fileiras de 3: são 12 cadeiras do mesmo jeito.","passos":"1. Se ficar mais fácil, troque a ordem dos fatores.\n2. Viu × 1? O resultado é o próprio número.\n3. Viu × 0? O resultado é 0.\n4. Use isso para conferir contas grandes."},"id":"b3"},{"skill":"problemas","title":"Usando no dia a dia","text":"Para resolver um problema, procure grupos iguais: quantos grupos existem e quantas coisas há em cada grupo. \"Dobro\" é × 2 e \"triplo\" é × 3.","example":"Uma caixa tem 6 ovos. Em 5 caixas há 5 × 6 = 30 ovos.","variants":{"simples":"Pergunte: quantos grupos? Quantos em cada grupo? Depois faça a conta de vezes.","exemplo":"Um ingresso custa R$ 8. Para 4 pessoas: 4 × 8 = R$ 32.","passos":"1. Leia e encontre os grupos iguais.\n2. Anote quantos grupos e quantos por grupo.\n3. Multiplique.\n4. Responda com a unidade (ovos, reais…)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"conceito","prompt":"4 + 4 + 4 é o mesmo que:","options":["4 × 4","3 × 4","4 + 3","12 × 4"],"answer":1,"hints":["Conte quantas vezes o 4 aparece.","O 4 aparece 3 vezes.","3 grupos de 4."],"explanation":"São 3 parcelas iguais a 4: 3 × 4 = 12.","id":"q1"},{"type":"fill","difficulty":1,"skill":"tabuada","prompt":"Quanto é 7 × 2?","answers":["14"],"hints":["× 2 é o dobro.","Qual é o dobro de 7?","7 + 7."],"explanation":"7 × 2 = 14, o dobro de 7.","id":"q2"},{"type":"mc","difficulty":1,"skill":"tabuada","prompt":"Quanto é 6 × 10?","options":["16","60","600","61"],"answer":1,"hints":["Na tabuada do 10 tem um truque.","Coloque um zero no fim.","6 com um zero."],"explanation":"6 × 10 = 60.","id":"q3"},{"type":"tf","difficulty":1,"skill":"propriedades","prompt":"3 × 5 dá o mesmo resultado que 5 × 3.","answer":true,"hints":["A ordem muda o resultado da multiplicação?","Faça as duas contas.","15 e 15."],"explanation":"Verdadeiro: a ordem dos fatores não altera o produto.","id":"q4"},{"type":"mc","difficulty":2,"skill":"propriedades","prompt":"Quanto é 9 × 0?","options":["9","0","90","1"],"answer":1,"hints":["Pense em 9 grupos com nada dentro.","Quantas coisas há no total?","Nenhuma."],"explanation":"Qualquer número vezes 0 dá 0.","id":"q5"},{"type":"fill","difficulty":2,"skill":"problemas","prompt":"Uma caixa tem 6 ovos. Quantos ovos há em 5 caixas?","answers":["30"],"hints":["Quantos grupos? Quantos em cada?","5 caixas com 6 ovos.","5 × 6."],"explanation":"5 × 6 = 30 ovos.","id":"q6"},{"type":"match","difficulty":2,"skill":"tabuada","prompt":"Ligue cada conta ao resultado.","pairs":[["2 × 8","16"],["5 × 4","20"],["3 × 3","9"],["10 × 7","70"]],"hints":["Comece pela do 10.","5 × 4 termina em 0.","2 × 8 é o dobro de 8."],"explanation":"2 × 8 = 16 · 5 × 4 = 20 · 3 × 3 = 9 · 10 × 7 = 70.","id":"q7"},{"type":"tf","difficulty":2,"skill":"tabuada","prompt":"Todos os resultados da tabuada do 5 terminam em 0 ou 5.","answer":true,"hints":["Teste alguns: 5, 10, 15…","Veja o último algarismo.","Só aparecem 0 e 5."],"explanation":"Verdadeiro: 5, 10, 15, 20, 25…","id":"q8"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Uma sala tem 4 fileiras com 7 cadeiras cada. Quantas cadeiras há?","options":["11","28","24","47"],"answer":1,"hints":["São grupos iguais.","4 grupos de 7.","4 × 7."],"explanation":"4 × 7 = 28 cadeiras.","id":"q9"},{"type":"fill","difficulty":3,"skill":"tabuada","prompt":"Quanto é 8 × 7?","answers":["56"],"hints":["Pense em 7 × 8.","7 × 7 = 49.","49 + 7."],"explanation":"8 × 7 = 56.","id":"q10"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Ana tem 6 anos. Seu pai tem o quíntuplo da idade dela. Quantos anos tem o pai?","options":["11","30","36","25"],"answer":1,"hints":["Quíntuplo = 5 vezes.","Multiplique a idade de Ana por 5.","6 × 5."],"explanation":"Quíntuplo de 6 = 6 × 5 = 30 anos.","id":"q11"},{"type":"open","difficulty":3,"skill":"conceito","prompt":"Explique com suas palavras por que 3 × 4 = 12, sem usar a tabuada.","modelAnswer":"Porque 3 × 4 significa três grupos de 4 e, somando 4 + 4 + 4, obtemos 12.","keywords":["grupos","soma","somar","4 + 4","vezes"],"hints":["O que \"3 vezes 4\" significa?","Três grupos de quê?","Some esses grupos."],"explanation":"Multiplicar é somar parcelas iguais: 4 + 4 + 4 = 12.","id":"q12"}],"review":["Multiplicar = somar parcelas iguais (fatores → produto)","× 2 é o dobro · × 10 põe um zero","A ordem não muda o resultado","× 1 não muda · × 0 dá zero"],"relatedQuestions":["Como aprender a tabuada?","O que é multiplicar?","Como fazer conta de vezes?"],"equivalentQuestions":["como decorar a tabuada","truque para tabuada","quanto é 7 vezes 8","como fazer conta de vezes","o que significa 3 vezes 4","o que é produto na matematica","o que são fatores da multiplicação","como multiplicar numeros grandes","qualquer numero vezes zero da quanto","a ordem muda na multiplicação","o que é dobro e triplo","como calcular o quíntuplo","tabuada do 9 truque","tabuada do 7 como aprender","como saber quantas coisas tem em varias caixas","problema de multiplicação exemplo","me explica multiplicação","multiplicação é soma repetida","por que 5 vezes 0 da zero","como fazer multiplicação de cabeça","quando usar conta de vezes no problema"],"commonDoubts":[{"q":"Por que qualquer número vezes zero dá zero?","a":"Porque são grupos vazios: 5 × 0 é \"5 grupos de nada\", que dá nada."},{"q":"Não decorei a tabuada. E agora?","a":"Use a soma repetida ou quebre a conta: 7 × 6 = 7 × 5 + 7 = 35 + 7 = 42."}],"commonErrors":["Confundir × 0 com × 1 (8 × 0 é 0, e 8 × 1 é 8)","Somar em vez de multiplicar: fazer 4 + 7 quando o problema pede 4 grupos de 7"],"formulas":[{"name":"Multiplicação","expression":"a × b = produto","variables":[{"symbol":"a","meaning":"número de grupos"},{"symbol":"b","meaning":"quantidade em cada grupo"},{"symbol":"produto","meaning":"total"}],"conditions":"quando os grupos têm o mesmo tamanho"}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-divisao","subject":"matematica","title":"Divisão","levels":["fund1","fund2"],"grade":"3º ao 5º ano","topic":"Operações","subtopic":"Divisão","aliases":["divisao","dividir","conta de dividir","resto da divisao","dividendo divisor quociente","divisao exata","repartir","metade","terca parte"],"summary":"Aprenda a dividir em partes iguais, entenda o resto e confira a divisão com a multiplicação.","intro":"Dividir é repartir em partes iguais ou descobrir quantas vezes uma quantidade cabe em outra.","objective":"Resolver divisões exatas e não exatas, interpretar o resto e usar a divisão em problemas.","prerequisites":["mat-multiplicacao"],"next":["mat-fracoes","mat-mmc-mdc"],"skills":{"conceito":"Ideia de dividir","termos":"Termos e resto","algoritmo":"Conta de dividir","problemas":"Problemas com divisão"},"blocks":[{"skill":"conceito","title":"Repartir em partes iguais","text":"Dividir é repartir uma quantidade em partes iguais, ou descobrir quantas vezes um número cabe em outro. A divisão é a operação inversa da multiplicação.","example":"12 balas para 3 crianças: 12 ÷ 3 = 4 balas para cada uma, porque 3 × 4 = 12.","variants":{"simples":"Dividir é dar a mesma quantidade para todo mundo.","exemplo":"Uma pizza de 8 pedaços dividida entre 4 amigos: cada um come 8 ÷ 4 = 2 pedaços.","passos":"1. Veja quanto há no total.\n2. Veja em quantas partes vai dividir.\n3. Pergunte: que número vezes as partes dá o total?\n4. Esse número é a resposta."},"id":"b1"},{"skill":"termos","title":"Dividendo, divisor, quociente e resto","text":"Em 17 ÷ 5: 17 é o dividendo, 5 é o divisor, 3 é o quociente e 2 é o resto. Quando o resto é 0, a divisão é exata. O resto é sempre menor que o divisor.","example":"17 ÷ 5 = 3 e sobra 2, porque 5 × 3 + 2 = 17.","variants":{"simples":"O que sobra e não dá para repartir é o resto.","exemplo":"17 figurinhas para 5 amigos: cada um ganha 3 e sobram 2 figurinhas.","passos":"1. Veja quantas vezes o divisor cabe no dividendo.\n2. Multiplique para ver quanto foi usado.\n3. Subtraia: o que sobrar é o resto.\n4. Confira: divisor × quociente + resto = dividendo."},"id":"b2"},{"skill":"algoritmo","title":"A conta armada","text":"Na conta armada dividimos parte por parte, da esquerda para a direita: dividimos, multiplicamos, subtraímos e \"baixamos\" o próximo algarismo.","example":"84 ÷ 4: 8 ÷ 4 = 2; baixa o 4; 4 ÷ 4 = 1. Resultado 21.","variants":{"simples":"Divida um algarismo de cada vez, começando pela esquerda.","exemplo":"Dividir R$ 96 entre 3 pessoas: 9 ÷ 3 = 3 e 6 ÷ 3 = 2 → R$ 32 para cada.","passos":"1. Pegue o primeiro algarismo (ou os dois primeiros, se precisar).\n2. Divida e escreva no quociente.\n3. Multiplique e subtraia.\n4. Baixe o próximo algarismo e repita até acabar."},"id":"b3"},{"skill":"problemas","title":"Quando dividir","text":"Use a divisão quando o problema fala em repartir igualmente, \"cada um\", \"metade\" (÷ 2), \"terça parte\" (÷ 3) ou \"quantos grupos cabem\".","example":"Uma van leva 9 pessoas. Para 30 pessoas: 30 ÷ 9 = 3 e resto 3 → são necessárias 4 vans.","variants":{"simples":"\"Cada um recebe quanto?\" → divide.","exemplo":"Um livro de 60 páginas lido em 5 dias iguais: 60 ÷ 5 = 12 páginas por dia.","passos":"1. Encontre o total e o número de partes.\n2. Divida.\n3. Pense no resto: ele sobra, ou exige mais um grupo?\n4. Responda à pergunta do problema."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"conceito","prompt":"12 balas divididas igualmente entre 3 crianças. Quantas balas cada uma recebe?","options":["3","4","9","36"],"answer":1,"hints":["Que número vezes 3 dá 12?","3 × ? = 12.","3 × 4 = 12."],"explanation":"12 ÷ 3 = 4.","id":"q1"},{"type":"fill","difficulty":1,"skill":"conceito","prompt":"Quanto é 20 ÷ 5?","answers":["4"],"hints":["5 × ? = 20.","Conte de 5 em 5 até 20.","5, 10, 15, 20."],"explanation":"20 ÷ 5 = 4.","id":"q2"},{"type":"tf","difficulty":1,"skill":"termos","prompt":"Numa divisão exata, o resto é zero.","answer":true,"hints":["Exata = não sobra nada.","O que é o resto?","O que sobra."],"explanation":"Verdadeiro.","id":"q3"},{"type":"match","difficulty":2,"skill":"termos","prompt":"Em 17 ÷ 5 = 3, resto 2, ligue cada número ao nome.","pairs":[["17","Dividendo"],["5","Divisor"],["3","Quociente"],["2","Resto"]],"hints":["O que está sendo dividido é o dividendo.","O resultado é o quociente.","O que sobra é o resto."],"explanation":"17 dividendo · 5 divisor · 3 quociente · 2 resto.","id":"q4"},{"type":"mc","difficulty":2,"skill":"algoritmo","prompt":"Quanto é 84 ÷ 4?","options":["12","21","24","41"],"answer":1,"hints":["Comece pelo 8.","8 ÷ 4 = 2; depois 4 ÷ 4.","Junte: 2 e 1."],"explanation":"84 ÷ 4 = 21. Confira: 4 × 21 = 84.","id":"q5"},{"type":"fill","difficulty":2,"skill":"termos","prompt":"Qual é o resto de 17 ÷ 5?","answers":["2"],"hints":["Quantas vezes o 5 cabe no 17?","3 vezes: 15.","17 − 15."],"explanation":"5 × 3 = 15; 17 − 15 = 2.","id":"q6"},{"type":"tf","difficulty":2,"skill":"termos","prompt":"O resto pode ser maior que o divisor.","answer":false,"hints":["Se o resto fosse maior, caberia mais uma vez?","Sim, caberia.","Então a divisão não teria terminado."],"explanation":"Falso: o resto é sempre menor que o divisor.","id":"q7"},{"type":"mc","difficulty":2,"skill":"problemas","prompt":"Um livro de 60 páginas será lido em 5 dias, a mesma quantidade por dia. Quantas páginas por dia?","options":["55","12","15","300"],"answer":1,"hints":["\"A mesma quantidade por dia\" é repartir.","60 ÷ 5.","5 × 12 = 60."],"explanation":"60 ÷ 5 = 12 páginas por dia.","id":"q8"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Uma van leva 9 pessoas. Quantas vans são necessárias para 30 pessoas?","options":["3","4","21","270"],"answer":1,"hints":["30 ÷ 9 = 3 e sobra algo.","O resto é 3 pessoas.","Essas 3 pessoas também precisam ir!"],"explanation":"30 ÷ 9 = 3 resto 3: as 3 pessoas que sobram precisam de mais uma van → 4 vans.","id":"q9"},{"type":"fill","difficulty":3,"skill":"algoritmo","prompt":"Quanto é 156 ÷ 12?","answers":["13"],"hints":["12 cabe uma vez em 15.","15 − 12 = 3; baixe o 6: 36.","36 ÷ 12 = 3."],"explanation":"156 ÷ 12 = 13. Confira: 12 × 13 = 156.","id":"q10"},{"type":"order","difficulty":2,"skill":"algoritmo","prompt":"Coloque os passos da conta de dividir na ordem.","items":["Dividir","Multiplicar","Subtrair","Baixar o próximo algarismo"],"hints":["Primeiro vemos quantas vezes cabe.","Depois calculamos quanto foi usado.","Por fim, sobra algo e baixamos o próximo."],"explanation":"Dividir → multiplicar → subtrair → baixar, e repetir.","id":"q11"},{"type":"open","difficulty":3,"skill":"termos","prompt":"Como você confere se 47 ÷ 6 = 7, resto 5, está certo?","modelAnswer":"Multiplico o divisor pelo quociente e somo o resto: 6 × 7 + 5 = 42 + 5 = 47. Como deu o dividendo, está certo.","keywords":["multiplic","resto","soma","47","dividendo"],"hints":["A divisão é o contrário de qual conta?","Multiplique 6 × 7.","Some o resto."],"explanation":"Divisor × quociente + resto = dividendo.","id":"q12"}],"review":["Dividir = repartir igualmente (inverso da multiplicação)","Dividendo ÷ divisor = quociente (+ resto)","Resto é sempre menor que o divisor","Prova: divisor × quociente + resto = dividendo"],"relatedQuestions":["Como fazer conta de dividir?","O que é o resto da divisão?","Como conferir uma divisão?"],"equivalentQuestions":["como dividir numeros","como fazer conta de dividir armada","o que é quociente","o que é dividendo e divisor","o que fazer com o resto","o que é divisão exata","como dividir por 12","como saber quanto cada um recebe","como repartir igualmente","quanto é 84 dividido por 4","como fazer a prova real da divisão","o resto pode ser maior que o divisor","o que é metade de um número","como calcular a terça parte","divisão com resto exemplo","quantas vans preciso problema de divisão","me explica divisão","não sei dividir","dividir é o contrário de multiplicar","como baixar o numero na divisão","divisão com dois algarismos no divisor"],"commonDoubts":[{"q":"Posso dividir por zero?","a":"Não. Não existe número que multiplicado por 0 dê, por exemplo, 5 — por isso a divisão por zero não é definida."},{"q":"O que faço com o resto no problema?","a":"Depende da pergunta: às vezes ele sobra (figurinhas), às vezes exige mais um grupo (vans, ônibus)."}],"commonErrors":["Esquecer de \"baixar\" um algarismo e pular um zero no quociente (ex.: 612 ÷ 6 = 102, não 12)","Deixar resto maior que o divisor","Ignorar o resto em problemas que precisam de mais um grupo"],"formulas":[{"name":"Relação fundamental da divisão","expression":"D = d × q + r","variables":[{"symbol":"D","meaning":"dividendo"},{"symbol":"d","meaning":"divisor (diferente de zero)"},{"symbol":"q","meaning":"quociente"},{"symbol":"r","meaning":"resto (0 ≤ r < d)"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-formas-geometricas","subject":"matematica","title":"Figuras geométricas planas e espaciais","levels":["fund1"],"grade":"1º ao 5º ano","topic":"Geometria","subtopic":"Figuras planas e sólidos","aliases":["figuras geometricas","formas geometricas","triangulo quadrado retangulo circulo","solidos geometricos","cubo esfera cilindro piramide","faces vertices arestas","poligonos","geometria espacial basica"],"summary":"Reconheça figuras planas (triângulo, quadrado…) e sólidos (cubo, esfera…), com seus lados, faces, vértices e arestas.","intro":"Olhe ao redor: uma janela lembra um retângulo, uma bola é uma esfera. A geometria está em tudo!","objective":"Identificar e classificar figuras planas e sólidos geométricos pelos seus elementos.","next":["mat-area-perimetro","mat-angulos"],"skills":{"planas":"Figuras planas","poligonos":"Polígonos: lados e vértices","solidos":"Sólidos geométricos","elementos":"Faces, arestas e vértices"},"blocks":[{"skill":"planas","title":"Figuras planas","text":"Figuras planas são \"achatadas\": têm comprimento e largura, mas não têm altura. Exemplos: triângulo, quadrado, retângulo e círculo.","example":"O desenho de uma placa de trânsito no papel é uma figura plana.","variants":{"simples":"Plana é a figura que dá para desenhar inteira no papel.","exemplo":"Uma folha de sulfite lembra um retângulo; o fundo de um copo lembra um círculo.","passos":"1. Veja se a figura é \"achatada\".\n2. Conte os lados.\n3. Veja se os lados são retos ou curvos.\n4. Dê o nome: 3 lados triângulo, 4 lados quadrilátero, sem lados retos círculo."},"id":"b1"},{"skill":"poligonos","title":"Polígonos: lados e vértices","text":"Polígonos são figuras planas fechadas formadas só por segmentos de reta (lados). O ponto onde dois lados se encontram é um vértice. O círculo não é polígono, pois não tem lados retos.","example":"Triângulo: 3 lados e 3 vértices. Quadrado: 4 lados iguais e 4 ângulos retos. Pentágono: 5 lados. Hexágono: 6 lados.","variants":{"simples":"Conte os lados: 3 é triângulo, 4 é quadrilátero, 5 é pentágono, 6 é hexágono.","exemplo":"Os favos de mel das abelhas têm formato de hexágono: 6 lados.","passos":"1. Confira se a figura é fechada e tem só lados retos.\n2. Conte os lados.\n3. O número de vértices é igual ao de lados.\n4. Use o nome: tri (3), quadri (4), penta (5), hexa (6)."},"id":"b2"},{"skill":"solidos","title":"Sólidos geométricos","text":"Sólidos (figuras espaciais) têm comprimento, largura e altura: ocupam lugar no espaço. Os que têm só superfícies planas são poliedros (cubo, pirâmide, prisma). Os que têm parte arredondada são corpos redondos (esfera, cilindro, cone).","example":"Um dado é um cubo; uma lata é um cilindro; uma casquinha de sorvete lembra um cone; uma bola é uma esfera.","variants":{"simples":"Sólido é o que dá para pegar na mão, como um dado ou uma bola.","exemplo":"Na cozinha: caixa de leite (prisma), lata de milho (cilindro), laranja (esfera).","passos":"1. Veja se o objeto rola.\n2. Se rola, é corpo redondo (esfera, cilindro, cone).\n3. Se não rola e só tem partes planas, é poliedro.\n4. Compare com os modelos: cubo, prisma, pirâmide."},"id":"b3"},{"skill":"elementos","title":"Faces, arestas e vértices","text":"Nos poliedros, cada superfície plana é uma face, cada \"quina\" onde duas faces se encontram é uma aresta e cada ponta é um vértice. O cubo tem 6 faces, 12 arestas e 8 vértices.","example":"Um dado tem 6 faces (os lados com números), 12 arestas e 8 pontas (vértices).","variants":{"simples":"Face é o lado chato, aresta é a dobra, vértice é a ponta.","exemplo":"Numa caixa de sapato: as tampas e os lados são faces, as dobras são arestas e os cantos são vértices.","passos":"1. Conte as superfícies planas: faces.\n2. Conte as \"linhas\" onde as faces se juntam: arestas.\n3. Conte as pontas: vértices.\n4. Confira no cubo: 6, 12 e 8."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"poligonos","prompt":"Quantos lados tem um triângulo?","options":["2","3","4","5"],"answer":1,"hints":["\"Tri\" quer dizer…","Triciclo tem 3 rodas.","Três."],"explanation":"O triângulo tem 3 lados e 3 vértices.","id":"q1"},{"type":"mc","difficulty":1,"skill":"solidos","prompt":"Uma bola de futebol lembra qual sólido?","options":["Cubo","Cilindro","Esfera","Pirâmide"],"answer":2,"hints":["Ela rola para todos os lados.","Não tem nenhuma parte plana.","É toda redonda."],"explanation":"A bola lembra uma esfera.","id":"q2"},{"type":"tf","difficulty":1,"skill":"poligonos","prompt":"O círculo é um polígono.","answer":false,"hints":["Polígono tem lados retos.","O círculo tem lados retos?","Não, é todo curvo."],"explanation":"Falso: o círculo não tem lados retos, então não é polígono.","id":"q3"},{"type":"match","difficulty":2,"skill":"solidos","prompt":"Ligue o objeto ao sólido que ele lembra.","pairs":[["Dado","Cubo"],["Lata de refrigerante","Cilindro"],["Casquinha de sorvete","Cone"],["Laranja","Esfera"]],"hints":["O dado tem 6 faces iguais.","A lata tem duas bases redondas.","A casquinha tem uma ponta."],"explanation":"Dado–cubo · lata–cilindro · casquinha–cone · laranja–esfera.","id":"q4"},{"type":"fill","difficulty":2,"skill":"elementos","prompt":"Quantas faces tem um cubo?","answers":["6","seis"],"hints":["Pense num dado.","Os números vão de 1 a…","Cada número está numa face."],"explanation":"O cubo tem 6 faces.","id":"q5"},{"type":"mc","difficulty":2,"skill":"poligonos","prompt":"Uma figura plana com 6 lados se chama:","options":["Pentágono","Hexágono","Octógono","Quadrilátero"],"answer":1,"hints":["Pense nos favos de mel.","\"Hexa\" significa 6.","Hexa + gono."],"explanation":"Hexágono: 6 lados.","id":"q6"},{"type":"tf","difficulty":2,"skill":"planas","prompt":"Um quadrado tem 4 lados iguais.","answer":true,"hints":["Compare o quadrado com o retângulo.","No retângulo, os lados podem ser diferentes.","No quadrado, todos são iguais."],"explanation":"Verdadeiro: 4 lados iguais e 4 ângulos retos.","id":"q7"},{"type":"mc","difficulty":2,"skill":"solidos","prompt":"Qual destes sólidos NÃO rola?","options":["Esfera","Cilindro","Cone","Cubo"],"answer":3,"hints":["Corpos redondos rolam.","Quem só tem faces planas não rola.","O dado rola ou tomba?"],"explanation":"O cubo só tem faces planas: não rola.","id":"q8"},{"type":"fill","difficulty":3,"skill":"elementos","prompt":"Quantos vértices (pontas) tem um cubo?","answers":["8","oito"],"hints":["Conte as pontas de cima.","São 4 em cima.","E mais 4 embaixo."],"explanation":"4 em cima + 4 embaixo = 8 vértices.","id":"q9"},{"type":"mc","difficulty":3,"skill":"elementos","prompt":"Quantas arestas tem um cubo?","options":["6","8","12","24"],"answer":2,"hints":["Aresta é a \"dobra\" entre duas faces.","Conte 4 em cima e 4 embaixo.","Mais as 4 que ligam cima e embaixo."],"explanation":"4 + 4 + 4 = 12 arestas.","id":"q10"},{"type":"mc","difficulty":3,"skill":"poligonos","prompt":"Quantos vértices tem um pentágono?","options":["4","5","6","10"],"answer":1,"hints":["Num polígono, vértices e lados são iguais em número.","\"Penta\" = 5.","5 lados → 5 vértices."],"explanation":"Pentágono: 5 lados e 5 vértices.","id":"q11"},{"type":"open","difficulty":3,"skill":"solidos","prompt":"Qual é a diferença entre uma figura plana e um sólido geométrico?","modelAnswer":"A figura plana tem só comprimento e largura e pode ser desenhada inteira no papel. O sólido tem também altura: ocupa lugar no espaço, como um dado ou uma bola.","keywords":["altura","espaco","papel","plana","tres dimens","ocupa"],"hints":["Pense num quadrado e num cubo.","Qual deles dá para segurar?","Fale de altura ou de ocupar espaço."],"explanation":"Plana: 2 dimensões. Sólido: 3 dimensões.","id":"q12"}],"review":["Planas: triângulo, quadrado, retângulo, círculo","Polígonos têm lados retos; nº de lados = nº de vértices","Sólidos: poliedros (não rolam) e corpos redondos (rolam)","Cubo: 6 faces, 12 arestas, 8 vértices"],"relatedQuestions":["Quais são as figuras geométricas?","Quantas faces tem um cubo?","O que é aresta e vértice?"],"equivalentQuestions":["quais sao as formas geometricas","o que é figura plana","o que é solido geometrico","qual a diferença entre quadrado e retangulo","quantos lados tem um hexagono","o que é poligono","circulo é poligono","o que é vertice","o que é aresta","o que é face de um solido","quantas arestas tem o cubo","quantos vertices tem o cubo","quais objetos tem forma de cilindro","o que é um cone","o que é piramide na geometria","qual solido rola","nome das figuras com 5 lados","o que é corpo redondo","o que é poliedro","me explica figuras geometricas","como diferenciar prisma e piramide"],"commonDoubts":[{"q":"O quadrado é um retângulo?","a":"Sim! O retângulo tem 4 ângulos retos; o quadrado também tem, e ainda tem os 4 lados iguais. Todo quadrado é um retângulo especial."},{"q":"Qual a diferença entre círculo e esfera?","a":"O círculo é plano (desenho no papel). A esfera é um sólido (como uma bola)."}],"commonErrors":["Chamar o cubo de quadrado (quadrado é plano, cubo é sólido)","Achar que o círculo é polígono","Contar arestas só de uma face do cubo"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-medidas","subject":"matematica","title":"Medidas de comprimento, massa e capacidade","levels":["fund1","fund2"],"grade":"3º ao 6º ano","topic":"Grandezas e medidas","subtopic":"Unidades de medida","aliases":["medidas","unidades de medida","metro centimetro quilometro","grama quilograma","litro mililitro","converter medidas","transformar unidades","comprimento massa capacidade"],"summary":"Conheça metro, grama e litro, seus múltiplos e submúltiplos, e aprenda a converter entre eles.","intro":"Quanto você mede? Quanto pesa um pacote de arroz? Quanto cabe numa garrafa? Vamos medir!","objective":"Usar unidades de comprimento, massa e capacidade e converter entre elas.","prerequisites":["mat-multiplicacao","mat-divisao"],"next":["mat-area-perimetro","mat-decimais"],"skills":{"comprimento":"Comprimento","massa":"Massa","capacidade":"Capacidade","conversao":"Conversão de unidades"},"blocks":[{"skill":"comprimento","title":"Comprimento: metro","text":"Comprimento é medido em metro (m). 1 m = 100 centímetros (cm) = 1.000 milímetros (mm). Para distâncias grandes, usamos o quilômetro: 1 km = 1.000 m.","example":"Uma porta tem cerca de 2 m de altura. De uma cidade a outra podem ser 50 km.","variants":{"simples":"Régua mede em centímetros. Estrada mede em quilômetros.","exemplo":"Uma criança de 1,30 m tem 130 cm de altura.","passos":"1. Escolha a unidade pelo tamanho: mm (muito pequeno), cm (objetos), m (salas, pessoas), km (estradas).\n2. Lembre: 1 km = 1.000 m.\n3. 1 m = 100 cm.\n4. 1 cm = 10 mm."},"id":"b1"},{"skill":"massa","title":"Massa: grama e quilograma","text":"Massa (o que chamamos de \"peso\" no dia a dia) é medida em grama (g) e quilograma (kg). 1 kg = 1.000 g. Para coisas muito leves, usamos o miligrama (mg): 1 g = 1.000 mg.","example":"Um pacote de arroz tem 5 kg; um pacote de biscoito, 200 g.","variants":{"simples":"Coisas leves em gramas, coisas pesadas em quilos.","exemplo":"Meio quilo de carne são 500 g.","passos":"1. Veja se o objeto é leve ou pesado.\n2. Leve: gramas. Pesado: quilogramas.\n3. Para passar kg para g, multiplique por 1.000.\n4. Para passar g para kg, divida por 1.000."},"id":"b2"},{"skill":"capacidade","title":"Capacidade: litro","text":"Capacidade é quanto cabe dentro de um recipiente. Usamos o litro (L) e o mililitro (mL): 1 L = 1.000 mL.","example":"Uma garrafa de refrigerante pode ter 2 L; uma lata, 350 mL.","variants":{"simples":"Litro é para quanto cabe de líquido.","exemplo":"Um copo de 250 mL: quatro copos enchem 1 litro (4 × 250 = 1.000).","passos":"1. Pergunte: quanto cabe?\n2. Muito líquido: litros.\n3. Pouco líquido: mililitros.\n4. 1 L = 1.000 mL."},"id":"b3"},{"skill":"conversao","title":"Convertendo unidades","text":"Para passar de uma unidade maior para uma menor, multiplicamos; da menor para a maior, dividimos. Os prefixos ajudam: quilo = 1.000, centi = 1/100, mili = 1/1.000.","example":"3 km = 3 × 1.000 = 3.000 m. 2.500 g = 2.500 ÷ 1.000 = 2,5 kg.","variants":{"simples":"De grande para pequeno: multiplica. De pequeno para grande: divide.","exemplo":"Uma corrida de 5 km tem 5.000 m.","passos":"1. Descubra a relação (ex.: 1 km = 1.000 m).\n2. Indo para uma unidade menor, multiplique.\n3. Indo para uma unidade maior, divida.\n4. Escreva o resultado com a nova unidade."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"comprimento","prompt":"Quantos centímetros há em 1 metro?","options":["10","100","1.000","12"],"answer":1,"hints":["\"Centi\" lembra cem.","Uma régua grande de 1 m tem…","100 cm."],"explanation":"1 m = 100 cm.","id":"q1"},{"type":"mc","difficulty":1,"skill":"massa","prompt":"Qual unidade é melhor para medir a massa de um pacote de arroz?","options":["Metro","Litro","Quilograma","Centímetro"],"answer":2,"hints":["Arroz não se mede pelo tamanho.","Queremos saber o \"peso\".","Massa: grama ou quilograma."],"explanation":"Massa é medida em kg (quilograma).","id":"q2"},{"type":"tf","difficulty":1,"skill":"capacidade","prompt":"O litro é usado para medir capacidade.","answer":true,"hints":["Capacidade é quanto cabe.","Refrigerante vem em…","Litros!"],"explanation":"Verdadeiro.","id":"q3"},{"type":"fill","difficulty":2,"skill":"conversao","prompt":"Quantos metros há em 3 km?","answers":["3000","3.000"],"hints":["1 km = 1.000 m.","De km para m, multiplique.","3 × 1.000."],"explanation":"3 km = 3.000 m.","id":"q4"},{"type":"mc","difficulty":2,"skill":"conversao","prompt":"2.500 g equivalem a:","options":["25 kg","2,5 kg","250 kg","0,25 kg"],"answer":1,"hints":["1 kg = 1.000 g.","De g para kg, divida por 1.000.","2.500 ÷ 1.000."],"explanation":"2.500 g = 2,5 kg.","id":"q5"},{"type":"match","difficulty":2,"skill":"comprimento","prompt":"Ligue cada medida à unidade mais adequada.","pairs":[["Distância entre cidades","Quilômetro"],["Comprimento de um lápis","Centímetro"],["Espessura de uma moeda","Milímetro"],["Altura de uma porta","Metro"]],"hints":["Distâncias grandes: km.","Objetos pequenos: cm.","Coisas muito finas: mm."],"explanation":"Cidades–km · lápis–cm · moeda–mm · porta–m.","id":"q6"},{"type":"fill","difficulty":2,"skill":"capacidade","prompt":"Quantos mililitros há em 1 litro?","answers":["1000","1.000"],"hints":["\"Mili\" = milésima parte.","São mil partes.","1 L = … mL."],"explanation":"1 L = 1.000 mL.","id":"q7"},{"type":"tf","difficulty":2,"skill":"massa","prompt":"1 kg de algodão tem a mesma massa que 1 kg de ferro.","answer":true,"hints":["Os dois têm 1 kg.","O volume é diferente, a massa não.","1 kg é 1 kg."],"explanation":"Verdadeiro: a massa é a mesma; o algodão só ocupa mais espaço.","id":"q8"},{"type":"mc","difficulty":3,"skill":"capacidade","prompt":"Quantos copos de 250 mL enchem uma jarra de 2 L?","options":["4","8","10","250"],"answer":1,"hints":["2 L = 2.000 mL.","Quantas vezes 250 cabe em 2.000?","2.000 ÷ 250."],"explanation":"2.000 ÷ 250 = 8 copos.","id":"q9"},{"type":"fill","difficulty":3,"skill":"conversao","prompt":"Uma criança mede 1,35 m. Quantos centímetros ela tem?","answers":["135","135 cm"],"hints":["1 m = 100 cm.","Multiplique por 100.","1,35 × 100."],"explanation":"1,35 × 100 = 135 cm.","id":"q10"},{"type":"order","difficulty":3,"skill":"comprimento","prompt":"Ordene do MENOR para o MAIOR.","items":["8 mm","5 cm","2 m","1 km"],"hints":["Converta tudo para a mesma unidade.","8 mm < 50 mm (5 cm).","1 km = 1.000 m."],"explanation":"8 mm < 5 cm (50 mm) < 2 m < 1 km.","id":"q11"},{"type":"open","difficulty":3,"skill":"conversao","prompt":"Explique como transformar quilômetros em metros, com um exemplo.","modelAnswer":"Como 1 km tem 1.000 m, multiplico o número de quilômetros por 1.000. Por exemplo, 4 km = 4 × 1.000 = 4.000 m.","keywords":["1000","multiplic","metros","quilometro"],"hints":["Quantos metros tem 1 km?","De maior para menor: multiplica ou divide?","Dê um exemplo com números."],"explanation":"km → m: multiplica por 1.000.","id":"q12"}],"review":["Comprimento: 1 km = 1.000 m · 1 m = 100 cm · 1 cm = 10 mm","Massa: 1 kg = 1.000 g","Capacidade: 1 L = 1.000 mL","Maior → menor: multiplica · menor → maior: divide"],"relatedQuestions":["Como transformar km em metros?","Quantos gramas tem 1 kg?","Quantos mL tem 1 litro?"],"equivalentQuestions":["quantos cm tem um metro","como converter metros em centimetros","quantos metros tem um quilometro","como transformar gramas em quilos","quantas gramas tem meio quilo","quantos ml tem 1 litro","como converter litros em mililitros","qual unidade usar para medir peso","diferença entre massa e peso","o que significa quilo centi e mili","como saber se multiplico ou divido na conversão","1,35 m em centimetros","quantos mm tem 1 cm","como medir capacidade","unidade de medida de comprimento","o que é capacidade na matematica","quantos copos de 250 ml tem 1 litro","me explica medidas","tabela de conversão de medidas","2500 gramas em kg","como passar de km para m"],"commonDoubts":[{"q":"Massa e peso são a mesma coisa?","a":"No dia a dia usamos como sinônimos, mas na Física massa (kg) é a quantidade de matéria e peso é a força da gravidade sobre ela (em newtons)."},{"q":"Como lembrar se multiplico ou divido?","a":"Indo para uma unidade menor, o número fica maior (multiplica). Indo para uma unidade maior, o número fica menor (divide)."}],"commonErrors":["Dividir quando deveria multiplicar (3 km = 3.000 m, não 0,003 m)","Achar que 1 m = 10 cm","Comparar medidas em unidades diferentes sem converter"],"formulas":[{"name":"Relações principais","expression":"1 km = 1.000 m · 1 m = 100 cm · 1 kg = 1.000 g · 1 L = 1.000 mL","variables":[{"symbol":"k (quilo)","meaning":"× 1.000"},{"symbol":"c (centi)","meaning":"÷ 100"},{"symbol":"m (mili)","meaning":"÷ 1.000"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-sistema-monetario","subject":"matematica","title":"Sistema monetário: dinheiro e troco","levels":["fund1"],"grade":"2º ao 5º ano","topic":"Grandezas e medidas","subtopic":"Sistema monetário brasileiro","aliases":["sistema monetario","dinheiro","real","moedas e cedulas","troco","centavos","reais e centavos","contar dinheiro","compras"],"summary":"Conheça o real, as moedas e cédulas, e aprenda a calcular preços, totais e troco.","intro":"Ir à padaria, comprar um lanche, receber troco… Usamos matemática com dinheiro o tempo todo!","objective":"Reconhecer cédulas e moedas do real, fazer trocas equivalentes e calcular totais e troco.","prerequisites":["mat-adicao-subtracao"],"next":["mat-decimais"],"skills":{"real":"Real e centavos","trocas":"Trocas equivalentes","total":"Calcular o total","troco":"Calcular o troco"},"blocks":[{"skill":"real","title":"O real e os centavos","text":"A moeda do Brasil é o real (R$). 1 real = 100 centavos. Há moedas de 5, 10, 25 e 50 centavos e de 1 real, e cédulas de 2, 5, 10, 20, 50, 100 e 200 reais.","example":"R$ 3,50 lê-se \"três reais e cinquenta centavos\".","variants":{"simples":"Cem centavos fazem 1 real.","exemplo":"Duas moedas de 50 centavos valem R$ 1,00.","passos":"1. Os números antes da vírgula são reais.\n2. Os dois números depois da vírgula são centavos.\n3. 100 centavos = R$ 1,00.\n4. Leia: \"x reais e y centavos\"."},"id":"b1"},{"skill":"trocas","title":"Trocas que valem o mesmo","text":"Podemos formar o mesmo valor com cédulas e moedas diferentes. Trocar uma nota de R$ 10 por duas de R$ 5 não muda o valor.","example":"R$ 20 = 2 notas de R$ 10 = 4 notas de R$ 5 = 10 notas de R$ 2.","variants":{"simples":"O valor é o mesmo, só muda o jeito de juntar.","exemplo":"Para pagar R$ 1,00 você pode usar 4 moedas de 25 centavos.","passos":"1. Veja o valor que quer formar.\n2. Escolha as cédulas maiores que cabem.\n3. Complete com as menores e moedas.\n4. Some para conferir."},"id":"b2"},{"skill":"total","title":"Quanto vou pagar?","text":"Para saber o total de uma compra, somamos os preços. Com vírgula, alinhamos a vírgula: reais embaixo de reais e centavos embaixo de centavos.","example":"Suco R$ 4,50 + pão R$ 2,30 = R$ 6,80.","variants":{"simples":"Some os preços de tudo que você comprou.","exemplo":"Um caderno de R$ 12,00 e um lápis de R$ 1,50 custam juntos R$ 13,50.","passos":"1. Escreva os preços um embaixo do outro, vírgula embaixo de vírgula.\n2. Some os centavos.\n3. Se passar de 100 centavos, vira 1 real.\n4. Some os reais."},"id":"b3"},{"skill":"troco","title":"Quanto recebo de troco?","text":"Troco é o dinheiro que volta: valor pago menos o preço. Dá para calcular \"completando\": do preço, conte até o valor pago.","example":"Paguei R$ 10 por algo de R$ 6,80: 6,80 + 0,20 = 7,00; 7,00 + 3,00 = 10,00. Troco: R$ 3,20.","variants":{"simples":"Troco = o que eu dei − o que custou.","exemplo":"Com uma nota de R$ 20 para um lanche de R$ 15, o troco é R$ 5.","passos":"1. Anote quanto você pagou.\n2. Anote o preço.\n3. Subtraia (ou complete a partir do preço).\n4. Confira: preço + troco = valor pago."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"real","prompt":"Quantos centavos formam 1 real?","options":["10","50","100","1.000"],"answer":2,"hints":["Pense em moedas de 50 centavos.","Duas delas formam 1 real.","50 + 50."],"explanation":"1 real = 100 centavos.","id":"q1"},{"type":"mc","difficulty":1,"skill":"trocas","prompt":"Quantas moedas de 25 centavos formam R$ 1,00?","options":["2","4","5","25"],"answer":1,"hints":["R$ 1,00 = 100 centavos.","Quantas vezes 25 cabe em 100?","25 + 25 + 25 + 25."],"explanation":"4 × 25 = 100 centavos = R$ 1,00.","id":"q2"},{"type":"tf","difficulty":1,"skill":"trocas","prompt":"Uma nota de R$ 10 vale o mesmo que duas notas de R$ 5.","answer":true,"hints":["Some as duas de R$ 5.","5 + 5 = ?","10."],"explanation":"Verdadeiro.","id":"q3"},{"type":"fill","difficulty":2,"skill":"total","prompt":"Um suco custa R$ 4,50 e um pão R$ 2,30. Quanto custa tudo? (R$)","answers":["6,80","6.80","6,8"],"hints":["Some os centavos: 50 + 30.","Some os reais: 4 + 2.","Junte reais e centavos."],"explanation":"4,50 + 2,30 = R$ 6,80.","id":"q4"},{"type":"mc","difficulty":2,"skill":"troco","prompt":"Paguei com R$ 10 algo que custou R$ 6,80. Qual o troco?","options":["R$ 4,20","R$ 3,20","R$ 3,80","R$ 16,80"],"answer":1,"hints":["Troco = pago − preço.","De 6,80 até 7,00 faltam 0,20.","De 7,00 até 10,00 faltam 3,00."],"explanation":"10,00 − 6,80 = R$ 3,20.","id":"q5"},{"type":"match","difficulty":2,"skill":"trocas","prompt":"Ligue cada valor a uma forma de formá-lo.","pairs":[["R$ 20","4 notas de R$ 5"],["R$ 1","2 moedas de 50 centavos"],["R$ 50","5 notas de R$ 10"],["R$ 6","3 notas de R$ 2"]],"hints":["Multiplique a quantidade pelo valor da nota.","4 × 5 = 20.","5 × 10 = 50."],"explanation":"20 = 4×5 · 1 = 2×0,50 · 50 = 5×10 · 6 = 3×2.","id":"q6"},{"type":"fill","difficulty":2,"skill":"troco","prompt":"Com uma nota de R$ 20, comprei um lanche de R$ 15. Qual é o troco em reais?","answers":["5","5,00","R$ 5"],"hints":["Troco = pago − preço.","20 − 15.","Confira: 15 + ? = 20."],"explanation":"20 − 15 = R$ 5.","id":"q7"},{"type":"tf","difficulty":3,"skill":"real","prompt":"R$ 3,05 e R$ 3,50 são o mesmo valor.","answer":false,"hints":["Olhe os centavos.","05 centavos e 50 centavos são iguais?","Não."],"explanation":"Falso: R$ 3,05 tem 5 centavos; R$ 3,50 tem 50 centavos.","id":"q8"},{"type":"mc","difficulty":3,"skill":"total","prompt":"Comprei 3 cadernos de R$ 8,50. Quanto gastei?","options":["R$ 24,50","R$ 25,50","R$ 11,50","R$ 26,00"],"answer":1,"hints":["São 3 vezes o mesmo preço.","3 × 8 = 24 e 3 × 0,50 = 1,50.","Some as partes."],"explanation":"3 × 8,50 = 24 + 1,50 = R$ 25,50.","id":"q9"},{"type":"order","difficulty":2,"skill":"real","prompt":"Ordene do MENOR para o MAIOR valor.","items":["R$ 0,75","R$ 1,20","R$ 2,05","R$ 2,50"],"hints":["Compare primeiro os reais.","Com reais iguais, compare os centavos.","05 centavos < 50 centavos."],"explanation":"0,75 < 1,20 < 2,05 < 2,50.","id":"q10"},{"type":"mc","difficulty":3,"skill":"troco","prompt":"Tenho R$ 50. Gastei R$ 12,40 e R$ 23,60. Quanto sobrou?","options":["R$ 14,00","R$ 36,00","R$ 13,00","R$ 24,00"],"answer":0,"hints":["Some os gastos primeiro.","12,40 + 23,60 = 36,00.","50 − 36."],"explanation":"Gastos: R$ 36,00. Sobra: 50 − 36 = R$ 14,00.","id":"q11"},{"type":"open","difficulty":3,"skill":"troco","prompt":"Explique como você confere se recebeu o troco certo.","modelAnswer":"Somo o preço da compra com o troco recebido. Se der o valor que eu paguei, o troco está certo.","keywords":["preco","soma","somar","troco","paguei","igual"],"hints":["O troco é o que volta do valor pago.","Preço + troco deve dar…","O valor que você entregou."],"explanation":"Preço + troco = valor pago.","id":"q12"}],"review":["1 real = 100 centavos","Valores iguais podem ser formados de jeitos diferentes","Total: some alinhando a vírgula","Troco = valor pago − preço (confira somando)"],"relatedQuestions":["Como calcular o troco?","Quantos centavos tem um real?","Como somar preços com vírgula?"],"equivalentQuestions":["como calcular troco","quanto de troco eu recebo","quantos centavos tem 1 real","como somar dinheiro com virgula","como ler preços em reais","quais sao as moedas do real","quais notas de dinheiro existem","como formar 1 real com moedas","como conferir o troco","como calcular o total da compra","o que significa R$","quanto é meio real","como contar dinheiro","problema de dinheiro e troco","como pagar com notas diferentes","como subtrair dinheiro","me explica sistema monetario","como saber se vai sobrar dinheiro","quantas moedas de 25 centavos fazem 1 real","diferença entre 3,05 e 3,50"],"commonDoubts":[{"q":"Por que R$ 0,50 é metade de 1 real?","a":"Porque 1 real tem 100 centavos, e 50 é metade de 100."}],"commonErrors":["Confundir R$ 3,05 com R$ 3,50","Somar sem alinhar a vírgula","Esquecer que 100 centavos viram 1 real na soma"],"formulas":[{"name":"Troco","expression":"troco = valor pago − preço","variables":[{"symbol":"valor pago","meaning":"quanto você entregou"},{"symbol":"preço","meaning":"quanto custou"},{"symbol":"troco","meaning":"o que volta"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Cédulas e moedas do Real","url":"https://www.bcb.gov.br/cedulasemoedas","author":"Banco Central do Brasil","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Números racionais","subtopic":"Frações","relatedQuestions":["O que é numerador e denominador?","Como simplificar uma fração?","O que são frações equivalentes?","Como ler uma fração?"],"id":"mat-fracoes","subject":"matematica","title":"Frações","levels":["fund1","fund2"],"grade":"4º ao 6º ano","aliases":["fracao","fracoes","numerador","denominador","fracoes equivalentes","simplificar fracao","simplificacao de fracoes"],"summary":"Entenda o que é uma fração, como ler, encontrar frações equivalentes e simplificar.","intro":"Vamos entender juntos. Fração é um jeito de mostrar pedaços de alguma coisa — de uma pizza, de uma barra de chocolate ou de um grupo de pessoas.","skills":{"conceito":"Conceito de fração","leitura":"Leitura de frações","equivalentes":"Frações equivalentes","simplificacao":"Simplificação de frações"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é uma fração","text":"A fração representa uma parte de um todo. O número de cima (numerador) indica quantas partes você está pegando. O número de baixo (denominador) indica em quantas partes iguais o todo foi dividido.","example":"Uma pizza cortada em 8 pedaços iguais. Se você come 3, comeu 3/8 da pizza: 3 é o numerador e 8 é o denominador.","variants":{"simples":"Pense numa pizza. O número de baixo diz em quantos pedaços ela foi cortada. O número de cima diz quantos pedaços você pegou. Só isso!","exemplo":"Uma barra de chocolate tem 4 quadradinhos iguais. Você deu 1 para seu amigo. Seu amigo ganhou 1/4 da barra: 1 pedaço de 4.","outra":"Fração é uma divisão escrita de um jeito especial. 3/8 quer dizer \"dividi em 8 partes iguais e fiquei com 3 delas\". O traço do meio é como um \"de\": 3 de 8.","detalhado":"Numa fração a/b, o denominador b (que nunca pode ser zero) diz em quantas partes IGUAIS o inteiro foi dividido — as partes precisam ter o mesmo tamanho. O numerador a conta quantas dessas partes estamos considerando. Se a = b, temos o inteiro (8/8 = 1). Se a > b, temos mais de um inteiro, como 9/8."}},{"id":"b2","skill":"leitura","title":"Como ler uma fração","text":"Lemos primeiro o numerador e depois o denominador com um nome especial: 2 = meio, 3 = terço, 4 = quarto, 5 = quinto… até 9 = nono, e 10 = décimo. Acima de 10, usamos a palavra \"avos\".","example":"1/2 = um meio · 2/3 = dois terços · 3/10 = três décimos · 5/12 = cinco doze avos.","variants":{"simples":"1/2 é \"um meio\" (metade). 1/3 é \"um terço\". 1/4 é \"um quarto\". Quando o número de baixo passa de 10, falamos \"avos\": 1/12 é \"um doze avos\".","exemplo":"Se um bolo foi cortado em 12 fatias e você comeu 5, você comeu \"cinco doze avos\" do bolo. Se foi cortado em 4 e você comeu 3, comeu \"três quartos\".","outra":"O denominador vira um nome parecido com os números de ordem: quinto, sexto, sétimo, oitavo, nono, décimo. Exceções: 2 é \"meio\" e 3 é \"terço\". Depois do 10, é o número + \"avos\".","detalhado":"Denominadores 100 e 1000 também têm nomes próprios: centésimo (1/100) e milésimo (1/1000). Por isso 25/100 se lê \"vinte e cinco centésimos\". Nos demais casos acima de 10 usamos \"avos\": 7/15 = sete quinze avos."}},{"id":"b3","skill":"equivalentes","title":"Frações equivalentes","text":"Frações equivalentes representam a mesma quantidade, mesmo com números diferentes. Para encontrar uma, multiplique (ou divida) o numerador e o denominador pelo mesmo número.","example":"1/2 = 2/4 = 4/8. Metade da pizza é sempre metade, esteja ela cortada em 2, 4 ou 8 pedaços.","variants":{"simples":"Metade de uma pizza é igual a 2 pedaços de 4, ou 4 pedaços de 8. Muda o número de pedaços, mas a quantidade de pizza é a mesma.","exemplo":"Você tem 1/3 de uma barra. Se cortar cada pedaço ao meio, agora são 6 pedaços no total e você tem 2: 2/6. Continua sendo a mesma quantidade de chocolate.","outra":"Multiplicar em cima e embaixo pelo mesmo número é como \"cortar os pedaços em pedaços menores\": aumenta a quantidade de pedaços, mas não a quantidade de pizza.","detalhado":"a/b e c/d são equivalentes quando a·d = b·c (produto cruzado). Exemplo: 2/3 e 4/6 → 2·6 = 12 e 3·4 = 12, então são equivalentes. Isso funciona porque multiplicar numerador e denominador pelo mesmo número é o mesmo que multiplicar a fração por 1 (n/n = 1)."}},{"id":"b4","skill":"simplificacao","title":"Simplificar frações","text":"Simplificar é escrever a fração com os menores números possíveis. Divida o numerador e o denominador pelo mesmo número até não ser mais possível. A fração final é chamada de irredutível.","example":"6/8 → dividindo os dois por 2 → 3/4. Como 3 e 4 não têm outro divisor comum, 3/4 é irredutível.","variants":{"simples":"Procure um número que divide o de cima e o de baixo ao mesmo tempo. Divida os dois. Repita até não dar mais.","exemplo":"12/18: os dois são pares, divide por 2 → 6/9. Os dois estão na tabuada do 3, divide por 3 → 2/3. Pronto: 2/3.","outra":"Simplificar é o caminho contrário das equivalentes: em vez de cortar os pedaços em partes menores, você junta pedaços até ficarem do maior tamanho possível.","detalhado":"O jeito mais rápido é dividir numerador e denominador pelo máximo divisor comum (MDC). MDC(12, 18) = 6, então 12/18 = (12÷6)/(18÷6) = 2/3 em um passo só. Uma fração é irredutível quando o MDC entre numerador e denominador é 1."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Se João comeu 3 de 8 pedaços de uma pizza, qual fração representa o que ele comeu?","options":["3/5","3/8","5/8","8/3"],"answer":1,"hints":["Quantos pedaços a pizza tinha no total?","O número de baixo é o total de pedaços; o de cima é quantos ele comeu.","Total = 8 (embaixo). Comeu = 3 (em cima)."],"explanation":"A pizza tinha 8 pedaços (denominador) e João comeu 3 (numerador): 3/8."},{"id":"q2","type":"mc","difficulty":1,"skill":"conceito","prompt":"Na fração 2/5, qual é o denominador?","options":["2","5","7","10"],"answer":1,"hints":["Denominador fica em uma posição específica da fração.","O denominador é o número de baixo: em quantas partes o todo foi dividido.","Olhe o número abaixo do traço."],"explanation":"O denominador é o número de baixo, 5: o todo foi dividido em 5 partes iguais."},{"id":"q3","type":"tf","difficulty":1,"skill":"leitura","prompt":"A fração 1/4 se lê \"um quarto\".","answer":true,"hints":["Pense no nome especial do denominador 4.","2 = meio, 3 = terço, 4 = …","4 é \"quarto\", como em \"um quarto de hora\"."],"explanation":"Verdadeiro. O denominador 4 se lê \"quarto\": 1/4 = um quarto."},{"id":"q4","type":"mc","difficulty":1,"skill":"leitura","prompt":"Como se lê a fração 3/10?","options":["Três dez avos","Três décimos","Três dezenas","Dez terços"],"answer":1,"hints":["O 10 tem um nome especial.","Até o 10, os denominadores têm nomes próprios.","10 no denominador = décimo."],"explanation":"Quando o denominador é 10, usamos \"décimo(s)\": três décimos."},{"id":"q5","type":"fill","difficulty":2,"skill":"leitura","prompt":"Complete: 5/12 se lê \"cinco doze ____\".","answers":["avos"],"hints":["12 é maior que 10.","Acima de 10, os denominadores não têm nome especial.","Usamos a palavra que começa com \"a\" e termina com \"s\"."],"explanation":"Acima de 10 usamos \"avos\": cinco doze avos."},{"id":"q6","type":"mc","difficulty":2,"skill":"equivalentes","prompt":"Qual destas frações é equivalente a 1/2?","options":["2/3","4/8","3/5","1/4"],"answer":1,"hints":["Procure a fração que também representa \"metade\".","Multiplique o 1 e o 2 pelo mesmo número.","1×4 = 4 e 2×4 = 8."],"explanation":"4/8 é metade de 8, igual a 1/2. Multiplicamos em cima e embaixo por 4."},{"id":"q7","type":"tf","difficulty":2,"skill":"equivalentes","prompt":"As frações 2/3 e 4/6 são equivalentes.","answer":true,"hints":["Compare como 2 virou 4 e como 3 virou 6.","Se os dois foram multiplicados pelo mesmo número, são equivalentes.","2×2 = 4 e 3×2 = 6."],"explanation":"Verdadeiro. Numerador e denominador de 2/3 foram multiplicados por 2, gerando 4/6."},{"id":"q8","type":"fill","difficulty":2,"skill":"simplificacao","prompt":"Simplifique a fração 6/8. (Escreva no formato a/b)","answers":["3/4"],"hints":["6 e 8 são números pares.","Divida numerador e denominador pelo mesmo número.","6÷2 = 3 e 8÷2 = 4."],"explanation":"Dividindo os dois por 2: 6/8 = 3/4, que já é irredutível."},{"id":"q9","type":"mc","difficulty":3,"skill":"simplificacao","prompt":"Qual é a forma irredutível de 12/18?","options":["6/9","4/6","2/3","3/2"],"answer":2,"hints":["Irredutível = não dá mais para simplificar.","6/9 e 4/6 ainda podem ser simplificadas.","Divida 12 e 18 por 6."],"explanation":"O maior divisor comum de 12 e 18 é 6. 12÷6 = 2 e 18÷6 = 3, então 12/18 = 2/3."},{"id":"q10","type":"match","difficulty":2,"skill":"leitura","prompt":"Ligue cada fração ao seu nome.","pairs":[["1/2","Um meio"],["1/3","Um terço"],["1/4","Um quarto"],["1/5","Um quinto"]],"hints":["Comece pela mais conhecida: metade.","2 = meio, 3 = terço.","4 = quarto e 5 = quinto."],"explanation":"1/2 = um meio, 1/3 = um terço, 1/4 = um quarto, 1/5 = um quinto."},{"id":"q11","type":"mc","difficulty":3,"skill":"equivalentes","prompt":"Qual número deve ocupar o lugar do x em 3/5 = x/20?","options":["8","12","15","4"],"answer":1,"hints":["O que aconteceu com o denominador 5 para virar 20?","5 foi multiplicado por 4.","Faça o mesmo com o numerador: 3 × 4."],"explanation":"5 × 4 = 20, então o numerador também é multiplicado por 4: 3 × 4 = 12."},{"id":"q12","type":"open","difficulty":3,"skill":"equivalentes","prompt":"Explique com suas palavras por que 2/4 e 1/2 representam a mesma quantidade.","modelAnswer":"Porque 2/4 é a metade de 4 partes, e 1/2 também é metade. Se dividirmos o numerador e o denominador de 2/4 por 2, obtemos 1/2 — são frações equivalentes.","keywords":["metade","mesma","equivalente","dividir","multiplicar","2"],"hints":["Desenhe uma pizza cortada em 4 e outra em 2.","Pinte 2 pedaços de 4 e 1 pedaço de 2. O que você percebe?","Fale sobre \"metade\" ou sobre dividir em cima e embaixo por 2."],"explanation":"As duas representam metade do todo. 2/4 simplificada (÷2) vira 1/2 — por isso são equivalentes."}],"review":["Numerador (em cima) = partes que pegamos","Denominador (embaixo) = em quantas partes iguais o todo foi dividido","Equivalentes: multiplique ou divida em cima e embaixo pelo mesmo número","Simplificar: divida até não dar mais (irredutível)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Proporcionalidade","subtopic":"Porcentagem","relatedQuestions":["Como calcular porcentagem?","Como calcular desconto?","Quanto é 10% de um valor?","Como calcular aumento percentual?"],"id":"mat-porcentagem","subject":"matematica","title":"Porcentagem","levels":["fund2","medio"],"grade":"6º e 7º ano","aliases":["porcentagem","por cento","percentual","desconto","juros simples","aumento percentual"],"summary":"Aprenda o que significa \"por cento\", como calcular porcentagens, descontos e aumentos.","intro":"Porcentagem está em todo lugar: promoções, bateria do celular, notas. Vamos descobrir como ela funciona.","skills":{"conceito":"O que é porcentagem","atalhos":"Atalhos de cálculo","calculo":"Calcular porcentagem de um valor","desconto":"Descontos e aumentos"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é \"por cento\"","text":"Porcentagem é uma fração com denominador 100. \"25%\" significa 25 de cada 100, ou seja, 25/100. O todo sempre vale 100%.","example":"Se a bateria do celular está em 40%, sobrou 40 de 100 partes da carga total.","variants":{"simples":"Imagine algo dividido em 100 pedacinhos. 30% são 30 desses pedacinhos. 100% é tudo.","exemplo":"Numa turma de 100 alunos, 60 gostam de futebol. Então 60% da turma gosta de futebol.","outra":"O símbolo % é um jeito curto de escrever \"dividido por 100\". Então 7% = 7 ÷ 100 = 0,07.","detalhado":"Porcentagem é uma razão centesimal. Toda porcentagem pode ser escrita como fração (15% = 15/100 = 3/20) ou como decimal (15% = 0,15). Valores acima de 100% indicam mais que o todo, como um aumento de 150%."}},{"id":"b2","skill":"atalhos","title":"Atalhos que ajudam muito","text":"50% é a metade. 25% é um quarto (metade da metade). 10% é dividir por 10. A partir daí você monta outras: 20% = 2 × 10%, 5% = metade de 10%.","example":"De R$ 80: 10% = R$ 8 · 5% = R$ 4 · 15% = R$ 8 + R$ 4 = R$ 12.","variants":{"simples":"Para achar 10%, tire o último zero ou divida por 10. Para 50%, pegue a metade.","exemplo":"De 200 figurinhas: 50% = 100, 25% = 50, 10% = 20.","outra":"Pense em \"blocos de 10%\". 30% são três blocos de 10%. Achou um bloco, é só somar.","detalhado":"Os atalhos funcionam porque 10% = 1/10, 50% = 1/2, 25% = 1/4 e 20% = 1/5. Combinar porcentagens é somar as frações: 35% = 25% + 10% = 1/4 + 1/10."}},{"id":"b3","skill":"calculo","title":"Calculando a porcentagem de um valor","text":"Para calcular x% de um valor, multiplique o valor por x e divida por 100. Para saber quantos por cento uma parte representa, divida a parte pelo todo e multiplique por 100.","example":"20% de 150 = 150 × 20 ÷ 100 = 30. E 30 de 120 é: 30 ÷ 120 = 0,25 → 25%.","variants":{"simples":"x% de um número: número × x ÷ 100. Exemplo: 20% de 50 = 50 × 20 ÷ 100 = 10.","exemplo":"Uma prova tem 40 questões e você acertou 30. 30 ÷ 40 = 0,75 → 75% de acerto.","outra":"Transforme a porcentagem em decimal e multiplique: 20% = 0,2. Então 20% de 150 = 0,2 × 150 = 30.","detalhado":"São duas perguntas diferentes: (1) \"quanto é p% de V?\" → p/100 × V; (2) \"a parte P é quantos % de V?\" → P/V × 100. Confundir qual é o todo (V) é o erro mais comum."}},{"id":"b4","skill":"desconto","title":"Descontos e aumentos","text":"No desconto, você calcula a porcentagem e subtrai do preço. No aumento, calcula e soma. Atalho: desconto de 10% = pagar 90% do preço.","example":"Camiseta de R$ 60 com 10% de desconto: 10% de 60 = 6 → 60 − 6 = R$ 54.","variants":{"simples":"Desconto: acha a porcentagem e tira. Aumento: acha a porcentagem e soma.","exemplo":"Um tênis de R$ 200 subiu 15%: 15% de 200 = 30. Novo preço: 200 + 30 = R$ 230.","outra":"Use o fator: desconto de 20% → multiplica por 0,8. Aumento de 20% → multiplica por 1,2.","detalhado":"Aumentos e descontos sucessivos não se cancelam: 100 com +20% vira 120; 120 com −20% vira 96. Isso acontece porque o segundo cálculo é feito sobre um valor diferente (1,2 × 0,8 = 0,96)."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"atalhos","prompt":"50% de alguma coisa é o mesmo que:","options":["Um terço","A metade","Um quarto","O dobro"],"answer":1,"hints":["50 é que parte de 100?","50 de 100 partes.","50/100 simplificado dá 1/2."],"explanation":"50% = 50/100 = 1/2, ou seja, a metade."},{"id":"q2","type":"fill","difficulty":1,"skill":"conceito","prompt":"Escreva 25% como fração simplificada (a/b).","answers":["1/4"],"hints":["Porcentagem é uma fração com denominador 100.","25% = 25/100.","Simplifique 25/100 dividindo por 25."],"explanation":"25% = 25/100 = 1/4."},{"id":"q3","type":"mc","difficulty":1,"skill":"atalhos","prompt":"Quanto é 10% de 80?","options":["8","10","18","0,8"],"answer":0,"hints":["10% é um atalho fácil.","10% = dividir por 10.","80 ÷ 10."],"explanation":"10% de 80 = 80 ÷ 10 = 8."},{"id":"q4","type":"tf","difficulty":1,"skill":"conceito","prompt":"100% representa o todo.","answer":true,"hints":["Porcentagem é \"de cada 100\".","100 de 100 partes é quanto?","É tudo."],"explanation":"Verdadeiro. 100% = 100/100 = 1 inteiro."},{"id":"q5","type":"fill","difficulty":2,"skill":"calculo","prompt":"Quanto é 20% de 150?","answers":["30"],"hints":["Comece achando 10%.","10% de 150 = 15.","20% = 2 × 10%."],"explanation":"10% de 150 = 15, então 20% = 30. Ou: 150 × 20 ÷ 100 = 30."},{"id":"q6","type":"mc","difficulty":2,"skill":"desconto","prompt":"Uma camiseta custa R$ 60 e tem 10% de desconto. Quanto você paga?","options":["R$ 50","R$ 54","R$ 56","R$ 66"],"answer":1,"hints":["Primeiro ache quanto é o desconto.","10% de 60 = 6.","Desconto se subtrai: 60 − 6."],"explanation":"O desconto é 10% de 60 = R$ 6. Você paga 60 − 6 = R$ 54."},{"id":"q7","type":"match","difficulty":2,"skill":"atalhos","prompt":"Ligue cada porcentagem à fração correspondente.","pairs":[["50%","A metade"],["25%","Um quarto"],["10%","Um décimo"],["100%","O todo"]],"hints":["Escreva cada uma sobre 100.","25/100 = 1/4 e 10/100 = 1/10.","100/100 = 1."],"explanation":"50% = 1/2, 25% = 1/4, 10% = 1/10, 100% = o todo."},{"id":"q8","type":"tf","difficulty":2,"skill":"atalhos","prompt":"Para calcular 10% de um número, basta dividi-lo por 10.","answer":true,"hints":["10% = 10/100.","10/100 simplificado.","= 1/10."],"explanation":"Verdadeiro. 10% = 1/10, então é só dividir por 10."},{"id":"q9","type":"mc","difficulty":3,"skill":"desconto","prompt":"Um produto de R$ 200 teve aumento de 15%. Qual é o novo preço?","options":["R$ 215","R$ 230","R$ 185","R$ 300"],"answer":1,"hints":["Calcule 15% de 200.","10% = 20 e 5% = 10.","Aumento se soma: 200 + 30."],"explanation":"15% de 200 = 30. Novo preço = 200 + 30 = R$ 230."},{"id":"q10","type":"fill","difficulty":3,"skill":"calculo","prompt":"30 é quantos por cento de 120? (só o número)","answers":["25","25%"],"hints":["Divida a parte pelo todo.","30 ÷ 120 = 0,25.","Multiplique por 100."],"explanation":"30 ÷ 120 = 0,25 = 25%."},{"id":"q11","type":"mc","difficulty":3,"skill":"desconto","prompt":"Um valor de 100 sofre desconto de 20% e depois aumento de 20%. Qual o resultado final?","options":["100","96","104","120"],"answer":1,"hints":["Faça em duas etapas.","Depois do desconto: 80.","Agora calcule 20% de 80 e some."],"explanation":"100 − 20% = 80. 80 + 20% de 80 (16) = 96. O segundo cálculo é sobre um valor menor."},{"id":"q12","type":"mc","difficulty":3,"skill":"calculo","prompt":"Quanto é 15% de 40?","options":["4","6","15","5,5"],"answer":1,"hints":["Quebre 15% em 10% + 5%.","10% de 40 = 4.","5% é a metade de 10%: 2. Some."],"explanation":"10% de 40 = 4 e 5% = 2. Total: 4 + 2 = 6."}],"review":["% = dividido por 100","10% = ÷10 · 50% = metade · 25% = um quarto","Desconto: subtrai · Aumento: soma","Parte ÷ todo × 100 = porcentagem"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Álgebra","subtopic":"Equação do 1º grau","relatedQuestions":["Como achar o valor de x?","Como resolver uma equação simples?","O que é incógnita?"],"id":"mat-equacao-1-grau","subject":"matematica","title":"Equação do 1º grau","levels":["fund2","medio"],"grade":"7º ano","aliases":["equacao do primeiro grau","equacao do 1 grau","equacao simples","incognita","achar o x","isolar o x"],"summary":"Aprenda a encontrar o valor desconhecido (x) mantendo a equação equilibrada.","intro":"Uma equação é como uma balança em equilíbrio. Vamos descobrir o peso escondido!","skills":{"conceito":"O que é uma equação","operacoes":"Operações inversas","resolucao":"Resolver passo a passo","problemas":"Montar equações a partir de problemas"},"blocks":[{"id":"b1","skill":"conceito","title":"Uma balança em equilíbrio","text":"Equação é uma igualdade com um valor desconhecido, a incógnita (geralmente x). Resolver é descobrir o valor de x que torna a igualdade verdadeira.","example":"Em x + 3 = 10, o valor de x é 7, porque 7 + 3 = 10."},{"id":"b2","skill":"operacoes","title":"Operações inversas","text":"Para isolar o x, desfazemos as operações usando a inversa: a soma se desfaz com subtração, e a multiplicação, com divisão. O que fazemos de um lado, fazemos do outro.","example":"x + 5 = 12 → subtraia 5 dos dois lados → x = 7. E 3x = 18 → divida os dois lados por 3 → x = 6."},{"id":"b3","skill":"resolucao","title":"Passo a passo","text":"Primeiro junte os números sem x de um lado e os termos com x do outro. Depois, divida pelo número que multiplica o x.","example":"2x + 4 = 14 → 2x = 14 − 4 → 2x = 10 → x = 5. Confira: 2·5 + 4 = 14 ✓."},{"id":"b4","skill":"problemas","title":"Transformando problemas em equações","text":"Chame o valor desconhecido de x e traduza a frase em matemática: \"o dobro\" é 2x, \"o triplo\" é 3x, \"somado a\" é +.","example":"\"O dobro de um número mais 3 é 11\" → 2x + 3 = 11 → x = 4."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Qual é o valor de x em x + 3 = 10?","options":["13","7","3","30"],"answer":1,"hints":["Que número somado a 3 dá 10?","Desfaça a soma.","10 − 3."],"explanation":"x = 10 − 3 = 7."},{"id":"q2","type":"fill","difficulty":1,"skill":"operacoes","prompt":"Resolva: x − 4 = 9. x = ?","answers":["13"],"hints":["A subtração se desfaz com…","Some 4 aos dois lados.","9 + 4."],"explanation":"x = 9 + 4 = 13."},{"id":"q3","type":"mc","difficulty":1,"skill":"operacoes","prompt":"Resolva: 3x = 18.","options":["x = 6","x = 15","x = 21","x = 54"],"answer":0,"hints":["3x quer dizer 3 vezes x.","A multiplicação se desfaz com divisão.","18 ÷ 3."],"explanation":"x = 18 ÷ 3 = 6."},{"id":"q4","type":"tf","difficulty":1,"skill":"conceito","prompt":"Numa equação, o que fazemos de um lado devemos fazer também do outro.","answer":true,"hints":["Lembre da balança.","Tirar peso só de um lado desequilibra.","Os dois lados mudam juntos."],"explanation":"Verdadeiro. Assim a igualdade continua valendo."},{"id":"q5","type":"fill","difficulty":2,"skill":"resolucao","prompt":"Resolva: 2x + 4 = 14. x = ?","answers":["5"],"hints":["Primeiro tire o 4.","2x = 10.","Divida por 2."],"explanation":"2x = 10 → x = 5."},{"id":"q6","type":"mc","difficulty":2,"skill":"resolucao","prompt":"Resolva: 5x − 10 = 15.","options":["x = 1","x = 5","x = 25","x = 3"],"answer":1,"hints":["Some 10 aos dois lados.","5x = 25.","25 ÷ 5."],"explanation":"5x = 25 → x = 5."},{"id":"q7","type":"match","difficulty":2,"skill":"problemas","prompt":"Ligue cada frase à expressão.","pairs":[["O dobro de um número","2x"],["O triplo de um número","3x"],["Um número mais 5","x + 5"],["A metade de um número","x ÷ 2"]],"hints":["Dobro = 2 vezes.","Triplo = 3 vezes.","Metade = dividir por 2."],"explanation":"Dobro: 2x · triplo: 3x · mais 5: x + 5 · metade: x ÷ 2."},{"id":"q8","type":"mc","difficulty":3,"skill":"problemas","prompt":"O dobro de um número mais 3 é igual a 11. Que número é esse?","options":["4","7","8","14"],"answer":0,"hints":["Monte: 2x + 3 = 11.","2x = 8.","x = 8 ÷ 2."],"explanation":"2x + 3 = 11 → 2x = 8 → x = 4."},{"id":"q9","type":"fill","difficulty":3,"skill":"resolucao","prompt":"Resolva: 4x + 2 = 2x + 10. x = ?","answers":["4"],"hints":["Junte os x de um lado: 4x − 2x.","2x = 10 − 2.","2x = 8."],"explanation":"2x = 8 → x = 4. Confira: 18 = 18 ✓."},{"id":"q10","type":"tf","difficulty":3,"skill":"operacoes","prompt":"Em x ÷ 3 = 5, o valor de x é 15.","answer":true,"hints":["A divisão se desfaz com…","Multiplique os dois lados por 3.","5 × 3."],"explanation":"Verdadeiro: x = 5 × 3 = 15."}],"review":["Equação = igualdade com incógnita","Use operações inversas dos dois lados","Junte x de um lado e números do outro","Sempre confira substituindo o valor"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Álgebra","subtopic":"Equação do 2º grau","relatedQuestions":["Como usar a fórmula de Bhaskara?","Como calcular o delta?","Como achar as raízes de uma equação do segundo grau?"],"id":"mat-equacao-2-grau","subject":"matematica","title":"Equação do 2º grau","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["equacao do segundo grau","equacao do 2 grau","bhaskara","baskara","delta","discriminante","equacao quadratica","raizes"],"summary":"Reconheça a equação do 2º grau, calcule o delta e encontre as raízes com a fórmula de Bhaskara.","intro":"A equação do 2º grau aparece quando a incógnita está elevada ao quadrado. Vamos por partes, sem pressa.","skills":{"forma":"Forma geral e coeficientes","delta":"Discriminante (Δ)","bhaskara":"Fórmula de Bhaskara","incompletas":"Equações incompletas"},"blocks":[{"id":"b1","skill":"forma","title":"A forma geral","text":"Toda equação do 2º grau pode ser escrita como ax² + bx + c = 0, em que a, b e c são números chamados coeficientes e a nunca é zero.","example":"Em 2x² − 3x + 1 = 0: a = 2, b = −3 e c = 1. O sinal faz parte do coeficiente!","variants":{"simples":"Se o maior expoente do x é 2 (x²), é uma equação do 2º grau. O número na frente do x² é o a, na frente do x é o b, e o número sozinho é o c.","exemplo":"x² − 5x + 6 = 0 → a = 1 (tem um \"1\" invisível na frente do x²), b = −5, c = 6.","outra":"Pense como uma ficha com três espaços: [a]x² + [b]x + [c] = 0. Seu trabalho é preencher a ficha com os números da equação, sempre levando o sinal junto.","detalhado":"Se a = 0, o termo x² desaparece e a equação passa a ser do 1º grau — por isso a ≠ 0. Antes de identificar os coeficientes, organize a equação: tudo de um lado e zero do outro. Ex.: x² = 5x − 6 vira x² − 5x + 6 = 0."}},{"id":"b2","skill":"delta","title":"O discriminante (Δ)","text":"O delta é calculado por Δ = b² − 4ac. Ele revela quantas raízes reais a equação tem: Δ > 0 → duas raízes diferentes; Δ = 0 → duas raízes iguais (uma só); Δ < 0 → nenhuma raiz real.","example":"x² − 5x + 6 = 0 → Δ = (−5)² − 4·1·6 = 25 − 24 = 1. Como 1 > 0, há duas raízes diferentes.","variants":{"simples":"Delta é uma conta que vem antes da resposta: b vezes b, menos 4 vezes a vezes c. Se der positivo, tem duas respostas. Zero, uma. Negativo, nenhuma (nos números reais).","exemplo":"x² + 2x + 5 = 0 → Δ = 4 − 20 = −16. Negativo: essa equação não tem raiz real.","outra":"O delta é como um \"detector\": antes de fazer toda a conta, ele avisa se vale a pena continuar e quantas respostas vão sair.","detalhado":"Na fórmula de Bhaskara aparece √Δ. Não existe raiz quadrada real de número negativo, por isso Δ < 0 não tem solução real. Quando Δ = 0, +√Δ e −√Δ dão o mesmo valor e as raízes coincidem: x = −b/2a."}},{"id":"b3","skill":"bhaskara","title":"A fórmula de Bhaskara","text":"Com o delta calculado, as raízes são x = (−b ± √Δ) ÷ 2a. O \"±\" gera duas contas: uma somando e outra subtraindo a raiz de delta.","example":"x² − 5x + 6 = 0, Δ = 1 → x = (5 ± 1) ÷ 2 → x₁ = 6 ÷ 2 = 3 e x₂ = 4 ÷ 2 = 2.","variants":{"simples":"Receita: 1) ache a, b, c. 2) calcule delta. 3) faça (−b + √Δ) ÷ 2a e depois (−b − √Δ) ÷ 2a.","exemplo":"x² + 2x − 8 = 0 → Δ = 4 + 32 = 36, √36 = 6 → x = (−2 ± 6) ÷ 2 → x₁ = 2 e x₂ = −4.","outra":"Sempre confira: coloque a resposta no lugar do x. Se a conta der zero, acertou. Em x² − 5x + 6 com x = 3: 9 − 15 + 6 = 0 ✓.","detalhado":"Cuidado com o −b: se b = −5, então −b = 5. Também vale a relação de soma e produto: x₁ + x₂ = −b/a e x₁ · x₂ = c/a — útil para conferir ou até resolver de cabeça."}},{"id":"b4","skill":"incompletas","title":"Equações incompletas","text":"Quando b = 0 ou c = 0 existe um caminho mais curto. Se c = 0, coloque x em evidência: x(ax + b) = 0. Se b = 0, isole o x² e tire a raiz.","example":"x² − 4x = 0 → x(x − 4) = 0 → x = 0 ou x = 4. E x² − 9 = 0 → x² = 9 → x = 3 ou x = −3.","variants":{"simples":"Falta o número sozinho? Tire o x para fora. Falta o termo com x? Passe o número para o outro lado e tire a raiz.","exemplo":"2x² − 18 = 0 → 2x² = 18 → x² = 9 → x = ±3.","outra":"Um produto só dá zero se um dos fatores for zero. Por isso x(x − 4) = 0 leva a x = 0 ou x − 4 = 0.","detalhado":"Bhaskara também funciona nas incompletas, mas é mais lento. Quando c = 0, uma das raízes é sempre zero. Quando b = 0 e −c/a > 0, as raízes são simétricas (±√(−c/a))."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"forma","prompt":"Qual destas é uma equação do 2º grau?","options":["3x + 2 = 0","x² − 5x + 6 = 0","x³ = 8","2x = 10"],"answer":1,"hints":["Procure o maior expoente do x.","No 2º grau, o maior expoente é 2.","Qual tem x²?"],"explanation":"x² − 5x + 6 = 0 tem x² como maior potência: é do 2º grau."},{"id":"q2","type":"mc","difficulty":1,"skill":"forma","prompt":"Em 2x² − 3x + 1 = 0, quais são a, b e c?","options":["a=2, b=3, c=1","a=2, b=−3, c=1","a=−3, b=2, c=1","a=1, b=−3, c=2"],"answer":1,"hints":["a acompanha x², b acompanha x.","O sinal faz parte do coeficiente.","O termo com x é −3x."],"explanation":"a = 2 (x²), b = −3 (x, com o sinal) e c = 1."},{"id":"q3","type":"tf","difficulty":1,"skill":"forma","prompt":"Em uma equação do 2º grau, o coeficiente a pode ser zero.","answer":false,"hints":["O que acontece com ax² se a = 0?","0 · x² = 0.","O x² desaparece."],"explanation":"Falso. Se a = 0 o termo x² some e a equação vira do 1º grau."},{"id":"q4","type":"fill","difficulty":2,"skill":"delta","prompt":"Calcule o Δ da equação x² − 5x + 6 = 0.","answers":["1"],"hints":["Δ = b² − 4ac.","a = 1, b = −5, c = 6.","(−5)² = 25 e 4·1·6 = 24."],"explanation":"Δ = 25 − 24 = 1."},{"id":"q5","type":"mc","difficulty":2,"skill":"delta","prompt":"Se Δ < 0, a equação:","options":["Tem duas raízes reais diferentes","Tem uma raiz real","Não tem raízes reais","Tem infinitas raízes"],"answer":2,"hints":["Na fórmula aparece √Δ.","Existe raiz quadrada real de número negativo?","Não existe."],"explanation":"Não existe raiz quadrada real de número negativo, então não há raízes reais."},{"id":"q6","type":"match","difficulty":2,"skill":"delta","prompt":"Ligue o valor do delta ao número de raízes reais.","pairs":[["Δ > 0","Duas raízes diferentes"],["Δ = 0","Duas raízes iguais"],["Δ < 0","Nenhuma raiz real"]],"hints":["Pense no ± da fórmula.","Se √Δ = 0, somar e subtrair dá o mesmo.","Negativo não tem raiz real."],"explanation":"Δ > 0: duas diferentes · Δ = 0: iguais · Δ < 0: nenhuma real."},{"id":"q7","type":"mc","difficulty":2,"skill":"bhaskara","prompt":"Quais são as raízes de x² − 5x + 6 = 0?","options":["1 e 6","2 e 3","−2 e −3","5 e 6"],"answer":1,"hints":["O Δ dessa equação é 1.","x = (5 ± 1) ÷ 2.","6 ÷ 2 e 4 ÷ 2."],"explanation":"x = (5 ± 1) ÷ 2 → 3 e 2. Conferindo: 9 − 15 + 6 = 0 ✓."},{"id":"q8","type":"fill","difficulty":2,"skill":"incompletas","prompt":"Qual é a raiz positiva de x² − 9 = 0?","answers":["3","+3"],"hints":["Não precisa de Bhaskara.","Passe o 9 para o outro lado.","x² = 9. Que número vezes ele mesmo dá 9?"],"explanation":"x² = 9 → x = ±3. A positiva é 3."},{"id":"q9","type":"mc","difficulty":3,"skill":"incompletas","prompt":"Quais são as raízes de x² − 4x = 0?","options":["0 e 4","2 e −2","4 e −4","Só 4"],"answer":0,"hints":["Falta o c.","Coloque x em evidência.","x(x − 4) = 0."],"explanation":"x(x − 4) = 0 → x = 0 ou x = 4."},{"id":"q10","type":"mc","difficulty":3,"skill":"bhaskara","prompt":"Quais são as raízes de x² + 2x − 8 = 0?","options":["2 e −4","−2 e 4","4 e 8","1 e −8"],"answer":0,"hints":["Δ = 4 − 4·1·(−8).","Δ = 36, √Δ = 6.","x = (−2 ± 6) ÷ 2."],"explanation":"Δ = 36 → x = (−2 ± 6) ÷ 2 → 2 e −4."},{"id":"q11","type":"tf","difficulty":2,"skill":"delta","prompt":"Quando Δ = 0, a equação tem duas raízes reais iguais.","answer":true,"hints":["Quanto é √0?","−b + 0 e −b − 0.","Dá o mesmo resultado."],"explanation":"Verdadeiro. Com √Δ = 0, as duas contas dão o mesmo valor."},{"id":"q12","type":"mc","difficulty":3,"skill":"bhaskara","prompt":"Quais são as raízes de 2x² − 8x + 6 = 0?","options":["1 e 3","2 e 6","−1 e −3","4 e 2"],"answer":0,"hints":["a = 2, b = −8, c = 6.","Δ = 64 − 48 = 16.","x = (8 ± 4) ÷ 4."],"explanation":"Δ = 16 → x = (8 ± 4) ÷ 4 → 3 e 1."}],"review":["Forma geral: ax² + bx + c = 0, com a ≠ 0","Δ = b² − 4ac","x = (−b ± √Δ) ÷ 2a","Incompletas: evidência (c = 0) ou isolar x² (b = 0)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Geometria","subtopic":"Triângulo retângulo","relatedQuestions":["Como calcular a hipotenusa?","O que diz o teorema de Pitágoras?","Como achar o cateto?"],"id":"mat-teorema-pitagoras","subject":"matematica","title":"Teorema de Pitágoras","levels":["fund2","medio"],"grade":"9º ano","aliases":["pitagoras","teorema de pitagoras","triangulo retangulo","hipotenusa","catetos"],"summary":"Descubra a relação entre os lados de um triângulo retângulo e use-a para calcular medidas.","intro":"Há mais de 2 mil anos já se sabia um segredo dos triângulos com um ângulo reto. Vamos a ele!","skills":{"elementos":"Hipotenusa e catetos","teorema":"A fórmula a² = b² + c²","calculo":"Calcular um lado","aplicacoes":"Aplicações"},"blocks":[{"id":"b1","skill":"elementos","title":"O triângulo retângulo","text":"Triângulo retângulo é o que tem um ângulo de 90° (ângulo reto). O lado oposto ao ângulo reto é a hipotenusa — sempre o maior lado. Os outros dois são os catetos.","example":"No canto de uma folha de papel há um ângulo reto. A diagonal da folha faria o papel de hipotenusa."},{"id":"b2","skill":"teorema","title":"A relação de Pitágoras","text":"Em todo triângulo retângulo, o quadrado da hipotenusa é igual à soma dos quadrados dos catetos: a² = b² + c², em que a é a hipotenusa.","example":"Catetos 3 e 4: 3² + 4² = 9 + 16 = 25 = 5². A hipotenusa mede 5."},{"id":"b3","skill":"calculo","title":"Calculando o lado que falta","text":"Para achar a hipotenusa, some os quadrados dos catetos e tire a raiz. Para achar um cateto, subtraia do quadrado da hipotenusa o quadrado do outro cateto e tire a raiz.","example":"Hipotenusa 13 e cateto 5: c² = 169 − 25 = 144 → c = 12."},{"id":"b4","skill":"aplicacoes","title":"Onde isso aparece","text":"O teorema calcula distâncias em diagonal: a altura que uma escada alcança numa parede, a diagonal de uma tela ou de um terreno.","example":"Escada de 5 m com o pé a 3 m da parede alcança √(25 − 9) = 4 m de altura."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"elementos","prompt":"Num triângulo retângulo, o lado oposto ao ângulo reto se chama:","options":["Cateto","Hipotenusa","Base","Mediana"],"answer":1,"hints":["É o maior lado.","Não é cateto.","Começa com H."],"explanation":"A hipotenusa fica oposta ao ângulo de 90°."},{"id":"q2","type":"tf","difficulty":1,"skill":"elementos","prompt":"A hipotenusa é sempre o maior lado do triângulo retângulo.","answer":true,"hints":["Ela fica oposta ao maior ângulo.","O maior ângulo é o de 90°.","Maior ângulo → maior lado."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"teorema","prompt":"Qual é a fórmula do Teorema de Pitágoras (a = hipotenusa)?","options":["a = b + c","a² = b² + c²","a² = b + c","a = b² − c²"],"answer":1,"hints":["Envolve quadrados.","A hipotenusa fica sozinha de um lado.","Soma dos quadrados dos catetos."],"explanation":"a² = b² + c²."},{"id":"q4","type":"fill","difficulty":2,"skill":"calculo","prompt":"Os catetos medem 3 e 4. Quanto mede a hipotenusa?","answers":["5"],"hints":["Calcule 3² + 4².","9 + 16 = 25.","Raiz de 25."],"explanation":"a² = 25 → a = 5."},{"id":"q5","type":"fill","difficulty":2,"skill":"calculo","prompt":"Os catetos medem 6 e 8. Quanto mede a hipotenusa?","answers":["10"],"hints":["6² + 8².","36 + 64 = 100.","√100."],"explanation":"a² = 100 → a = 10."},{"id":"q6","type":"mc","difficulty":2,"skill":"calculo","prompt":"A hipotenusa mede 13 e um cateto mede 5. Quanto mede o outro cateto?","options":["8","12","18","10"],"answer":1,"hints":["c² = 13² − 5².","169 − 25 = 144.","√144."],"explanation":"c² = 144 → c = 12."},{"id":"q7","type":"match","difficulty":2,"skill":"elementos","prompt":"Ligue cada termo à descrição.","pairs":[["Hipotenusa","Maior lado, oposto ao ângulo reto"],["Catetos","Lados que formam o ângulo reto"],["Ângulo reto","Mede 90°"],["a² = b² + c²","Teorema de Pitágoras"]],"hints":["O ângulo reto é o do \"canto\".","Os catetos o formam.","A fórmula tem nome de um matemático grego."],"explanation":"Hipotenusa: maior lado · catetos: formam o ângulo reto · ângulo reto: 90° · a² = b² + c²: Pitágoras."},{"id":"q8","type":"mc","difficulty":3,"skill":"aplicacoes","prompt":"Uma escada de 5 m está apoiada numa parede, com o pé a 3 m dela. Que altura ela alcança?","options":["2 m","4 m","8 m","√34 m"],"answer":1,"hints":["A escada é a hipotenusa.","h² = 5² − 3².","25 − 9 = 16."],"explanation":"h = √16 = 4 m."},{"id":"q9","type":"tf","difficulty":3,"skill":"teorema","prompt":"O Teorema de Pitágoras vale para qualquer triângulo.","answer":false,"hints":["Releia a condição do teorema.","Precisa ter um ângulo especial.","Só com ângulo de 90°."],"explanation":"Falso. Vale apenas para triângulos retângulos."},{"id":"q10","type":"open","difficulty":3,"skill":"aplicacoes","prompt":"Explique como você usaria o Teorema de Pitágoras para descobrir a diagonal de um terreno retangular de 30 m por 40 m.","modelAnswer":"A diagonal divide o retângulo em dois triângulos retângulos. Os lados 30 e 40 são os catetos e a diagonal é a hipotenusa: d² = 30² + 40² = 900 + 1600 = 2500, então d = 50 m.","keywords":["cateto","hipotenusa","triangulo","2500","50","quadrado","raiz"],"hints":["A diagonal forma que tipo de triângulo?","Quem são os catetos?","Some 30² e 40² e tire a raiz."],"explanation":"Catetos 30 e 40, hipotenusa = diagonal = 50 m."}],"review":["Triângulo retângulo: um ângulo de 90°","Hipotenusa = maior lado; catetos formam o ângulo reto","a² = b² + c²","Serve para distâncias em diagonal"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Funções","subtopic":"Função afim","relatedQuestions":["O que é função do primeiro grau?","Como achar a raiz da função?","O que é coeficiente angular?"],"id":"mat-funcao-1-grau","subject":"matematica","title":"Função do 1º grau","levels":["medio"],"grade":"1ª série","aliases":["funcao afim","funcao do primeiro grau","funcao do 1 grau","funcao linear","coeficiente angular","grafico de funcao"],"summary":"Entenda a função f(x) = ax + b, seus coeficientes, a raiz e o gráfico em linha reta.","intro":"Funções descrevem relações: quanto mais você anda de táxi, mais paga. Vamos ver a mais simples delas.","skills":{"forma":"Forma f(x) = ax + b","coeficientes":"Coeficientes a e b","raiz":"Raiz da função","grafico":"Gráfico e crescimento"},"blocks":[{"id":"b1","skill":"forma","title":"O que é a função afim","text":"A função do 1º grau tem a forma f(x) = ax + b, com a ≠ 0. Para cada valor de x, a função devolve um único valor f(x).","example":"Táxi com bandeirada de R$ 5 e R$ 2 por km: f(x) = 2x + 5. Em 10 km: f(10) = 25 reais."},{"id":"b2","skill":"coeficientes","title":"Os coeficientes a e b","text":"O coeficiente a (angular) indica quanto f(x) muda quando x aumenta 1. O coeficiente b (linear) é o valor de f(x) quando x = 0 — o ponto onde a reta corta o eixo y.","example":"Em f(x) = 2x + 5, cada km a mais custa 2 reais (a = 2), e o valor inicial é 5 (b = 5)."},{"id":"b3","skill":"raiz","title":"A raiz (zero da função)","text":"A raiz é o valor de x que faz f(x) = 0. Basta resolver ax + b = 0, que dá x = −b/a. No gráfico, é onde a reta corta o eixo x.","example":"f(x) = 2x − 6 → 2x − 6 = 0 → x = 3."},{"id":"b4","skill":"grafico","title":"Gráfico: uma reta","text":"O gráfico da função afim é sempre uma reta. Se a > 0, a função é crescente (a reta sobe); se a < 0, é decrescente (a reta desce).","example":"f(x) = −x + 4 é decrescente: quando x aumenta, f(x) diminui."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"forma","prompt":"Qual destas é uma função do 1º grau?","options":["f(x) = x² + 1","f(x) = 3x − 2","f(x) = 5","f(x) = 1/x"],"answer":1,"hints":["A forma é ax + b.","O x não pode estar ao quadrado.","Procure \"número vezes x mais número\"."],"explanation":"f(x) = 3x − 2 tem a forma ax + b com a = 3."},{"id":"q2","type":"fill","difficulty":1,"skill":"forma","prompt":"Se f(x) = 2x + 5, quanto vale f(10)?","answers":["25"],"hints":["Troque x por 10.","2 · 10 + 5.","20 + 5."],"explanation":"f(10) = 20 + 5 = 25."},{"id":"q3","type":"mc","difficulty":1,"skill":"coeficientes","prompt":"Em f(x) = 4x − 7, qual é o coeficiente angular?","options":["4","−7","x","−3"],"answer":0,"hints":["O angular acompanha o x.","É o \"a\" de ax + b.","O número na frente do x."],"explanation":"a = 4."},{"id":"q4","type":"tf","difficulty":1,"skill":"grafico","prompt":"O gráfico de uma função do 1º grau é uma reta.","answer":true,"hints":["Pense na forma do desenho.","Não é curva.","É uma linha reta."],"explanation":"Verdadeiro."},{"id":"q5","type":"fill","difficulty":2,"skill":"raiz","prompt":"Qual é a raiz de f(x) = 2x − 6?","answers":["3"],"hints":["Faça f(x) = 0.","2x − 6 = 0.","2x = 6."],"explanation":"x = 3."},{"id":"q6","type":"mc","difficulty":2,"skill":"grafico","prompt":"A função f(x) = −3x + 1 é:","options":["Crescente","Decrescente","Constante","Não é função"],"answer":1,"hints":["Olhe o sinal de a.","a = −3.","a negativo → reta desce."],"explanation":"a < 0: decrescente."},{"id":"q7","type":"match","difficulty":2,"skill":"coeficientes","prompt":"Ligue cada termo ao significado.","pairs":[["Coeficiente a","Taxa de variação"],["Coeficiente b","Onde a reta corta o eixo y"],["Raiz","Onde a reta corta o eixo x"],["a > 0","Função crescente"]],"hints":["b é o valor quando x = 0.","A raiz faz f(x) = 0.","a positivo sobe."],"explanation":"a: variação · b: corte no eixo y · raiz: corte no eixo x · a > 0: crescente."},{"id":"q8","type":"mc","difficulty":3,"skill":"forma","prompt":"Um plano de celular custa R$ 30 fixos mais R$ 0,50 por minuto. Qual função representa o valor f(x) para x minutos?","options":["f(x) = 30x + 0,5","f(x) = 0,5x + 30","f(x) = 30,5x","f(x) = 0,5x − 30"],"answer":1,"hints":["O que depende dos minutos?","R$ 0,50 multiplica x.","O fixo é o b."],"explanation":"f(x) = 0,5x + 30."},{"id":"q9","type":"fill","difficulty":3,"skill":"raiz","prompt":"Qual é a raiz de f(x) = −4x + 12?","answers":["3"],"hints":["−4x + 12 = 0.","−4x = −12.","x = −12 ÷ −4."],"explanation":"x = 3."},{"id":"q10","type":"tf","difficulty":3,"skill":"coeficientes","prompt":"Em f(x) = 5x + 2, o gráfico corta o eixo y no ponto (0, 2).","answer":true,"hints":["O eixo y é onde x = 0.","f(0) = 5·0 + 2.","f(0) = 2."],"explanation":"Verdadeiro: f(0) = b = 2."}],"review":["f(x) = ax + b, com a ≠ 0","a = taxa de variação · b = valor inicial","Raiz: x = −b/a","a > 0 cresce · a < 0 decresce · gráfico é reta"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Classes gramaticais","subtopic":"Substantivo e adjetivo","relatedQuestions":["O que é substantivo?","O que é adjetivo?","Qual a diferença entre substantivo próprio e comum?"],"id":"por-substantivo-adjetivo","subject":"portugues","title":"Substantivo e adjetivo","levels":["fund1","fund2"],"grade":"3º ao 6º ano","aliases":["gramatica","substantivo","adjetivo","classes gramaticais","classes de palavras","substantivo proprio","substantivo comum","concordancia nominal"],"summary":"Aprenda a reconhecer substantivos e adjetivos e a fazer a concordância entre eles.","intro":"As palavras têm \"profissões\" diferentes numa frase. Hoje vamos conhecer duas muito importantes: o substantivo e o adjetivo.","skills":{"substantivo":"Reconhecer substantivos","tipos":"Substantivo comum e próprio","adjetivo":"Reconhecer adjetivos","concordancia":"Concordância"},"blocks":[{"id":"b1","skill":"substantivo","title":"Substantivo: a palavra que dá nome","text":"Substantivo é a palavra que dá nome a pessoas, animais, lugares, objetos, sentimentos e ideias.","example":"Em \"O cachorro correu no parque\", as palavras cachorro e parque são substantivos.","variants":{"simples":"Tudo o que tem nome é substantivo: mesa, gato, mãe, escola, alegria.","exemplo":"Olhe ao seu redor: celular, cadeira, janela, caderno. Todos esses nomes são substantivos.","outra":"Um teste: se dá para colocar \"o\", \"a\", \"um\" ou \"uma\" antes da palavra, ela provavelmente é um substantivo. \"Um sonho\", \"a amizade\", \"o lápis\".","detalhado":"Os substantivos podem ser concretos (seres com existência própria, reais ou imaginários: casa, fada) ou abstratos (dependem de outro ser para existir: saudade, beleza, coragem). Também variam em gênero (menino/menina) e número (menino/meninos)."}},{"id":"b2","skill":"tipos","title":"Comum ou próprio","text":"O substantivo comum nomeia qualquer ser de uma espécie (cidade, rio, menina). O substantivo próprio nomeia um ser específico e é escrito com letra maiúscula (Itajaí, Amazonas, Maria).","example":"\"rio\" é comum; \"Rio Amazonas\" usa um substantivo próprio para dizer qual rio.","variants":{"simples":"Comum: nome de qualquer um (cachorro). Próprio: nome de um só, com letra maiúscula (Totó).","exemplo":"Você mora numa cidade (comum). O nome da sua cidade, como Florianópolis, é próprio.","outra":"Pergunte: \"é o nome de um tipo de coisa ou o nome de alguém/lugar em especial?\". Tipo = comum. Especial = próprio.","detalhado":"Nomes de pessoas, cidades, países, rios, planetas, instituições e datas comemorativas costumam ser próprios. Um mesmo termo pode mudar: \"sol\" (qualquer estrela) × \"Sol\" (a estrela do nosso sistema)."}},{"id":"b3","skill":"adjetivo","title":"Adjetivo: a palavra que caracteriza","text":"Adjetivo é a palavra que dá uma característica ao substantivo: qualidade, estado, cor, tamanho, origem.","example":"Em \"A casa amarela é bonita\", as palavras amarela e bonita são adjetivos que caracterizam \"casa\".","variants":{"simples":"Adjetivo diz \"como é\" a coisa: grande, azul, feliz, gostoso.","exemplo":"Um cachorro. Um cachorro pequeno. Um cachorro pequeno e brincalhão. Pequeno e brincalhão são adjetivos.","outra":"Pergunte \"como é?\" para o substantivo. A resposta é o adjetivo. \"Como é o menino?\" → \"inteligente\".","detalhado":"A classe de uma palavra depende da função na frase. Em \"O velho abriu a porta\", velho nomeia a pessoa (substantivo). Em \"O homem velho abriu a porta\", velho caracteriza o homem (adjetivo). Adjetivos também têm locuções: \"amor de mãe\" = amor materno."}},{"id":"b4","skill":"concordancia","title":"Concordância","text":"O adjetivo concorda com o substantivo em gênero (masculino/feminino) e número (singular/plural).","example":"Menino cansado → meninas cansadas. Blusa bonita → blusas bonitas.","variants":{"simples":"Se o nome está no plural, o adjetivo também vai. Se o nome é feminino, o adjetivo também fica feminino.","exemplo":"\"As meninas estão cansadas\" está certo. \"As meninas estão cansado\" está errado, porque \"cansado\" não acompanhou \"meninas\".","outra":"Substantivo e adjetivo andam \"de mãos dadas\": o que acontece com um (plural, feminino) acontece com o outro.","detalhado":"Quando um adjetivo se refere a substantivos de gêneros diferentes, costuma ir para o masculino plural: \"O menino e a menina estão atentos\". Alguns adjetivos têm forma única para os dois gêneros: feliz, inteligente, azul."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"substantivo","prompt":"Em \"O cachorro correu\", qual palavra é um substantivo?","options":["O","cachorro","correu","Nenhuma"],"answer":1,"hints":["Substantivo dá nome.","Qual palavra é o nome de um animal?","Dá para dizer \"um ______\"."],"explanation":"\"Cachorro\" dá nome a um animal: é substantivo."},{"id":"q2","type":"mc","difficulty":1,"skill":"adjetivo","prompt":"Em \"A casa amarela é bonita\", quais são os adjetivos?","options":["casa e bonita","amarela e bonita","A e casa","casa e é"],"answer":1,"hints":["Adjetivo responde \"como é?\".","Como é a casa?","Tem uma cor e uma qualidade."],"explanation":"\"Amarela\" (cor) e \"bonita\" (qualidade) caracterizam a casa."},{"id":"q3","type":"tf","difficulty":1,"skill":"tipos","prompt":"\"Brasil\" é um substantivo próprio.","answer":true,"hints":["É o nome de um lugar específico?","Existe só um Brasil.","E é escrito com maiúscula."],"explanation":"Verdadeiro. Nomeia um país específico e vai com maiúscula."},{"id":"q4","type":"fill","difficulty":2,"skill":"tipos","prompt":"O substantivo próprio é escrito com letra ________.","answers":["maiuscula","maiúscula"],"hints":["Olhe como se escreve \"Maria\".","A primeira letra é grande.","O contrário de minúscula."],"explanation":"Com letra maiúscula."},{"id":"q5","type":"mc","difficulty":2,"skill":"tipos","prompt":"Qual destas palavras é um substantivo comum?","options":["Itajaí","Maria","cidade","Amazonas"],"answer":2,"hints":["Comum nomeia qualquer ser de um tipo.","Três delas estão com maiúscula.","Qual nomeia um tipo de lugar?"],"explanation":"\"Cidade\" nomeia qualquer cidade: é comum."},{"id":"q6","type":"match","difficulty":2,"skill":"adjetivo","prompt":"Ligue cada palavra à sua classe.","pairs":[["gato","Substantivo comum"],["Paulo","Substantivo próprio"],["alegre","Adjetivo"],["correr","Verbo (ação)"]],"hints":["Qual é nome de pessoa?","Qual diz \"como é\"?","Qual indica uma ação?"],"explanation":"gato → comum; Paulo → próprio; alegre → adjetivo; correr → verbo."},{"id":"q7","type":"tf","difficulty":2,"skill":"adjetivo","prompt":"Em \"o menino inteligente\", a palavra \"inteligente\" é um substantivo.","answer":false,"hints":["Como é o menino?","A palavra responde \"como é?\".","Isso é função de adjetivo."],"explanation":"Falso. \"Inteligente\" caracteriza o menino: é adjetivo."},{"id":"q8","type":"mc","difficulty":2,"skill":"concordancia","prompt":"Qual frase está com a concordância correta?","options":["As meninas estão cansado.","As meninas estão cansadas.","A meninas estão cansadas.","As menina estão cansadas."],"answer":1,"hints":["\"Meninas\" é feminino e plural.","O adjetivo acompanha.","Procure \"-as\" no adjetivo."],"explanation":"\"As meninas estão cansadas\": tudo no feminino plural."},{"id":"q9","type":"fill","difficulty":3,"skill":"concordancia","prompt":"Complete com o adjetivo \"bonito\" na forma correta: \"Comprei duas blusas ________.\"","answers":["bonitas"],"hints":["\"Blusas\" é feminino.","E está no plural.","Bonit + as."],"explanation":"\"Bonitas\", concordando com \"blusas\" (feminino plural)."},{"id":"q10","type":"mc","difficulty":3,"skill":"substantivo","prompt":"Em \"O velho abriu a porta\", a palavra \"velho\" é:","options":["Adjetivo","Substantivo","Verbo","Artigo"],"answer":1,"hints":["Aqui não existe \"homem\" na frase.","A palavra está nomeando quem abriu a porta.","Tem \"o\" antes dela."],"explanation":"Aqui \"velho\" nomeia a pessoa, funcionando como substantivo."},{"id":"q11","type":"tf","difficulty":3,"skill":"concordancia","prompt":"O adjetivo concorda em gênero e número com o substantivo.","answer":true,"hints":["Lembre do \"de mãos dadas\".","Blusa bonita → blusas bonitas.","Muda junto."],"explanation":"Verdadeiro. É a regra da concordância nominal."},{"id":"q12","type":"open","difficulty":2,"skill":"adjetivo","prompt":"Explique com suas palavras a diferença entre substantivo e adjetivo.","modelAnswer":"O substantivo dá nome às coisas, pessoas, lugares e sentimentos. O adjetivo dá uma característica ou qualidade ao substantivo. Ex.: em \"gato preto\", gato é substantivo e preto é adjetivo.","keywords":["nome","nomeia","caracteristica","qualidade","caracteriza","como e"],"hints":["Um deles dá nome.","O outro diz como a coisa é.","Use um exemplo, como \"gato preto\"."],"explanation":"Substantivo nomeia; adjetivo caracteriza o substantivo."}],"review":["Substantivo = dá nome","Comum (qualquer um) × próprio (específico, maiúscula)","Adjetivo = dá característica (\"como é?\")","Concordância em gênero e número"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Classes gramaticais","subtopic":"Verbo","relatedQuestions":["O que é verbo?","Quais são os tempos verbais?","O que é modo subjuntivo?","Como conjugar um verbo?"],"id":"por-verbos","subject":"portugues","title":"Verbos e tempos verbais","levels":["fund1","fund2"],"grade":"4º ao 7º ano","aliases":["verbo","verbos","tempos verbais","presente passado futuro","preterito","conjugacao","modo indicativo","subjuntivo","imperativo"],"summary":"Reconheça verbos, os tempos presente, passado e futuro e os modos verbais.","intro":"Os verbos contam o que acontece e quando acontece. Vamos conhecê-los!","skills":{"conceito":"O que é verbo","tempos":"Presente, pretérito e futuro","modos":"Modos verbais","conjugacao":"Concordância do verbo com a pessoa"},"blocks":[{"id":"b1","skill":"conceito","title":"Verbo indica ação, estado ou fenômeno","text":"Verbo é a palavra que indica ação (correr, estudar), estado (ser, estar, ficar) ou fenômeno da natureza (chover, ventar). Ele muda conforme o tempo e a pessoa.","example":"Ana corre. · Ana está feliz. · Choveu ontem.","variants":{"simples":"Verbo é a palavra que mostra o que alguém faz ou como está: pular, comer, ser, estar."}},{"id":"b2","skill":"tempos","title":"Presente, passado e futuro","text":"O presente indica o que acontece agora (eu estudo). O pretérito (passado) indica o que já aconteceu (eu estudei, eu estudava). O futuro indica o que ainda vai acontecer (eu estudarei).","example":"Hoje eu jogo. Ontem eu joguei. Amanhã eu jogarei.","variants":{"simples":"Agora: eu brinco. Já passou: eu brinquei. Ainda vai acontecer: eu brincarei."}},{"id":"b3","skill":"modos","title":"Os três modos","text":"Indicativo expressa certeza (Ele viaja amanhã). Subjuntivo expressa dúvida ou desejo (Talvez ele viaje; Espero que ele viaje). Imperativo expressa ordem ou pedido (Viaje com cuidado!).","example":"Estude! (imperativo) · Se eu estudasse… (subjuntivo) · Eu estudo. (indicativo)"},{"id":"b4","skill":"conjugacao","title":"O verbo acompanha a pessoa","text":"O verbo muda de forma para concordar com quem faz a ação: eu canto, tu cantas, ele canta, nós cantamos, vós cantais, eles cantam.","example":"\"Nós canta\" está errado; o correto é \"nós cantamos\".","variants":{"simples":"Eu canto, ele canta, nós cantamos, eles cantam. O verbo muda junto com quem faz."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Na frase \"O menino pulou o muro\", qual palavra é o verbo?","options":["menino","pulou","muro","o"],"answer":1,"hints":["Qual palavra mostra uma ação?","O que o menino fez?","Ele…"],"explanation":"\"Pulou\" indica a ação."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceito","prompt":"\"Chover\" é um verbo.","answer":true,"hints":["Verbo pode indicar fenômeno da natureza.","Chuva acontece.","Choveu, choverá…"],"explanation":"Verdadeiro: indica um fenômeno da natureza."},{"id":"q3","type":"mc","difficulty":1,"skill":"tempos","prompt":"\"Eu estudei para a prova.\" O verbo está no:","options":["Presente","Passado (pretérito)","Futuro","Imperativo"],"answer":1,"hints":["A ação já aconteceu ou vai acontecer?","Já aconteceu.","Passado também se chama pretérito."],"explanation":"\"Estudei\" está no pretérito (passado)."},{"id":"q4","type":"fill","difficulty":2,"skill":"tempos","prompt":"Complete no futuro: \"Amanhã eu ______ (viajar) para a praia.\"","answers":["viajarei","vou viajar"],"hints":["Vai acontecer depois.","Futuro com \"eu\" termina em -rei.","Viaja + rei."],"explanation":"\"Viajarei\" (ou \"vou viajar\")."},{"id":"q5","type":"match","difficulty":2,"skill":"tempos","prompt":"Ligue cada frase ao tempo do verbo.","pairs":[["Eu como maçã agora.","Presente"],["Eu comi maçã ontem.","Pretérito"],["Eu comerei maçã amanhã.","Futuro"]],"hints":["Olhe as palavras \"agora\", \"ontem\" e \"amanhã\".","Ontem = passado.","Amanhã = futuro."],"explanation":"Como → presente · comi → pretérito · comerei → futuro."},{"id":"q6","type":"mc","difficulty":2,"skill":"conjugacao","prompt":"Qual frase está correta?","options":["Nós canta no coral.","Nós cantamos no coral.","Nós cantam no coral.","Nós canto no coral."],"answer":1,"hints":["O verbo concorda com \"nós\".","Com \"nós\" o verbo termina em -mos.","Canta + mos."],"explanation":"\"Nós cantamos\"."},{"id":"q7","type":"mc","difficulty":2,"skill":"modos","prompt":"\"Feche a porta, por favor!\" O verbo está no modo:","options":["Indicativo","Subjuntivo","Imperativo","Infinitivo"],"answer":2,"hints":["A frase é um pedido.","Pedido ou ordem.","Modo das ordens."],"explanation":"Imperativo: ordem ou pedido."},{"id":"q8","type":"tf","difficulty":3,"skill":"modos","prompt":"Em \"Talvez ele chegue cedo\", o verbo está no modo subjuntivo.","answer":true,"hints":["\"Talvez\" indica certeza ou dúvida?","Dúvida.","Dúvida → subjuntivo."],"explanation":"Verdadeiro: expressa dúvida."},{"id":"q9","type":"fill","difficulty":3,"skill":"conjugacao","prompt":"Complete: \"Eles ______ (estudar) todos os dias.\"","answers":["estudam"],"hints":["Presente, com \"eles\".","Com \"eles\" termina em -am.","Estud + am."],"explanation":"\"Eles estudam\"."},{"id":"q10","type":"mc","difficulty":3,"skill":"tempos","prompt":"\"Quando eu era criança, eu brincava na rua.\" O verbo \"brincava\" indica:","options":["Ação terminada num momento exato","Ação que se repetia no passado","Ação no futuro","Uma ordem"],"answer":1,"hints":["É passado.","Acontecia uma vez ou várias?","Era um costume."],"explanation":"O pretérito imperfeito (\"brincava\") indica ação habitual no passado."}],"review":["Verbo = ação, estado ou fenômeno","Presente · pretérito · futuro","Indicativo (certeza) · subjuntivo (dúvida/desejo) · imperativo (ordem)","O verbo concorda com a pessoa"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Sintaxe","subtopic":"Termos essenciais da oração","relatedQuestions":["Como encontrar o sujeito da frase?","O que é predicado?","O que é sujeito oculto?","O que é oração sem sujeito?"],"id":"por-sujeito-predicado","subject":"portugues","title":"Sujeito e predicado","levels":["fund2","medio"],"grade":"7º e 8º ano","aliases":["sujeito","predicado","analise sintatica","termos essenciais da oracao","sujeito oculto","sujeito composto","oracao sem sujeito"],"summary":"Identifique o sujeito e o predicado e conheça os tipos de sujeito.","intro":"Toda frase conta algo sobre alguém. Vamos descobrir quem é esse \"alguém\" e o que se diz dele.","skills":{"conceito":"Sujeito e predicado","identificar":"Como encontrar o sujeito","tipos":"Tipos de sujeito","sem_sujeito":"Oração sem sujeito"},"blocks":[{"id":"b1","skill":"conceito","title":"De quem se fala e o que se diz","text":"Sujeito é o termo sobre o qual se declara algo. Predicado é tudo o que se declara sobre o sujeito — e nele sempre está o verbo.","example":"\"Os alunos | fizeram a tarefa.\" Sujeito: os alunos. Predicado: fizeram a tarefa."},{"id":"b2","skill":"identificar","title":"A pergunta mágica","text":"Encontre o verbo e pergunte \"quem?\" ou \"o quê?\" antes dele. A resposta é o sujeito. O verbo concorda com o sujeito em número e pessoa.","example":"\"Chegaram as encomendas.\" O que chegou? As encomendas → sujeito (mesmo vindo depois do verbo)."},{"id":"b3","skill":"tipos","title":"Tipos de sujeito","text":"Simples: um núcleo (O cão latiu). Composto: dois ou mais núcleos (O cão e o gato brigaram). Oculto (desinencial): não aparece, mas é identificado pela terminação do verbo (Estudamos muito → nós). Indeterminado: não se sabe ou não se quer dizer quem é (Roubaram minha bicicleta).","example":"\"Fomos ao cinema\" → sujeito oculto: nós."},{"id":"b4","skill":"sem_sujeito","title":"Orações sem sujeito","text":"Algumas orações não têm sujeito: com verbos de fenômenos da natureza (Choveu muito), com \"haver\" no sentido de existir (Há dois alunos) e com \"fazer\" indicando tempo (Faz três anos).","example":"\"Nevou na serra\" não tem sujeito — ninguém \"faz\" a neve."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Em \"A professora explicou a matéria\", qual é o sujeito?","options":["explicou","a matéria","A professora","explicou a matéria"],"answer":2,"hints":["Ache o verbo: explicou.","Quem explicou?","A resposta é o sujeito."],"explanation":"Quem explicou? A professora."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceito","prompt":"O verbo faz parte do predicado.","answer":true,"hints":["O predicado é o que se diz do sujeito.","O verbo é o centro dessa informação.","Está sempre no predicado."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":2,"skill":"identificar","prompt":"Em \"Chegaram as encomendas\", qual é o sujeito?","options":["Chegaram","as encomendas","Não há sujeito","Nós"],"answer":1,"hints":["O sujeito pode vir depois do verbo.","O que chegou?","O verbo está no plural por causa dele."],"explanation":"\"As encomendas\" chegaram."},{"id":"q4","type":"match","difficulty":2,"skill":"tipos","prompt":"Ligue cada frase ao tipo de sujeito.","pairs":[["O cão latiu.","Simples"],["Ana e Pedro saíram.","Composto"],["Estudamos muito.","Oculto"],["Roubaram minha bicicleta.","Indeterminado"]],"hints":["Conte os núcleos.","Em \"Estudamos\", quem é?","Em \"Roubaram\", sabemos quem foi?"],"explanation":"Simples · composto · oculto (nós) · indeterminado."},{"id":"q5","type":"fill","difficulty":2,"skill":"tipos","prompt":"Em \"Fomos ao cinema\", o sujeito oculto é: ______","answers":["nos","nós"],"hints":["Olhe a terminação do verbo.","\"-mos\" indica qual pessoa?","Primeira pessoa do plural."],"explanation":"Nós (sujeito oculto)."},{"id":"q6","type":"mc","difficulty":2,"skill":"sem_sujeito","prompt":"Qual destas orações NÃO tem sujeito?","options":["Maria cantou.","Choveu a noite toda.","Os meninos correram.","Eu li o livro."],"answer":1,"hints":["Procure um fenômeno da natureza.","Quem \"faz\" a chuva?","Ninguém."],"explanation":"\"Choveu a noite toda\" é oração sem sujeito."},{"id":"q7","type":"tf","difficulty":3,"skill":"sem_sujeito","prompt":"Em \"Há muitos alunos na sala\", o sujeito é \"muitos alunos\".","answer":false,"hints":["\"Haver\" aqui significa existir.","Com esse sentido, o verbo é impessoal.","Impessoal = sem sujeito."],"explanation":"Falso. \"Haver\" = existir é impessoal: oração sem sujeito (\"muitos alunos\" é objeto direto)."},{"id":"q8","type":"mc","difficulty":3,"skill":"identificar","prompt":"Qual frase tem a concordância correta?","options":["Faltou dois alunos.","Faltaram dois alunos.","Faltou os alunos.","Faltaram o aluno."],"answer":1,"hints":["Quem faltou?","\"Dois alunos\" é o sujeito, no plural.","O verbo vai para o plural."],"explanation":"\"Faltaram dois alunos\": o verbo concorda com o sujeito."},{"id":"q9","type":"mc","difficulty":3,"skill":"tipos","prompt":"\"Precisa-se de vendedores.\" O sujeito é:","options":["Simples","Oculto","Indeterminado","Composto"],"answer":2,"hints":["Quem precisa?","A frase não diz.","Verbo + \"se\" + preposição."],"explanation":"Sujeito indeterminado (índice de indeterminação do sujeito \"se\")."},{"id":"q10","type":"open","difficulty":3,"skill":"identificar","prompt":"Explique como você descobre o sujeito de uma oração.","modelAnswer":"Encontro o verbo e pergunto \"quem?\" ou \"o quê?\" fez a ação ou sobre quem se fala. A resposta é o sujeito. Depois confiro se o verbo concorda com ele.","keywords":["verbo","quem","que","concorda","pergunta"],"hints":["Qual palavra você procura primeiro?","Que pergunta você faz?","Fale do verbo e da pergunta \"quem?\"."],"explanation":"Ache o verbo e pergunte \"quem?/o quê?\"."}],"review":["Sujeito: de quem se fala · predicado: o que se diz","Ache o verbo e pergunte \"quem?\"","Simples, composto, oculto, indeterminado","Sem sujeito: fenômenos, haver = existir, fazer (tempo)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Leitura e produção de texto","subtopic":"Tipos e gêneros textuais","relatedQuestions":["Qual a diferença entre tipo e gênero textual?","O que é texto narrativo?","O que é texto dissertativo?","Como interpretar um texto?"],"id":"por-tipos-generos-textuais","subject":"portugues","title":"Tipos e gêneros textuais","levels":["fund2","medio"],"grade":"6º ao 9º ano","aliases":["interpretacao de texto","generos textuais","tipos textuais","texto narrativo","texto dissertativo","texto argumentativo","redacao","narracao descricao"],"summary":"Diferencie tipos textuais (narrar, descrever, argumentar…) de gêneros (notícia, crônica, receita…).","intro":"Uma receita e uma notícia são textos bem diferentes. Por quê? Vamos entender.","skills":{"tipos":"Tipos textuais","generos":"Gêneros textuais","diferenca":"Tipo × gênero","interpretacao":"Ler com objetivo"},"blocks":[{"id":"b1","skill":"tipos","title":"Os tipos textuais","text":"Tipo textual é o modo de organizar o texto. Narrativo conta fatos com personagens, tempo e lugar. Descritivo mostra como algo é. Dissertativo-argumentativo defende uma opinião com argumentos. Expositivo explica um assunto. Injuntivo dá instruções.","example":"\"Era uma vez…\" é narrativo. \"Misture a farinha e o ovo\" é injuntivo."},{"id":"b2","skill":"generos","title":"Os gêneros textuais","text":"Gênero textual é o \"formato\" que o texto tem no dia a dia, com uma função social: notícia, crônica, conto, receita, bula, carta, e-mail, anúncio, artigo de opinião.","example":"A receita serve para ensinar a preparar um prato; a notícia, para informar um fato recente."},{"id":"b3","skill":"diferenca","title":"Tipo × gênero","text":"Os tipos são poucos e fixos; os gêneros são muitos e surgem novos com o tempo (como o post de rede social). Um mesmo gênero pode misturar tipos: um conto narra e também descreve.","example":"Receita (gênero) usa principalmente o tipo injuntivo."},{"id":"b4","skill":"interpretacao","title":"Ler com objetivo","text":"Para interpretar, identifique o gênero e a finalidade do texto, quem escreveu e para quem, a ideia principal de cada parágrafo e as palavras que mostram opinião.","example":"Num artigo de opinião, expressões como \"é inaceitável\" revelam a posição do autor."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"tipos","prompt":"Um texto que começa com \"Era uma vez uma menina que…\" é do tipo:","options":["Descritivo","Narrativo","Injuntivo","Argumentativo"],"answer":1,"hints":["Ele conta uma história?","Tem personagem e acontecimentos.","Contar = narrar."],"explanation":"Narrativo: conta uma história."},{"id":"q2","type":"mc","difficulty":1,"skill":"generos","prompt":"Qual destes é um gênero textual?","options":["Narração","Receita","Descrição","Injunção"],"answer":1,"hints":["Gênero é o formato do dia a dia.","Três opções são tipos.","Qual você encontra num livro de culinária?"],"explanation":"Receita é um gênero; as outras são tipos."},{"id":"q3","type":"tf","difficulty":1,"skill":"tipos","prompt":"O texto injuntivo dá instruções ou ordens.","answer":true,"hints":["Pense num manual.","\"Aperte o botão…\"","Instrução = injunção."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"generos","prompt":"Ligue cada gênero à sua principal função.","pairs":[["Notícia","Informar um fato recente"],["Receita","Ensinar a preparar algo"],["Artigo de opinião","Defender um ponto de vista"],["Anúncio","Convencer a comprar ou aderir"]],"hints":["Qual quer vender?","Qual informa?","Qual defende uma ideia?"],"explanation":"Notícia informa, receita ensina, artigo opina, anúncio convence."},{"id":"q5","type":"mc","difficulty":2,"skill":"tipos","prompt":"\"A casa era pequena, com janelas azuis e um jardim florido.\" Esse trecho é predominantemente:","options":["Narrativo","Descritivo","Argumentativo","Injuntivo"],"answer":1,"hints":["Acontece alguma ação?","Ele mostra como a casa é.","Mostrar características = descrever."],"explanation":"Descritivo: apresenta características."},{"id":"q6","type":"tf","difficulty":2,"skill":"diferenca","prompt":"Existem muito mais gêneros textuais do que tipos textuais.","answer":true,"hints":["Os tipos são poucos.","Gêneros surgem com o tempo.","Ex.: post, meme, podcast…"],"explanation":"Verdadeiro."},{"id":"q7","type":"fill","difficulty":2,"skill":"tipos","prompt":"O tipo de texto que defende uma opinião com argumentos é o dissertativo-________.","answers":["argumentativo"],"hints":["Usa argumentos.","Argument…","É o tipo da redação do ENEM."],"explanation":"Dissertativo-argumentativo."},{"id":"q8","type":"mc","difficulty":3,"skill":"interpretacao","prompt":"Num artigo de opinião, qual expressão mostra mais claramente a posição do autor?","options":["\"Segundo o IBGE, a população cresceu.\"","\"É inaceitável que isso continue.\"","\"O evento ocorreu na segunda-feira.\"","\"A pesquisa ouviu 2 mil pessoas.\""],"answer":1,"hints":["Procure uma avaliação, não um dado.","Palavras que julgam.","\"Inaceitável\" é um julgamento."],"explanation":"\"É inaceitável\" expressa opinião; as outras apresentam fatos."},{"id":"q9","type":"mc","difficulty":3,"skill":"diferenca","prompt":"Um conto costuma ser:","options":["Um tipo textual injuntivo","Um gênero em que predomina a narração","Um gênero sem descrição","Um tipo textual expositivo"],"answer":1,"hints":["Conto é tipo ou gênero?","É gênero.","Ele conta uma história."],"explanation":"Conto é um gênero de tipo predominantemente narrativo."},{"id":"q10","type":"open","difficulty":3,"skill":"diferenca","prompt":"Explique a diferença entre tipo textual e gênero textual, dando um exemplo.","modelAnswer":"Tipo textual é o modo de organização do texto, como narrar, descrever, argumentar, expor ou instruir. Gênero textual é o formato usado no dia a dia com uma função social, como notícia, receita ou carta. Por exemplo, a receita é um gênero que usa o tipo injuntivo.","keywords":["tipo","genero","narrar","narrativo","funcao","formato","receita","noticia","injuntivo"],"hints":["Quais são os tipos?","Quais são alguns gêneros?","Dê o exemplo da receita."],"explanation":"Tipo = modo de organizar; gênero = formato social."}],"review":["Tipos: narrativo, descritivo, argumentativo, expositivo, injuntivo","Gêneros: notícia, receita, crônica, carta…","Gêneros misturam tipos","Interpretar: finalidade, autor, ideia principal"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Plantas","subtopic":"Fotossíntese","relatedQuestions":["Como as plantas produzem seu próprio alimento?","Como a planta se alimenta?","Por que as folhas são verdes?","Como as plantas fazem comida?","Para que serve a clorofila?"],"id":"cie-fotossintese","subject":"ciencias","title":"Fotossíntese","levels":["fund1","fund2","medio"],"grade":"6º e 7º ano","aliases":["fotossintese","clorofila","cloroplasto","como as plantas se alimentam","plantas produzem alimento"],"summary":"Descubra como as plantas fabricam o próprio alimento usando luz, água e gás carbônico.","intro":"As plantas não comem como nós. Elas fabricam o próprio alimento — e ainda liberam o oxigênio que respiramos.","skills":{"conceito":"O que é fotossíntese","ingredientes":"O que a planta usa","produtos":"O que a planta produz","importancia":"Importância para a vida"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é fotossíntese","text":"Fotossíntese é o processo em que plantas, algas e algumas bactérias usam a energia da luz para produzir o próprio alimento. \"Foto\" quer dizer luz e \"síntese\" quer dizer produção.","example":"Uma planta num vaso perto da janela cresce usando a luz do sol. Sem luz, ela fica fraca e amarelada.","variants":{"simples":"A planta é como uma cozinha movida a luz do sol: ela pega luz e faz a própria comida.","exemplo":"Por isso colocamos as plantas perto da janela. Se deixarmos um vaso num armário escuro por semanas, a planta enfraquece porque não consegue fazer a fotossíntese.","outra":"Nós precisamos comer para ter energia. A planta não: ela transforma a energia da luz em energia guardada num açúcar, e usa esse açúcar para viver e crescer.","detalhado":"A fotossíntese acontece em duas etapas: na fase clara, a energia luminosa é captada pela clorofila e a água é quebrada, liberando oxigênio; na fase escura (que não precisa de luz diretamente), o gás carbônico é fixado e transformado em glicose."}},{"id":"b2","skill":"ingredientes","title":"Os ingredientes","text":"A planta precisa de água (absorvida pelas raízes), gás carbônico (que entra pelas folhas, por pequenas aberturas chamadas estômatos) e luz. Quem capta a luz é a clorofila, um pigmento verde que fica dentro dos cloroplastos.","example":"É por causa da clorofila que a maioria das folhas é verde.","variants":{"simples":"A receita da planta: água + gás carbônico do ar + luz do sol. A parte verde da folha (clorofila) é quem \"pega\" a luz.","exemplo":"Quando você rega uma planta, a água sobe da raiz até a folha. Ao mesmo tempo, a folha \"puxa\" gás carbônico do ar. Com a luz do sol, está tudo pronto.","outra":"Pense numa fábrica: a água chega por um cano (raiz), o gás carbônico entra pelas janelas (estômatos), e a clorofila é o painel solar que liga as máquinas.","detalhado":"Os cloroplastos são organelas presentes principalmente nas células das folhas. A clorofila absorve bem luz vermelha e azul e reflete o verde. A água é transportada pelo xilema, e a abertura dos estômatos controla a entrada de CO₂ e a perda de água."}},{"id":"b3","skill":"produtos","title":"O que a planta produz","text":"O resultado da fotossíntese é a glicose (um açúcar que é o alimento da planta) e o gás oxigênio, que é liberado no ar. Resumindo: gás carbônico + água + luz → glicose + oxigênio.","example":"Parte da glicose vira amido e fica guardada, como na batata e na mandioca.","variants":{"simples":"A planta faz duas coisas: açúcar para ela comer e oxigênio, que ela solta no ar para a gente respirar.","exemplo":"A batata que você come é a reserva de alimento que a planta guardou depois de fazer fotossíntese.","outra":"Entra: gás carbônico e água. Sai: açúcar (glicose) e oxigênio. A luz é a energia que faz essa troca acontecer.","detalhado":"A equação geral é 6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂, na presença de luz e clorofila. O oxigênio liberado vem da quebra das moléculas de água. Lembre que as plantas também respiram: usam oxigênio para quebrar a glicose e liberar energia, dia e noite."}},{"id":"b4","skill":"importancia","title":"Por que isso importa para todos","text":"A fotossíntese produz grande parte do oxigênio da atmosfera e é a base das cadeias alimentares: as plantas são produtoras e todos os outros seres dependem delas, direta ou indiretamente.","example":"O capim faz fotossíntese, o boi come o capim e nós comemos alimentos que vêm dessa cadeia.","variants":{"simples":"Sem as plantas, faltaria oxigênio para respirar e comida para os animais.","exemplo":"Uma lagarta come a folha, um passarinho come a lagarta. Tudo começou com a energia da luz que a folha guardou.","outra":"As plantas são o \"primeiro elo\" da corrente: elas transformam luz em alimento, e o resto da natureza vai passando essa energia adiante.","detalhado":"Por serem autótrofos, os seres fotossintetizantes são produtores. As algas marinhas (fitoplâncton) respondem por boa parte do oxigênio produzido no planeta. A fotossíntese também retira CO₂ da atmosfera, o que se relaciona com o controle do efeito estufa."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"A fotossíntese é o processo em que as plantas:","options":["Absorvem comida do solo","Produzem o próprio alimento usando luz","Dormem durante a noite","Liberam gás carbônico para crescer"],"answer":1,"hints":["\"Foto\" significa luz.","\"Síntese\" significa produção.","Produção com luz."],"explanation":"Na fotossíntese, a planta produz o próprio alimento (glicose) usando a energia da luz."},{"id":"q2","type":"tf","difficulty":1,"skill":"produtos","prompt":"A fotossíntese libera gás oxigênio.","answer":true,"hints":["Pense no que respiramos.","A planta produz açúcar e mais uma coisa.","Essa outra coisa vai para o ar."],"explanation":"Verdadeiro. O oxigênio é um dos produtos da fotossíntese."},{"id":"q3","type":"fill","difficulty":1,"skill":"ingredientes","prompt":"O pigmento verde que capta a luz se chama ________.","answers":["clorofila"],"hints":["É ele que deixa a folha verde.","Começa com \"cloro\".","Cloro + fila."],"explanation":"A clorofila é o pigmento verde que absorve a luz."},{"id":"q4","type":"mc","difficulty":2,"skill":"ingredientes","prompt":"Qual destes NÃO é usado pela planta para fazer fotossíntese?","options":["Luz","Água","Gás carbônico","Gás oxigênio"],"answer":3,"hints":["Separe o que entra do que sai.","Entra: luz, água e gás carbônico.","Um dos itens é um produto, não um ingrediente."],"explanation":"O oxigênio é produzido (sai), não é usado para fazer fotossíntese."},{"id":"q5","type":"mc","difficulty":2,"skill":"ingredientes","prompt":"Em que parte da planta a fotossíntese acontece principalmente?","options":["Raiz","Folhas","Flores","Sementes"],"answer":1,"hints":["Onde fica a maior parte da clorofila?","É a parte que mais recebe luz.","É verde e larga."],"explanation":"Nas folhas, onde há muitos cloroplastos com clorofila."},{"id":"q6","type":"mc","difficulty":2,"skill":"produtos","prompt":"Qual açúcar a planta produz na fotossíntese?","options":["Sacarose","Glicose","Lactose","Frutose"],"answer":1,"hints":["É o mesmo açúcar que nosso corpo usa como energia.","Começa com \"gli\".","Gli + cose."],"explanation":"A glicose é o açúcar produzido; parte dela pode ser guardada como amido."},{"id":"q7","type":"match","difficulty":2,"skill":"ingredientes","prompt":"Ligue cada ingrediente ao seu papel.","pairs":[["Água","Absorvida pelas raízes"],["Gás carbônico","Entra pelas folhas"],["Luz","Fornece a energia"],["Clorofila","Capta a luz"]],"hints":["Pense por onde cada um chega.","A raiz fica no solo, que é úmido.","A clorofila é o \"painel solar\"."],"explanation":"Água pela raiz, gás carbônico pelas folhas (estômatos), a luz dá energia e a clorofila a capta."},{"id":"q8","type":"tf","difficulty":2,"skill":"conceito","prompt":"As plantas fazem fotossíntese no escuro total.","answer":false,"hints":["Qual é a fonte de energia da fotossíntese?","Sem ela, o processo para.","No escuro não há luz."],"explanation":"Falso. Sem luz, a planta não capta energia e a fotossíntese não acontece."},{"id":"q9","type":"fill","difficulty":3,"skill":"ingredientes","prompt":"A organela onde ocorre a fotossíntese é o ________.","answers":["cloroplasto","cloroplastos"],"hints":["É onde a clorofila fica guardada.","Começa igual a clorofila.","Cloro + plasto."],"explanation":"O cloroplasto é a organela que contém a clorofila."},{"id":"q10","type":"mc","difficulty":3,"skill":"importancia","prompt":"Por que a fotossíntese é importante para os animais?","options":["Porque aquece o planeta","Porque produz oxigênio e é a base das cadeias alimentares","Porque produz água","Porque elimina todos os gases"],"answer":1,"hints":["Pense no que os animais respiram.","E no que os animais comem.","As plantas são produtoras."],"explanation":"Ela libera oxigênio e é o início das cadeias alimentares."},{"id":"q11","type":"tf","difficulty":3,"skill":"produtos","prompt":"As plantas também respiram, consumindo oxigênio.","answer":true,"hints":["Toda célula viva precisa liberar energia.","Isso acontece dia e noite.","É a respiração celular."],"explanation":"Verdadeiro. As plantas respiram o tempo todo; de dia, a fotossíntese costuma produzir mais oxigênio do que elas consomem."},{"id":"q12","type":"open","difficulty":3,"skill":"importancia","prompt":"O que aconteceria com os animais se todas as plantas parassem de fazer fotossíntese?","modelAnswer":"Faltaria alimento, porque as plantas são a base das cadeias alimentares, e o oxigênio do ar diminuiria com o tempo. Os animais não conseguiriam sobreviver.","keywords":["oxigenio","alimento","comida","cadeia","morrer","sobreviver"],"hints":["Pense em duas coisas que vêm das plantas.","Uma delas respiramos.","A outra está no começo da cadeia alimentar."],"explanation":"Os animais perderiam a fonte de alimento e, aos poucos, o oxigênio."}],"review":["Fotossíntese = produzir alimento com luz","Usa: água, gás carbônico e luz (clorofila capta)","Produz: glicose e oxigênio","Base das cadeias alimentares"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Terra e Universo","subtopic":"Sistema Solar","relatedQuestions":["Quantos planetas existem?","Qual é o maior planeta?","Por que existe dia e noite?","O Sol é uma estrela?"],"id":"cie-sistema-solar","subject":"ciencias","title":"Sistema Solar","levels":["fund1","fund2"],"grade":"3º ao 6º ano","aliases":["sistema solar","planetas","sol","rotacao","translacao","movimentos da terra","astronomia"],"summary":"Conheça o Sol, os oito planetas e os movimentos da Terra.","intro":"Vamos fazer uma viagem pelo espaço, começando pela nossa estrela: o Sol.","skills":{"sol":"O Sol","planetas":"Os planetas","tipos":"Planetas rochosos e gasosos","movimentos":"Movimentos da Terra"},"blocks":[{"id":"b1","skill":"sol","title":"O Sol, nossa estrela","text":"O Sol é uma estrela: uma enorme bola de gases muito quentes que produz luz e calor. Ele fica no centro do Sistema Solar, e tudo gira ao redor dele.","example":"As estrelas que vemos à noite também são sóis, só que estão muito mais longe.","variants":{"simples":"O Sol é uma estrela. Ele dá luz e calor para a Terra.","exemplo":"Sem o Sol não haveria dia, as plantas não cresceriam e a Terra seria gelada.","outra":"Imagine uma fogueira gigante no meio de uma roda. Os planetas ficam dando voltas ao redor dela. Essa fogueira é o Sol.","detalhado":"O Sol concentra mais de 99% da massa do Sistema Solar. Sua gravidade mantém os planetas em órbita. Plutão, que já foi chamado de planeta, hoje é classificado como planeta anão."}},{"id":"b2","skill":"planetas","title":"Os oito planetas","text":"Em ordem, a partir do Sol: Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano e Netuno. A Terra é o terceiro planeta, e Júpiter é o maior de todos.","example":"Uma frase para lembrar: \"Minha Vó Tem Muitas Joias, Só Usa No Natal\".","variants":{"simples":"São 8 planetas. O mais perto do Sol é Mercúrio. A Terra é o 3º. O maior é Júpiter.","exemplo":"Se o Sol fosse do tamanho de uma porta, a Terra seria do tamanho de uma moeda pequena, e Júpiter de uma bola de tênis.","outra":"Use as iniciais: M-V-T-M-J-S-U-N. Cada palavra da frase \"Minha Vó Tem Muitas Joias, Só Usa No Natal\" começa com a letra de um planeta.","detalhado":"Os planetas giram em órbitas quase circulares. Quanto mais longe do Sol, mais tempo leva para dar uma volta: Mercúrio leva cerca de 88 dias, a Terra cerca de 365, e Netuno cerca de 165 anos terrestres."}},{"id":"b3","skill":"tipos","title":"Rochosos e gasosos","text":"Os quatro primeiros (Mercúrio, Vênus, Terra e Marte) são rochosos: têm superfície sólida. Os quatro últimos (Júpiter, Saturno, Urano e Netuno) são gigantes gasosos, muito maiores e formados principalmente por gases.","example":"Um robô pode pousar em Marte. Em Júpiter, não haveria chão para pousar.","variants":{"simples":"Os 4 mais perto do Sol são de pedra. Os 4 mais longe são enormes e feitos de gás.","exemplo":"A Terra tem montanhas e chão. Saturno é uma bola gigante de gás com anéis ao redor.","outra":"Pense em dois times: o time pequeno e duro (rochosos) perto do Sol, e o time gigante e \"fofo\" (gasosos) lá longe.","detalhado":"Os gasosos são formados principalmente por hidrogênio e hélio; Urano e Netuno também são chamados de gigantes de gelo. Todos os gasosos possuem anéis, embora os de Saturno sejam os mais visíveis."}},{"id":"b4","skill":"movimentos","title":"Os movimentos da Terra","text":"A Terra gira em torno de si mesma (rotação), e isso leva cerca de 24 horas, formando o dia e a noite. Ela também dá uma volta ao redor do Sol (translação), que leva cerca de 365 dias: um ano.","example":"Quando é dia no Brasil, é noite no Japão, porque cada lado da Terra está virado para o Sol em momentos diferentes.","variants":{"simples":"Girando em volta de si mesma: dia e noite (24 horas). Girando em volta do Sol: um ano (365 dias).","exemplo":"Gire uma bola perto de uma lanterna: o lado iluminado é o dia, o lado escuro é a noite. Agora ande com a bola em volta da lanterna: isso é a translação.","outra":"Rotação = Roda em si mesma. Translação = Trajeto ao redor do Sol.","detalhado":"A translação leva cerca de 365 dias e 6 horas — por isso, a cada 4 anos, somamos um dia (ano bissexto). A inclinação do eixo da Terra, combinada com a translação, causa as estações do ano."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"sol","prompt":"O Sol é:","options":["Um planeta","Uma estrela","Um satélite","Um cometa"],"answer":1,"hints":["Ele produz luz própria.","Os planetas não produzem luz.","As que brilham à noite são do mesmo tipo."],"explanation":"O Sol é uma estrela: produz luz e calor."},{"id":"q2","type":"fill","difficulty":1,"skill":"planetas","prompt":"Quantos planetas existem no Sistema Solar? (número)","answers":["8","oito"],"hints":["Lembre da frase da vó.","Conte as palavras de \"Minha Vó Tem Muitas Joias, Só Usa No Natal\".","São menos que 10."],"explanation":"São 8 planetas."},{"id":"q3","type":"mc","difficulty":1,"skill":"planetas","prompt":"Qual planeta fica mais perto do Sol?","options":["Terra","Vênus","Mercúrio","Marte"],"answer":2,"hints":["É o primeiro da lista.","A frase começa com \"Minha\".","Começa com M e não é Marte."],"explanation":"Mercúrio é o primeiro planeta a partir do Sol."},{"id":"q4","type":"tf","difficulty":1,"skill":"movimentos","prompt":"O dia e a noite acontecem por causa da rotação da Terra.","answer":true,"hints":["Qual movimento leva 24 horas?","É a Terra girando em si mesma.","Rotação = roda em si mesma."],"explanation":"Verdadeiro. A rotação faz cada lado da Terra ficar virado para o Sol em momentos diferentes."},{"id":"q5","type":"mc","difficulty":2,"skill":"planetas","prompt":"Qual é o maior planeta do Sistema Solar?","options":["Saturno","Júpiter","Netuno","Terra"],"answer":1,"hints":["É um gigante gasoso.","É o quinto planeta.","Começa com J."],"explanation":"Júpiter é o maior planeta."},{"id":"q6","type":"match","difficulty":2,"skill":"movimentos","prompt":"Ligue cada item à sua descrição.","pairs":[["Rotação","Forma o dia e a noite"],["Translação","Volta ao redor do Sol"],["Lua","Satélite natural da Terra"],["Sol","Estrela no centro"]],"hints":["Rotação: roda em si mesma.","Translação: trajeto ao redor do Sol.","A Lua gira ao redor da Terra."],"explanation":"Rotação → dia e noite; Translação → ano; Lua → satélite; Sol → estrela."},{"id":"q7","type":"tf","difficulty":2,"skill":"tipos","prompt":"Júpiter é um planeta rochoso.","answer":false,"hints":["Onde Júpiter fica na lista?","Os 4 últimos são de um tipo.","Os últimos são gasosos."],"explanation":"Falso. Júpiter é um gigante gasoso."},{"id":"q8","type":"mc","difficulty":2,"skill":"tipos","prompt":"Quais são os planetas rochosos?","options":["Júpiter, Saturno, Urano e Netuno","Mercúrio, Vênus, Terra e Marte","Terra, Marte, Júpiter e Saturno","Só a Terra"],"answer":1,"hints":["São os mais próximos do Sol.","São os 4 primeiros.","A Terra está entre eles."],"explanation":"Os rochosos são os quatro primeiros: Mercúrio, Vênus, Terra e Marte."},{"id":"q9","type":"fill","difficulty":2,"skill":"movimentos","prompt":"A translação da Terra dura cerca de ____ dias.","answers":["365","365 dias"],"hints":["É o tempo de um ano.","Um ano tem mais de 300 dias.","3-6-5."],"explanation":"Cerca de 365 dias — um ano."},{"id":"q10","type":"mc","difficulty":3,"skill":"planetas","prompt":"Qual é a posição da Terra a partir do Sol?","options":["Primeira","Segunda","Terceira","Quarta"],"answer":2,"hints":["Mercúrio é o 1º.","Vênus é o 2º.","Quem vem depois de Vênus?"],"explanation":"A Terra é o terceiro planeta."},{"id":"q11","type":"tf","difficulty":3,"skill":"sol","prompt":"Plutão é considerado um planeta anão.","answer":true,"hints":["Plutão já foi chamado de planeta.","Em 2006 a classificação mudou.","Hoje é de uma categoria menor."],"explanation":"Verdadeiro. Desde 2006, Plutão é classificado como planeta anão."},{"id":"q12","type":"mc","difficulty":3,"skill":"movimentos","prompt":"Quanto tempo dura, aproximadamente, a rotação da Terra?","options":["12 horas","24 horas","7 dias","365 dias"],"answer":1,"hints":["A rotação forma o dia e a noite.","Um dia completo inclui a noite.","Quantas horas tem um dia?"],"explanation":"Cerca de 24 horas: um dia completo."}],"review":["O Sol é uma estrela","8 planetas: Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano, Netuno","Rochosos (4 primeiros) × gasosos (4 últimos)","Rotação = dia/noite (24 h) · Translação = ano (365 dias)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Água","subtopic":"Ciclo hidrológico","relatedQuestions":["Como a chuva se forma?","Como as nuvens se formam?","Para onde vai a água da chuva?","O que é evaporação?"],"id":"cie-ciclo-da-agua","subject":"ciencias","title":"Ciclo da água","levels":["fund1","fund2"],"grade":"3º ao 6º ano","aliases":["ciclo da agua","ciclo hidrologico","evaporacao","condensacao","precipitacao","chuva","estados fisicos da agua","como a chuva se forma"],"summary":"Veja como a água viaja entre o mar, o céu e a terra: evaporação, condensação, precipitação e infiltração.","intro":"A água da chuva de hoje pode ter estado no oceano semana passada. Vamos acompanhar essa viagem!","skills":{"evaporacao":"Evaporação e transpiração","condensacao":"Condensação e nuvens","precipitacao":"Precipitação","retorno":"Infiltração e escoamento"},"blocks":[{"id":"b1","skill":"evaporacao","title":"A água sobe: evaporação","text":"O calor do Sol aquece a água de mares, rios e lagos, e ela passa do estado líquido para o gasoso (vapor), subindo para a atmosfera. As plantas também liberam vapor pelas folhas: é a transpiração.","example":"Uma roupa molhada seca no varal porque a água evapora.","variants":{"simples":"O Sol esquenta a água, e ela vira vapor, que sobe para o céu. Invisível!"}},{"id":"b2","skill":"condensacao","title":"As nuvens se formam: condensação","text":"Lá em cima o ar é mais frio. O vapor esfria e volta a virar gotinhas de água líquida, que se juntam e formam as nuvens.","example":"Um copo com água gelada fica \"suado\" por fora: o vapor do ar condensa no vidro frio.","variants":{"simples":"No alto é frio. O vapor vira gotinhas, e muitas gotinhas juntas formam as nuvens."}},{"id":"b3","skill":"precipitacao","title":"A água cai: precipitação","text":"Quando as gotinhas das nuvens ficam grandes e pesadas, caem como chuva. Em lugares muito frios, podem cair como neve ou granizo.","example":"Nuvens escuras e carregadas costumam anunciar chuva forte.","variants":{"simples":"Quando as gotas ficam pesadas, caem: é a chuva."}},{"id":"b4","skill":"retorno","title":"A água volta: infiltração e escoamento","text":"Parte da chuva infiltra no solo e forma a água subterrânea (lençol freático). Outra parte escorre pela superfície até rios, lagos e mares. E o ciclo recomeça.","example":"Em cidades com muito asfalto, a água não infiltra e escorre pelas ruas, causando enchentes.","variants":{"simples":"A chuva entra na terra ou escorre até os rios e o mar. Depois tudo começa de novo."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"evaporacao","prompt":"O que faz a água dos rios e mares evaporar?","options":["O frio","O calor do Sol","O vento sozinho","A Lua"],"answer":1,"hints":["A evaporação precisa de energia.","Essa energia vem do céu de dia.","Ela esquenta a água."],"explanation":"O calor do Sol transforma a água líquida em vapor."},{"id":"q2","type":"mc","difficulty":1,"skill":"condensacao","prompt":"Como as nuvens se formam?","options":["O vapor esfria e vira gotinhas","A fumaça das fábricas","A água do mar voa","O Sol cria nuvens"],"answer":0,"hints":["Lá em cima é mais frio.","O que acontece com o vapor no frio?","Ele vira líquido de novo."],"explanation":"O vapor condensa em gotinhas que formam as nuvens."},{"id":"q3","type":"tf","difficulty":1,"skill":"precipitacao","prompt":"A chuva é um tipo de precipitação.","answer":true,"hints":["Precipitação = água caindo do céu.","A chuva cai do céu?","Sim."],"explanation":"Verdadeiro. Neve e granizo também são precipitação."},{"id":"q4","type":"fill","difficulty":2,"skill":"condensacao","prompt":"A passagem do vapor para gotinhas de água se chama ________.","answers":["condensacao","condensação"],"hints":["Acontece quando o vapor esfria.","Forma as nuvens.","Conden…"],"explanation":"Condensação."},{"id":"q5","type":"match","difficulty":2,"skill":"retorno","prompt":"Ligue cada etapa ao que acontece.","pairs":[["Evaporação","Água vira vapor e sobe"],["Condensação","Vapor forma nuvens"],["Precipitação","Água cai como chuva"],["Infiltração","Água entra no solo"]],"hints":["Sobe, forma nuvem, cai, entra na terra.","Precipitação = cair.","Infiltrar = entrar."],"explanation":"Evaporação → condensação → precipitação → infiltração."},{"id":"q6","type":"tf","difficulty":2,"skill":"evaporacao","prompt":"As plantas também liberam vapor de água para a atmosfera.","answer":true,"hints":["Pense nas folhas.","Esse processo se chama transpiração.","Ele faz parte do ciclo."],"explanation":"Verdadeiro: é a transpiração das plantas."},{"id":"q7","type":"mc","difficulty":2,"skill":"condensacao","prompt":"Por que um copo com água gelada fica molhado por fora?","options":["A água atravessa o vidro","O vapor do ar condensa no vidro frio","O copo derrete","A água evapora de dentro"],"answer":1,"hints":["O vidro está frio.","O ar tem vapor invisível.","Vapor + frio = ?"],"explanation":"O vapor do ar esfria no vidro e condensa."},{"id":"q8","type":"mc","difficulty":3,"skill":"retorno","prompt":"Por que cidades com muito asfalto têm mais enchentes?","options":["Porque chove mais nas cidades","Porque a água não consegue infiltrar no solo","Porque o asfalto produz água","Porque não há evaporação"],"answer":1,"hints":["Asfalto deixa a água entrar na terra?","Não deixa.","Então ela escorre."],"explanation":"Sem infiltração, a água escorre toda pela superfície."},{"id":"q9","type":"fill","difficulty":3,"skill":"retorno","prompt":"A água que infiltra e fica guardada no subsolo forma o lençol ________.","answers":["freatico","freático"],"hints":["Fica embaixo da terra.","De onde vêm os poços.","Lençol frea…"],"explanation":"Lençol freático."},{"id":"q10","type":"open","difficulty":3,"skill":"precipitacao","prompt":"Explique com suas palavras como a água do mar pode virar chuva em outro lugar.","modelAnswer":"O Sol aquece o mar e a água evapora. O vapor sobe, esfria e condensa formando nuvens. O vento leva as nuvens, e quando as gotas ficam pesadas elas caem como chuva em outro lugar.","keywords":["evapora","vapor","nuvem","condensa","chuva","sol","vento"],"hints":["Comece pelo Sol.","Depois fale das nuvens.","Termine com a chuva caindo."],"explanation":"Evaporação → condensação → transporte pelo vento → precipitação."}],"review":["Evaporação: o Sol transforma água em vapor","Condensação: vapor esfria e forma nuvens","Precipitação: chuva, neve, granizo","Infiltração e escoamento devolvem a água"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Corpo humano","subtopic":"Sistema digestório","relatedQuestions":["Como funciona a digestão?","Para onde vai a comida que comemos?","O que faz o estômago?","Para que serve o intestino?"],"id":"cie-sistema-digestorio","subject":"ciencias","title":"Sistema digestório","levels":["fund2","medio"],"grade":"8º ano","aliases":["sistema digestorio","digestao","aparelho digestivo","estomago","intestino","corpo humano","como digerimos os alimentos"],"summary":"Acompanhe o caminho dos alimentos: da boca ao intestino, e o papel de cada órgão.","intro":"Um lanche leva horas viajando pelo seu corpo. Vamos seguir esse caminho!","skills":{"conceito":"O que é digestão","boca_estomago":"Boca, esôfago e estômago","intestinos":"Intestino delgado e grosso","anexos":"Fígado e pâncreas"},"blocks":[{"id":"b1","skill":"conceito","title":"Para que serve a digestão","text":"Digestão é a transformação dos alimentos em partes muito pequenas (nutrientes) que o corpo consegue absorver e usar para ter energia, crescer e se recuperar.","example":"O pão tem amido, que é quebrado até virar glicose, uma fonte de energia."},{"id":"b2","skill":"boca_estomago","title":"Da boca ao estômago","text":"Na boca, os dentes trituram o alimento e a saliva começa a digerir o amido. O alimento passa pela faringe e pelo esôfago até o estômago, onde o suco gástrico, muito ácido, digere as proteínas.","example":"Mastigar bem facilita todo o resto da digestão."},{"id":"b3","skill":"intestinos","title":"Os intestinos","text":"No intestino delgado a digestão termina e os nutrientes são absorvidos para o sangue. No intestino grosso, grande parte da água é absorvida e se formam as fezes, eliminadas pelo ânus.","example":"O intestino delgado de um adulto tem vários metros de comprimento, dobrado dentro da barriga."},{"id":"b4","skill":"anexos","title":"Os órgãos anexos","text":"O fígado produz a bile, que ajuda a digerir as gorduras (ela fica guardada na vesícula biliar). O pâncreas produz o suco pancreático, com enzimas que atuam no intestino delgado.","example":"Uma refeição muito gordurosa exige mais bile para ser digerida."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"boca_estomago","prompt":"Onde começa a digestão?","options":["No estômago","Na boca","No intestino","No fígado"],"answer":1,"hints":["É onde o alimento entra.","Lá há dentes e saliva.","É na…"],"explanation":"A digestão começa na boca, com a mastigação e a saliva."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceito","prompt":"A digestão transforma os alimentos em nutrientes que o corpo pode absorver.","answer":true,"hints":["Para que serve a digestão?","O corpo precisa de partes pequenas.","Essas partes são os nutrientes."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"boca_estomago","prompt":"Qual órgão liga a boca (faringe) ao estômago?","options":["Intestino","Esôfago","Pâncreas","Traqueia"],"answer":1,"hints":["É um tubo.","Fica atrás da traqueia.","Começa com E."],"explanation":"O esôfago leva o alimento ao estômago."},{"id":"q4","type":"fill","difficulty":2,"skill":"intestinos","prompt":"A maior parte dos nutrientes é absorvida no intestino ________.","answers":["delgado"],"hints":["São dois intestinos.","Não é o grosso.","É o mais fino e comprido."],"explanation":"No intestino delgado."},{"id":"q5","type":"match","difficulty":2,"skill":"anexos","prompt":"Ligue cada órgão à sua função.","pairs":[["Estômago","Digere proteínas com suco ácido"],["Fígado","Produz a bile"],["Intestino grosso","Absorve água e forma as fezes"],["Pâncreas","Produz o suco pancreático"]],"hints":["A bile vem de um órgão grande do lado direito.","O intestino grosso cuida da água.","O suco ácido fica no estômago."],"explanation":"Estômago → proteínas · fígado → bile · intestino grosso → água · pâncreas → suco pancreático."},{"id":"q6","type":"mc","difficulty":2,"skill":"anexos","prompt":"A bile ajuda a digerir principalmente:","options":["Gorduras","Água","Vitaminas","Sais minerais"],"answer":0,"hints":["Pense em frituras.","A bile \"quebra\" gotas grandes.","Gotas de gordura."],"explanation":"A bile emulsiona as gorduras."},{"id":"q7","type":"tf","difficulty":2,"skill":"intestinos","prompt":"O intestino grosso absorve grande parte da água.","answer":true,"hints":["O que sobra depois do delgado?","Resto de alimento com muita água.","O grosso recupera essa água."],"explanation":"Verdadeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"boca_estomago","prompt":"Qual é a sequência correta do caminho do alimento?","options":["Boca → estômago → esôfago → intestinos","Boca → faringe → esôfago → estômago → intestino delgado → intestino grosso","Boca → intestino → estômago → esôfago","Esôfago → boca → estômago → intestinos"],"answer":1,"hints":["Começa na boca.","O esôfago vem antes do estômago.","O delgado vem antes do grosso."],"explanation":"Boca → faringe → esôfago → estômago → delgado → grosso."},{"id":"q9","type":"fill","difficulty":3,"skill":"anexos","prompt":"A bile fica armazenada na vesícula ________.","answers":["biliar"],"hints":["Vem da palavra bile.","Bil…","Termina em -ar."],"explanation":"Vesícula biliar."},{"id":"q10","type":"open","difficulty":3,"skill":"conceito","prompt":"Por que é importante mastigar bem os alimentos?","modelAnswer":"Porque a mastigação quebra o alimento em pedaços menores e mistura com a saliva, que já começa a digestão. Isso facilita o trabalho do estômago e dos intestinos.","keywords":["pedacos","menores","saliva","facilita","digestao","estomago","triturar"],"hints":["O que os dentes fazem?","O que a saliva faz?","Como isso ajuda os outros órgãos?"],"explanation":"Mastigar tritura o alimento e facilita a digestão."}],"review":["Digestão = transformar alimento em nutrientes","Boca → faringe → esôfago → estômago → intestinos","Delgado absorve nutrientes · grosso absorve água","Fígado (bile) e pâncreas (suco pancreático)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Idade Contemporânea","subtopic":"Revolução Francesa","relatedQuestions":["O que foi a Revolução Francesa?","O que foi a Queda da Bastilha?","O que foi o período do Terror?"],"id":"his-revolucao-francesa","subject":"historia","title":"Revolução Francesa","levels":["fund2","medio"],"grade":"8º ano e 2ª série","aliases":["revolucao francesa","queda da bastilha","bastilha","robespierre","periodo do terror","jacobinos","girondinos","luis xvi","liberdade igualdade fraternidade","1789"],"summary":"Entenda por que a França entrou em revolução em 1789, suas fases e o que ela deixou para o mundo.","intro":"Em 1789, o povo francês derrubou um sistema que existia havia séculos. Vamos entender como isso aconteceu.","skills":{"contexto":"A França antes da revolução","inicio":"O início (1789)","ideias":"Ideias e direitos","fases":"Fases da revolução","legado":"Legado"},"blocks":[{"id":"b1","skill":"contexto","title":"A França antes de 1789","text":"A França era uma monarquia absolutista: o rei Luís XVI concentrava o poder. A sociedade era dividida em três estados: o clero (1º), a nobreza (2º) e o Terceiro Estado (burguesia, camponeses e trabalhadores urbanos). O Terceiro Estado era a imensa maioria e pagava quase todos os impostos.","example":"Um camponês pagava impostos ao rei, à Igreja e ao senhor da terra, enquanto muitos nobres e membros do clero tinham isenções.","variants":{"simples":"Na França havia três grupos: padres, nobres e o povo. O povo era quem mais trabalhava e quem pagava os impostos. O rei mandava em tudo.","exemplo":"Imagine uma escola em que só uma turma paga a cantina de todas as outras e ainda não pode opinar em nada. Era assim que o Terceiro Estado se sentia.","outra":"Três ingredientes explodiram juntos: um país endividado (guerras e gastos da corte), fome (colheitas ruins e pão caro) e ideias novas do Iluminismo, que diziam que o poder não vinha de Deus, e sim do povo.","detalhado":"Esse modelo é chamado de Antigo Regime. O Iluminismo, com pensadores como Rousseau, Montesquieu e Voltaire, criticava o absolutismo, os privilégios e defendia razão, liberdade e separação dos poderes. A burguesia, rica mas sem privilégios políticos, liderou a contestação."}},{"id":"b2","skill":"inicio","title":"O início: 1789","text":"Para resolver a crise, o rei convocou os Estados Gerais em 1789. O Terceiro Estado se declarou Assembleia Nacional e jurou criar uma Constituição. Em 14 de julho de 1789, o povo de Paris tomou a Bastilha, prisão que simbolizava o poder do rei.","example":"O 14 de julho é até hoje o feriado nacional da França.","variants":{"simples":"Em 1789 o povo se revoltou. No dia 14 de julho, invadiu uma prisão chamada Bastilha. Esse é o símbolo do começo da revolução.","exemplo":"Nos Estados Gerais cada estado tinha um voto. Clero e nobreza sempre se uniam e ganhavam por 2 a 1 do Terceiro Estado, mesmo ele representando quase toda a população.","outra":"Pense em três passos: o rei chama uma reunião (Estados Gerais) → o povo cria a própria assembleia → Paris toma a Bastilha. A partir daí, não tinha mais volta.","detalhado":"O impasse era o voto por estado × voto por cabeça. Com o Juramento da Sala do Jogo da Pela, os deputados do Terceiro Estado prometeram não se separar até dar uma Constituição à França. A tomada da Bastilha foi seguida por revoltas camponesas no campo (o \"Grande Medo\")."}},{"id":"b3","skill":"ideias","title":"Liberdade, Igualdade, Fraternidade","text":"Em agosto de 1789 foi aprovada a Declaração dos Direitos do Homem e do Cidadão, afirmando que todos nascem livres e iguais em direitos. O lema da revolução ficou famoso: Liberdade, Igualdade, Fraternidade.","example":"A ideia de que a lei vale igualmente para todos, sem privilégios de nascimento, vem desse período.","variants":{"simples":"Os revolucionários escreveram um documento dizendo que todas as pessoas têm direitos. O lema era: Liberdade, Igualdade, Fraternidade.","exemplo":"Antes, um nobre podia ser julgado de forma diferente de um camponês. A Declaração dizia que a lei deve ser a mesma para todos.","outra":"Liberdade = poder pensar e agir sem opressão. Igualdade = mesmas leis para todos. Fraternidade = união entre os cidadãos.","detalhado":"A Declaração garantia direitos como liberdade, propriedade, segurança e resistência à opressão, e afirmava a soberania da nação. Ela tinha limites: não incluía as mulheres na mesma condição — Olympe de Gouges escreveu em resposta a Declaração dos Direitos da Mulher e da Cidadã (1791)."}},{"id":"b4","skill":"fases","title":"As fases da revolução","text":"1) Monarquia constitucional (1789–1792): o rei continua, mas limitado por uma Constituição. 2) Convenção e República (1792–1795): o rei Luís XVI é executado em 1793; os jacobinos, liderados por Robespierre, promovem o período do Terror. 3) Diretório (1795–1799): governo da alta burguesia, que termina com o golpe de Napoleão Bonaparte, o 18 de Brumário, em 1799.","example":"No Terror, milhares de pessoas acusadas de serem inimigas da revolução foram executadas na guilhotina.","variants":{"simples":"Primeiro o rei perdeu poder. Depois foi morto e a França virou república, com uma fase violenta chamada Terror. No fim, Napoleão tomou o poder em 1799.","exemplo":"É como uma história em três capítulos: \"o rei com regras\", \"a república radical\" e \"a burguesia no comando\", terminando com Napoleão.","outra":"Grupos disputavam o rumo: os girondinos (alta burguesia, mais moderados) e os jacobinos (pequena burguesia, mais radicais, apoiados pelos sans-culottes). Cada fase mostra quem estava vencendo essa disputa.","detalhado":"Os jacobinos criaram o Comitê de Salvação Pública e tomaram medidas como a Lei do Máximo (teto de preços). Com a queda de Robespierre (1794), a reação termidoriana abriu caminho para o Diretório. A instabilidade e as guerras externas favoreceram o golpe do 18 de Brumário."}},{"id":"b5","skill":"legado","title":"O que ela deixou","text":"A Revolução Francesa pôs fim ao Antigo Regime na França, espalhou ideias de cidadania e direitos, e inspirou movimentos em vários países, inclusive na América. Por isso, ela é usada como marco do início da Idade Contemporânea.","example":"Conceitos que usamos hoje, como \"direitos do cidadão\" e \"direita e esquerda\" na política, ganharam força nessa época.","variants":{"simples":"Ela mudou o mundo porque espalhou a ideia de que as pessoas têm direitos e que o poder vem do povo.","exemplo":"Os termos \"direita\" e \"esquerda\" vêm da posição em que os grupos se sentavam na Assembleia francesa.","outra":"Antes: poder do rei e privilégios de nascimento. Depois: cidadãos com direitos e leis iguais. Essa virada é o legado.","detalhado":"A revolução consolidou a ascensão política da burguesia, influenciou constituições liberais e movimentos de independência, e fez circular o conceito moderno de nação. A historiografia usa 1789 como marco da Idade Contemporânea."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"inicio","prompt":"Em que ano começou a Revolução Francesa?","options":["1500","1789","1822","1917"],"answer":1,"hints":["É no século XVIII.","Mesmo ano da Queda da Bastilha.","Termina em 89."],"explanation":"A Revolução Francesa começou em 1789."},{"id":"q2","type":"mc","difficulty":1,"skill":"ideias","prompt":"Qual era o lema da Revolução Francesa?","options":["Ordem e Progresso","Liberdade, Igualdade, Fraternidade","Terra e Liberdade","Paz, Pão e Terra"],"answer":1,"hints":["São três palavras.","Uma delas é \"Liberdade\".","Outra é \"Igualdade\"."],"explanation":"Liberdade, Igualdade, Fraternidade."},{"id":"q3","type":"tf","difficulty":1,"skill":"inicio","prompt":"A Queda da Bastilha, em 14 de julho de 1789, é símbolo do início da revolução.","answer":true,"hints":["A Bastilha era uma prisão.","Ela representava o poder do rei.","Hoje o 14 de julho é feriado na França."],"explanation":"Verdadeiro. A tomada da Bastilha simboliza o início da revolução."},{"id":"q4","type":"match","difficulty":2,"skill":"contexto","prompt":"Ligue cada estado ao grupo que o formava.","pairs":[["Primeiro Estado","Clero"],["Segundo Estado","Nobreza"],["Terceiro Estado","Burguesia e povo"]],"hints":["A Igreja vinha primeiro.","Depois vinham os nobres.","O resto da população era o Terceiro."],"explanation":"1º: clero · 2º: nobreza · 3º: burguesia, camponeses e trabalhadores."},{"id":"q5","type":"fill","difficulty":2,"skill":"contexto","prompt":"O movimento de ideias que defendia a razão e criticava o absolutismo se chama ________.","answers":["iluminismo"],"hints":["Tem a ver com \"luz\".","A \"luz\" era a razão.","Ilumin…"],"explanation":"O Iluminismo."},{"id":"q6","type":"tf","difficulty":2,"skill":"contexto","prompt":"O clero e a nobreza pagavam a maior parte dos impostos.","answer":false,"hints":["Quem tinha privilégios?","Clero e nobreza tinham muitas isenções.","O peso caía sobre a maioria."],"explanation":"Falso. Quem pagava quase todos os impostos era o Terceiro Estado."},{"id":"q7","type":"mc","difficulty":2,"skill":"ideias","prompt":"Qual documento de 1789 afirmava que todos nascem livres e iguais em direitos?","options":["Constituição dos EUA","Declaração dos Direitos do Homem e do Cidadão","Carta Magna","Lei Áurea"],"answer":1,"hints":["Foi aprovado na França.","Fala em \"direitos\" e em \"cidadão\".","Foi em agosto de 1789."],"explanation":"A Declaração dos Direitos do Homem e do Cidadão."},{"id":"q8","type":"mc","difficulty":2,"skill":"contexto","prompt":"Quem fazia parte do Terceiro Estado?","options":["Apenas o rei e a rainha","Bispos e padres","Burguesia, camponeses e trabalhadores urbanos","Somente nobres"],"answer":2,"hints":["Era a maioria da população.","Não tinha privilégios.","Incluía ricos comerciantes e pobres."],"explanation":"Burguesia, camponeses e trabalhadores urbanos (sans-culottes)."},{"id":"q9","type":"mc","difficulty":3,"skill":"fases","prompt":"Como ficou conhecido o período de execuções liderado por Robespierre?","options":["Diretório","Terror","Consulado","Restauração"],"answer":1,"hints":["Foi uma fase muito violenta.","Usava muito a guilhotina.","O nome lembra medo."],"explanation":"O período do Terror (1793–1794), sob os jacobinos."},{"id":"q10","type":"fill","difficulty":3,"skill":"fases","prompt":"O rei francês guilhotinado em 1793 foi Luís ____. (algarismo romano)","answers":["xvi","16"],"hints":["Ele era o rei em 1789.","É um número entre 15 e 17.","Em romanos: X + V + I."],"explanation":"Luís XVI foi executado em 1793."},{"id":"q11","type":"mc","difficulty":3,"skill":"fases","prompt":"Como a Revolução Francesa terminou, em 1799?","options":["Com a volta do absolutismo","Com o golpe do 18 de Brumário, de Napoleão","Com a independência dos EUA","Com a Primeira Guerra Mundial"],"answer":1,"hints":["Um general tomou o poder.","Ele depois virou imperador.","O golpe tem nome de mês do calendário revolucionário."],"explanation":"Napoleão Bonaparte deu o golpe do 18 de Brumário e encerrou o Diretório."},{"id":"q12","type":"open","difficulty":3,"skill":"legado","prompt":"Por que a Revolução Francesa é considerada o marco do início da Idade Contemporânea?","modelAnswer":"Porque acabou com o Antigo Regime e o absolutismo na França, espalhou ideias de direitos, cidadania, liberdade e igualdade, e influenciou governos e movimentos no mundo todo.","keywords":["absolutismo","antigo regime","direitos","cidadao","cidadania","igualdade","liberdade","burguesia"],"hints":["O que ela derrubou?","Que ideias ela espalhou?","Fale de direitos ou do fim do poder absoluto do rei."],"explanation":"Ela encerrou o Antigo Regime e difundiu direitos e cidadania pelo mundo."}],"review":["Antigo Regime: rei absoluto + 3 estados","Terceiro Estado pagava os impostos","1789: Estados Gerais, Assembleia, Bastilha (14/07)","Declaração dos Direitos do Homem e do Cidadão","Fases: monarquia constitucional → República/Terror → Diretório → Napoleão (1799)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"História do Brasil","subtopic":"Período colonial","relatedQuestions":["Como foi a chegada dos portugueses ao Brasil?","O que foram as capitanias hereditárias?","Quem foi Tomé de Sousa?","Como era a economia do açúcar?"],"id":"his-brasil-colonia","subject":"historia","title":"Brasil Colônia","levels":["fund2","medio"],"grade":"7º ano","aliases":["brasil colonia","periodo colonial","descobrimento do brasil","chegada dos portugueses","capitanias hereditarias","governo geral","pau brasil","ciclo do acucar","engenho"],"summary":"Da chegada dos portugueses em 1500 às capitanias, ao governo-geral e à economia do açúcar.","intro":"Em 1500, navios portugueses chegaram a uma terra que já era habitada por milhões de indígenas. Começava o período colonial.","skills":{"chegada":"A chegada dos portugueses","capitanias":"Capitanias hereditárias","governo":"Governo-geral","economia":"Economia colonial e escravidão"},"blocks":[{"id":"b1","skill":"chegada","title":"A chegada em 1500","text":"Em abril de 1500, a esquadra de Pedro Álvares Cabral chegou ao litoral da atual Bahia. A terra já era habitada por muitos povos indígenas. Nos primeiros anos, Portugal explorou principalmente o pau-brasil, árvore usada para tingir tecidos.","example":"O nome \"Brasil\" vem do pau-brasil, cuja madeira tem cor de brasa."},{"id":"b2","skill":"capitanias","title":"As capitanias hereditárias (1534)","text":"Para ocupar e defender a terra, o rei Dom João III dividiu o território em faixas chamadas capitanias hereditárias, entregues a donatários que deviam povoá-las e explorá-las por conta própria. Passavam de pai para filho.","example":"Pernambuco e São Vicente prosperaram; a maioria das outras fracassou por falta de recursos e conflitos."},{"id":"b3","skill":"governo","title":"O governo-geral (1549)","text":"Como as capitanias não deram certo em geral, Portugal criou o governo-geral para centralizar a administração. O primeiro governador, Tomé de Sousa, chegou em 1549 e fundou Salvador, primeira capital do Brasil.","example":"Com Tomé de Sousa vieram os primeiros jesuítas, liderados por Manuel da Nóbrega."},{"id":"b4","skill":"economia","title":"Açúcar e escravidão","text":"A principal atividade econômica foi a produção de açúcar nos engenhos do Nordeste, feita com o trabalho de africanos escravizados trazidos à força. Indígenas também foram escravizados. A escravidão marcou profundamente a sociedade brasileira.","example":"O engenho reunia a casa-grande, a senzala, a moenda e os canaviais."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"chegada","prompt":"Em que ano a esquadra de Cabral chegou ao Brasil?","options":["1492","1500","1822","1534"],"answer":1,"hints":["É o começo do século XVI.","Um número \"redondo\".","Mil e quinhentos."],"explanation":"Em 1500."},{"id":"q2","type":"tf","difficulty":1,"skill":"chegada","prompt":"Quando os portugueses chegaram, a terra já era habitada por povos indígenas.","answer":true,"hints":["Estava vazia?","Havia milhões de pessoas.","Os povos originários."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"chegada","prompt":"O primeiro produto explorado pelos portugueses foi:","options":["Ouro","Café","Pau-brasil","Borracha"],"answer":2,"hints":["Deu nome ao país.","É uma árvore.","Pau-…"],"explanation":"O pau-brasil."},{"id":"q4","type":"fill","difficulty":2,"skill":"capitanias","prompt":"As capitanias hereditárias foram criadas em ____.","answers":["1534"],"hints":["Foi na década de 1530.","Antes do governo-geral (1549).","15-3-4."],"explanation":"Em 1534."},{"id":"q5","type":"mc","difficulty":2,"skill":"governo","prompt":"Quem foi o primeiro governador-geral do Brasil?","options":["Pedro Álvares Cabral","Tomé de Sousa","Dom Pedro I","Martim Afonso"],"answer":1,"hints":["Chegou em 1549.","Fundou Salvador.","Tomé…"],"explanation":"Tomé de Sousa."},{"id":"q6","type":"match","difficulty":2,"skill":"governo","prompt":"Ligue cada fato ao ano.","pairs":[["Chegada de Cabral","1500"],["Capitanias hereditárias","1534"],["Chegada de Tomé de Sousa e fundação de Salvador","1549"]],"hints":["A chegada é a mais antiga.","As capitanias vieram antes do governo-geral.","Salvador foi fundada no fim da década de 1540."],"explanation":"1500 → 1534 → 1549."},{"id":"q7","type":"tf","difficulty":2,"skill":"capitanias","prompt":"A maioria das capitanias hereditárias prosperou.","answer":false,"hints":["Por que Portugal criou o governo-geral?","Porque o sistema não funcionou bem.","Poucas deram certo."],"explanation":"Falso. Só algumas, como Pernambuco e São Vicente, prosperaram."},{"id":"q8","type":"mc","difficulty":3,"skill":"economia","prompt":"Qual foi a principal base de trabalho nos engenhos de açúcar?","options":["Trabalhadores assalariados europeus","Africanos escravizados","Máquinas a vapor","Colonos voluntários"],"answer":1,"hints":["Pessoas trazidas à força.","Vinham de outro continente.","Da África."],"explanation":"O trabalho de africanos escravizados."},{"id":"q9","type":"fill","difficulty":3,"skill":"governo","prompt":"A primeira capital do Brasil foi a cidade de ________.","answers":["salvador"],"hints":["Fica na Bahia.","Foi fundada por Tomé de Sousa.","Salva…"],"explanation":"Salvador."},{"id":"q10","type":"open","difficulty":3,"skill":"capitanias","prompt":"Por que Portugal criou o governo-geral depois das capitanias?","modelAnswer":"Porque a maioria das capitanias fracassou por falta de recursos, isolamento e conflitos com indígenas. O governo-geral centralizou a administração para defender e organizar melhor a colônia.","keywords":["fracass","centraliz","organizar","defender","recursos","administracao"],"hints":["As capitanias funcionaram?","O que faltava a elas?","O governo-geral juntou o poder num só lugar."],"explanation":"Para centralizar a administração após o fracasso da maioria das capitanias."}],"review":["1500: chegada de Cabral; terra já habitada","Pau-brasil: primeira exploração","1534: capitanias hereditárias","1549: governo-geral, Tomé de Sousa, Salvador","Açúcar + trabalho escravizado"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — Capitanias Hereditárias","url":"https://www.todamateria.com.br/capitanias-hereditarias/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"História do Brasil","subtopic":"Independência","relatedQuestions":["Como foi a Independência do Brasil?","O que foi o Dia do Fico?","O que aconteceu em 7 de setembro?","Quem proclamou a independência?"],"id":"his-independencia-brasil","subject":"historia","title":"Independência do Brasil","levels":["fund1","fund2","medio"],"grade":"8º ano","aliases":["independencia do brasil","7 de setembro","grito do ipiranga","dom pedro i","dia do fico","1822","primeiro reinado"],"summary":"Os caminhos até 1822, o 7 de setembro e o reconhecimento da independência.","intro":"O 7 de setembro é feriado nacional. Mas a independência foi um processo — não aconteceu num dia só.","skills":{"contexto":"Antecedentes","dia_do_fico":"Dia do Fico","proclamacao":"7 de setembro de 1822","reconhecimento":"Guerras e reconhecimento"},"blocks":[{"id":"b1","skill":"contexto","title":"A família real no Brasil","text":"Em 1808, fugindo das tropas de Napoleão, a família real portuguesa veio para o Rio de Janeiro. O Brasil ganhou importância: portos abertos, novas instituições e, em 1815, virou Reino Unido a Portugal e Algarves.","example":"Nessa época surgiram o Banco do Brasil e o Jardim Botânico do Rio."},{"id":"b2","skill":"dia_do_fico","title":"O Dia do Fico (1822)","text":"Dom João VI voltou a Portugal em 1821 e deixou seu filho, Dom Pedro, como príncipe regente. As cortes portuguesas exigiram que ele também voltasse. Em 9 de janeiro de 1822, ele decidiu ficar: foi o Dia do Fico.","example":"A frase atribuída a ele: \"Diga ao povo que fico\"."},{"id":"b3","skill":"proclamacao","title":"O 7 de setembro","text":"Em 7 de setembro de 1822, às margens do riacho Ipiranga, em São Paulo, Dom Pedro proclamou a independência. Em dezembro, foi coroado Dom Pedro I, primeiro imperador do Brasil. O país virou uma monarquia.","example":"O episódio ficou conhecido como \"Grito do Ipiranga\"."},{"id":"b4","skill":"reconhecimento","title":"Guerras e reconhecimento","text":"Tropas portuguesas resistiram em províncias como Bahia, Maranhão e Pará, e houve guerras de independência. A Bahia só se libertou em 2 de julho de 1823. Portugal reconheceu a independência em 1825, pelo Tratado do Rio de Janeiro, mediante indenização paga pelo Brasil.","example":"O 2 de Julho é a grande data cívica da Bahia."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"proclamacao","prompt":"Em que data comemoramos a Independência do Brasil?","options":["15 de novembro","7 de setembro","21 de abril","1º de janeiro"],"answer":1,"hints":["É feriado nacional.","Tem desfile cívico.","Setembro."],"explanation":"7 de setembro (de 1822)."},{"id":"q2","type":"mc","difficulty":1,"skill":"proclamacao","prompt":"Quem proclamou a independência?","options":["Dom João VI","Dom Pedro","Tiradentes","Deodoro da Fonseca"],"answer":1,"hints":["Era o príncipe regente.","Virou o primeiro imperador.","Dom…"],"explanation":"Dom Pedro, depois Dom Pedro I."},{"id":"q3","type":"tf","difficulty":1,"skill":"proclamacao","prompt":"Depois da independência, o Brasil virou uma república.","answer":false,"hints":["Quem passou a governar?","Um imperador.","Imperador = monarquia."],"explanation":"Falso. Virou um império (monarquia); a república veio só em 1889."},{"id":"q4","type":"fill","difficulty":2,"skill":"contexto","prompt":"A família real portuguesa chegou ao Brasil em ____.","answers":["1808"],"hints":["Fugia de Napoleão.","Início do século XIX.","18-0-8."],"explanation":"Em 1808."},{"id":"q5","type":"mc","difficulty":2,"skill":"dia_do_fico","prompt":"O que foi o Dia do Fico?","options":["A volta de Dom João VI a Portugal","A decisão de Dom Pedro de permanecer no Brasil","A coroação de Dom Pedro I","O fim da escravidão"],"answer":1,"hints":["\"Diga ao povo que fico.\"","Ele ficaria onde?","No Brasil."],"explanation":"Em 9/1/1822, Dom Pedro decidiu ficar no Brasil."},{"id":"q6","type":"match","difficulty":2,"skill":"reconhecimento","prompt":"Ligue cada fato à data.","pairs":[["Chegada da família real","1808"],["Proclamação da independência","1822"],["Independência na Bahia","1823"],["Reconhecimento por Portugal","1825"]],"hints":["A chegada da família real é a mais antiga.","A Bahia lutou depois do 7 de setembro.","O reconhecimento é a mais recente."],"explanation":"1808 → 1822 → 1823 → 1825."},{"id":"q7","type":"tf","difficulty":2,"skill":"reconhecimento","prompt":"Portugal reconheceu a independência imediatamente, em 1822.","answer":false,"hints":["Houve guerras depois.","O reconhecimento veio por tratado.","Três anos depois."],"explanation":"Falso. Só em 1825, pelo Tratado do Rio de Janeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"reconhecimento","prompt":"Em qual província houve forte resistência portuguesa, encerrada em 2 de julho de 1823?","options":["São Paulo","Bahia","Rio Grande do Sul","Minas Gerais"],"answer":1,"hints":["É uma data cívica estadual.","Fica no Nordeste.","Capital: Salvador."],"explanation":"Na Bahia."},{"id":"q9","type":"fill","difficulty":3,"skill":"proclamacao","prompt":"A independência foi proclamada às margens do riacho ________.","answers":["ipiranga"],"hints":["Fica em São Paulo.","\"Grito do …\"","Ipi…"],"explanation":"Ipiranga."},{"id":"q10","type":"open","difficulty":3,"skill":"contexto","prompt":"Por que a vinda da família real em 1808 ajudou no caminho da independência?","modelAnswer":"Porque o Brasil passou a ser a sede do governo português, ganhou instituições, portos abertos e depois virou Reino Unido. Com isso, a elite local não aceitou voltar a ser uma simples colônia quando Portugal tentou recolonizá-lo.","keywords":["sede","governo","instituicoes","portos","reino unido","colonia","importancia","autonomia"],"hints":["O que o Brasil ganhou com a corte aqui?","Virou o quê em 1815?","Por que não aceitaria voltar a ser colônia?"],"explanation":"O Brasil ganhou autonomia e importância e não aceitou voltar a ser colônia."}],"review":["1808: família real no Rio","9/1/1822: Dia do Fico","7/9/1822: proclamação; Dom Pedro I imperador","1823: Bahia (2 de Julho) · 1825: reconhecimento por Portugal"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Arquivo Nacional — Reconhecimento da Independência do Brasil por Portugal","url":"https://historialuso.an.gov.br/index.php?option=com_content&view=article&id=3869%3Areconhecimento-da-independencia-do-brasil-por-port&catid=149&Itemid=215","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Idade Contemporânea","subtopic":"Segunda Guerra Mundial","relatedQuestions":["Por que começou a Segunda Guerra Mundial?","O que foi o Holocausto?","O Brasil participou da Segunda Guerra?","Quem eram os Aliados e o Eixo?"],"id":"his-segunda-guerra","subject":"historia","title":"Segunda Guerra Mundial","levels":["fund2","medio"],"grade":"9º ano e 3ª série","aliases":["segunda guerra mundial","segunda guerra","2 guerra","nazismo","holocausto","hitler","feb","forca expedicionaria brasileira","aliados e eixo"],"summary":"Causas, lados, principais fatos, o Holocausto e a participação do Brasil (1939–1945).","intro":"Foi o maior conflito da história. Vamos entender por que começou e como terminou.","skills":{"causas":"Causas","lados":"Eixo e Aliados","fatos":"Principais acontecimentos","brasil":"O Brasil na guerra"},"blocks":[{"id":"b1","skill":"causas","title":"Por que começou","text":"Após a Primeira Guerra, a crise econômica e o descontentamento favoreceram regimes totalitários, como o nazismo na Alemanha (Hitler) e o fascismo na Itália (Mussolini). A guerra começou em 1º de setembro de 1939, com a invasão da Polônia pela Alemanha.","example":"O Tratado de Versalhes impôs duras punições à Alemanha, o que os nazistas usaram na propaganda."},{"id":"b2","skill":"lados","title":"Os dois lados","text":"O Eixo reunia principalmente Alemanha, Itália e Japão. Os Aliados reuniam Reino Unido, França, União Soviética (a partir de 1941) e Estados Unidos (a partir de 1941), entre outros.","example":"Os EUA entraram na guerra após o ataque japonês a Pearl Harbor, em dezembro de 1941."},{"id":"b3","skill":"fatos","title":"Fatos marcantes e o Holocausto","text":"O regime nazista perseguiu e assassinou cerca de 6 milhões de judeus, além de ciganos, pessoas com deficiência e outros grupos: o Holocausto. Em 1944 os Aliados desembarcaram na Normandia (Dia D). A guerra terminou na Europa em maio de 1945 e, após as bombas atômicas em Hiroshima e Nagasaki, o Japão se rendeu em setembro de 1945.","example":"Após a guerra foi criada a ONU (1945), para tentar evitar novos conflitos mundiais."},{"id":"b4","skill":"brasil","title":"O Brasil na guerra","text":"O Brasil declarou guerra ao Eixo em 1942, após navios brasileiros serem afundados. A Força Expedicionária Brasileira (FEB), com mais de 25 mil militares, lutou na Itália. A tomada de Monte Castelo, em 21 de fevereiro de 1945, é sua vitória mais lembrada.","example":"O símbolo da FEB era uma cobra fumando — resposta a quem dizia que era \"mais fácil uma cobra fumar\" do que o Brasil ir à guerra."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"causas","prompt":"Em que período aconteceu a Segunda Guerra Mundial?","options":["1914–1918","1939–1945","1789–1799","1964–1985"],"answer":1,"hints":["Começou no fim da década de 1930.","Terminou em meados dos anos 1940.","Termina em 1945."],"explanation":"De 1939 a 1945."},{"id":"q2","type":"mc","difficulty":1,"skill":"causas","prompt":"Qual fato marcou o início da guerra, em 1939?","options":["Ataque a Pearl Harbor","Invasão da Polônia pela Alemanha","Bomba de Hiroshima","Dia D"],"answer":1,"hints":["Foi na Europa.","Foi a Alemanha que atacou.","Um país vizinho da Alemanha a leste."],"explanation":"A invasão da Polônia, em 1º de setembro de 1939."},{"id":"q3","type":"match","difficulty":2,"skill":"lados","prompt":"Ligue cada país ao lado em que lutou.","pairs":[["Alemanha","Eixo"],["Estados Unidos","Aliados"],["Japão","Eixo (Ásia)"],["Reino Unido","Aliados (Europa)"]],"hints":["Hitler governava a Alemanha.","O Japão atacou os EUA.","Reino Unido lutou contra a Alemanha."],"explanation":"Alemanha e Japão: Eixo · EUA e Reino Unido: Aliados."},{"id":"q4","type":"tf","difficulty":1,"skill":"fatos","prompt":"O Holocausto foi a perseguição e o assassinato de milhões de judeus e outros grupos pelo regime nazista.","answer":true,"hints":["Aconteceu durante a guerra.","Foi promovido pelos nazistas.","Cerca de 6 milhões de judeus."],"explanation":"Verdadeiro."},{"id":"q5","type":"fill","difficulty":2,"skill":"brasil","prompt":"A sigla da força militar brasileira que lutou na Itália é ____.","answers":["feb"],"hints":["Força Expedicionária…","Brasileira.","Três letras."],"explanation":"FEB — Força Expedicionária Brasileira."},{"id":"q6","type":"mc","difficulty":2,"skill":"lados","prompt":"Por que os Estados Unidos entraram na guerra em 1941?","options":["Por causa do Dia D","Por causa do ataque japonês a Pearl Harbor","Por causa da invasão da Polônia","Por causa da criação da ONU"],"answer":1,"hints":["Foram atacados.","Pelo Japão.","Numa base no Havaí."],"explanation":"Após o ataque a Pearl Harbor, em dezembro de 1941."},{"id":"q7","type":"mc","difficulty":2,"skill":"brasil","prompt":"A vitória mais lembrada da FEB foi a tomada de:","options":["Normandia","Monte Castelo","Stalingrado","Berlim"],"answer":1,"hints":["Fica na Itália.","Foi em fevereiro de 1945.","Monte…"],"explanation":"Monte Castelo, 21/2/1945."},{"id":"q8","type":"tf","difficulty":3,"skill":"fatos","prompt":"A guerra terminou no mesmo dia na Europa e na Ásia.","answer":false,"hints":["A Alemanha se rendeu primeiro.","O Japão resistiu mais alguns meses.","Maio × setembro de 1945."],"explanation":"Falso. Europa: maio de 1945; Japão: setembro de 1945."},{"id":"q9","type":"mc","difficulty":3,"skill":"fatos","prompt":"Qual organização foi criada em 1945 para tentar evitar novas guerras mundiais?","options":["OTAN","ONU","União Europeia","Mercosul"],"answer":1,"hints":["Reúne quase todos os países.","Sede em Nova York.","Organização das Nações Unidas."],"explanation":"A ONU."},{"id":"q10","type":"open","difficulty":3,"skill":"causas","prompt":"Cite fatores que ajudaram os regimes totalitários a chegarem ao poder antes da guerra.","modelAnswer":"A crise econômica, o desemprego, o descontentamento com os resultados da Primeira Guerra e com o Tratado de Versalhes, e o medo de revoluções favoreceram líderes autoritários como Hitler e Mussolini, que usavam propaganda e nacionalismo.","keywords":["crise","economica","desemprego","versalhes","primeira guerra","nacionalismo","propaganda"],"hints":["Como estava a economia?","O que o Tratado de Versalhes impôs?","Fale de crise e descontentamento."],"explanation":"Crise econômica, Versalhes e nacionalismo fortaleceram o nazifascismo."}],"review":["1939–1945; começou com a invasão da Polônia","Eixo (Alemanha, Itália, Japão) × Aliados","Holocausto; Dia D (1944); fim em 1945","Brasil: FEB na Itália, Monte Castelo"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Blog do Exército Brasileiro — A tomada de Monte Castello pela FEB","url":"https://eblog.eb.mil.br/en/w/a-tomada-de-monte-castello-pela-for%C3%A7a-expedicion%C3%A1ria-brasileira-feb-em-21-de-fevereiro-de-1945","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Cartografia","subtopic":"Coordenadas geográficas","relatedQuestions":["O que é latitude e longitude?","O que é a Linha do Equador?","O que é o Meridiano de Greenwich?"],"id":"geo-coordenadas","subject":"geografia","title":"Coordenadas geográficas","levels":["fund2","medio"],"grade":"6º ano","aliases":["coordenadas geograficas","latitude","longitude","paralelos","meridianos","linha do equador","greenwich","hemisferios","localizacao"],"summary":"Aprenda latitude, longitude, paralelos e meridianos — o \"endereço\" de qualquer lugar do planeta.","intro":"Como o GPS sabe exatamente onde você está? Com um sistema de linhas imaginárias. Vamos conhecê-lo.","skills":{"latitude":"Paralelos e latitude","longitude":"Meridianos e longitude","coordenadas":"Coordenadas","hemisferios":"Hemisférios e o Brasil"},"blocks":[{"id":"b1","skill":"latitude","title":"Paralelos e latitude","text":"Paralelos são linhas imaginárias horizontais que dão a volta na Terra. O principal é a Linha do Equador (0°), que divide o planeta em Norte e Sul. Latitude é a distância, em graus, de um lugar até o Equador: vai de 0° a 90°, Norte (N) ou Sul (S).","example":"Os polos ficam a 90°: Polo Norte a 90° N e Polo Sul a 90° S.","variants":{"simples":"Imagine anéis deitados em volta da Terra. O do meio é o Equador. Latitude diz se você está mais para cima (Norte) ou para baixo (Sul) dele.","exemplo":"Os Trópicos de Câncer e de Capricórnio também são paralelos. O de Capricórnio passa bem perto da cidade de São Paulo.","outra":"Pense nos degraus de uma escada que sobe do Equador até o polo: cada degrau é um grau de latitude. O último degrau é o 90.","detalhado":"Os paralelos principais são: Equador (0°), Trópicos de Câncer e de Capricórnio (cerca de 23°27' N e S) e Círculos Polares Ártico e Antártico (cerca de 66°33' N e S). Todos os paralelos são paralelos entre si e diminuem de tamanho em direção aos polos."}},{"id":"b2","skill":"longitude","title":"Meridianos e longitude","text":"Meridianos são linhas imaginárias que vão de um polo ao outro. O principal é o Meridiano de Greenwich (0°), que divide a Terra em Leste (L ou E) e Oeste (O ou W). Longitude é a distância, em graus, até Greenwich: vai de 0° a 180°.","example":"Greenwich é um bairro de Londres, na Inglaterra, por onde passa o meridiano 0°.","variants":{"simples":"Meridianos são linhas que descem do Polo Norte ao Polo Sul, como os gomos de uma laranja. Longitude diz se você está para a direita (Leste) ou para a esquerda (Oeste) de Greenwich.","exemplo":"O Brasil fica a oeste de Greenwich; o Japão fica a leste.","outra":"Latitude responde \"quanto ao norte ou ao sul?\". Longitude responde \"quanto ao leste ou ao oeste?\".","detalhado":"O meridiano oposto a Greenwich (180°) serve de referência para a Linha Internacional de Data. Os meridianos também são usados para definir os fusos horários: a cada 15° de longitude, a hora muda em 1 hora (360° ÷ 24 h)."}},{"id":"b3","skill":"coordenadas","title":"Coordenadas: o endereço do planeta","text":"O cruzamento de uma latitude com uma longitude forma uma coordenada geográfica. Ela indica a localização exata de qualquer ponto da Terra. O GPS usa esse sistema.","example":"A cidade de São Paulo fica perto de 23° S e 46° O: ao sul do Equador e a oeste de Greenwich.","variants":{"simples":"Coordenada é como o número da rua e da casa, só que para o planeta inteiro: uma latitude + uma longitude.","exemplo":"No jogo de batalha naval você diz \"B5\": uma letra e um número. Coordenadas são isso: latitude e longitude.","outra":"Uma linha só não basta: a latitude diz uma \"faixa\" e a longitude diz outra. Onde elas se cruzam fica o ponto exato.","detalhado":"Coordenadas podem ser escritas em graus, minutos e segundos (23°32'51\" S) ou em graus decimais, usando sinal negativo para Sul e Oeste (−23,547; −46,636), que é o formato usado por mapas digitais."}},{"id":"b4","skill":"hemisferios","title":"Hemisférios e o Brasil","text":"O Equador separa os hemisférios Norte e Sul. Greenwich separa os hemisférios Oriental (Leste) e Ocidental (Oeste). O Brasil fica todo no Hemisfério Ocidental e em sua maior parte no Hemisfério Sul — mas a Linha do Equador passa pelo norte do país.","example":"Em Macapá (AP), o Equador passa pela cidade; lá existe o monumento Marco Zero.","variants":{"simples":"O Brasil está quase todo \"embaixo\" do Equador (Sul) e todo à esquerda de Greenwich (Oeste).","exemplo":"Roraima e parte do Amapá e do Amazonas ficam no Hemisfério Norte.","outra":"Pense na Terra cortada duas vezes: uma na horizontal (Equador) e outra na vertical (Greenwich). O Brasil está no pedaço de baixo à esquerda — com uma pontinha em cima.","detalhado":"O território brasileiro é cortado pelo Equador (no Norte) e pelo Trópico de Capricórnio (no Sudeste/Sul). Por isso, a maior parte do país está na zona intertropical, o que explica o predomínio de climas quentes."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"latitude","prompt":"Qual linha imaginária marca a latitude 0°?","options":["Meridiano de Greenwich","Linha do Equador","Trópico de Capricórnio","Círculo Polar Ártico"],"answer":1,"hints":["Latitude mede Norte e Sul.","É a linha que divide Norte e Sul.","Passa pelo \"meio\" da Terra."],"explanation":"A Linha do Equador é o paralelo 0°."},{"id":"q2","type":"mc","difficulty":1,"skill":"longitude","prompt":"Qual é o meridiano 0°?","options":["Equador","Greenwich","Trópico de Câncer","Meridiano de Brasília"],"answer":1,"hints":["Ele divide Leste e Oeste.","Passa por Londres.","Começa com G."],"explanation":"O Meridiano de Greenwich é o 0° de longitude."},{"id":"q3","type":"tf","difficulty":1,"skill":"latitude","prompt":"A latitude pode chegar a, no máximo, 90°.","answer":true,"hints":["Onde fica o ponto mais distante do Equador?","Nos polos.","Os polos ficam a 90°."],"explanation":"Verdadeiro. A latitude vai de 0° (Equador) a 90° (polos)."},{"id":"q4","type":"fill","difficulty":2,"skill":"longitude","prompt":"A longitude vai de 0° até ____°.","answers":["180"],"hints":["É o dobro da latitude máxima.","A latitude máxima é 90.","90 × 2."],"explanation":"A longitude vai de 0° a 180° para Leste ou Oeste."},{"id":"q5","type":"mc","difficulty":2,"skill":"coordenadas","prompt":"Uma coordenada geográfica é formada pelo cruzamento de:","options":["Dois paralelos","Latitude e longitude","Dois hemisférios","Equador e Trópico"],"answer":1,"hints":["Uma linha só não basta.","Precisamos de uma horizontal e uma vertical.","Uma de cada tipo."],"explanation":"Latitude + longitude = coordenada."},{"id":"q6","type":"match","difficulty":2,"skill":"coordenadas","prompt":"Ligue cada termo à sua descrição.","pairs":[["Equador","Divide Norte e Sul"],["Greenwich","Divide Leste e Oeste"],["Latitude","Distância até o Equador"],["Longitude","Distância até Greenwich"]],"hints":["O Equador é horizontal.","Greenwich vai de polo a polo.","Latitude usa o Equador como referência."],"explanation":"Equador → N/S; Greenwich → L/O; Latitude → até o Equador; Longitude → até Greenwich."},{"id":"q7","type":"tf","difficulty":2,"skill":"hemisferios","prompt":"O Brasil está inteiramente no Hemisfério Sul.","answer":false,"hints":["A Linha do Equador passa pelo Brasil?","Passa, sim.","Veja Macapá e Roraima."],"explanation":"Falso. A maior parte está no Sul, mas o Equador passa pelo norte do país."},{"id":"q8","type":"mc","difficulty":2,"skill":"hemisferios","prompt":"Em relação a Greenwich, o Brasil fica:","options":["Totalmente no Hemisfério Oriental","Totalmente no Hemisfério Ocidental","Metade em cada","Sobre o meridiano 0°"],"answer":1,"hints":["Greenwich passa pela Europa e pela África.","O Brasil está à esquerda no mapa.","Oeste = Ocidental."],"explanation":"O Brasil está todo a oeste de Greenwich: Hemisfério Ocidental."},{"id":"q9","type":"mc","difficulty":3,"skill":"coordenadas","prompt":"Um ponto em 23° S e 46° O fica:","options":["Acima do Equador e a leste de Greenwich","Abaixo do Equador e a oeste de Greenwich","Sobre o Equador","No Polo Sul"],"answer":1,"hints":["S = Sul. O = Oeste.","Sul fica abaixo do Equador.","Oeste fica à esquerda de Greenwich."],"explanation":"S → abaixo do Equador; O → a oeste de Greenwich. É perto de São Paulo."},{"id":"q10","type":"fill","difficulty":3,"skill":"latitude","prompt":"O trópico que passa pelo Brasil, perto de São Paulo, é o Trópico de ________.","answers":["capricornio","capricórnio"],"hints":["Existem dois trópicos: Câncer e…","O de Câncer fica no Hemisfério Norte.","O outro fica no Sul."],"explanation":"O Trópico de Capricórnio."},{"id":"q11","type":"tf","difficulty":3,"skill":"longitude","prompt":"Os paralelos são linhas que vão de um polo ao outro.","answer":false,"hints":["Pense na forma de cada linha.","Quem liga os polos são os \"gomos da laranja\".","Esses são os meridianos."],"explanation":"Falso. Quem vai de polo a polo são os meridianos; os paralelos são horizontais."},{"id":"q12","type":"open","difficulty":3,"skill":"coordenadas","prompt":"Por que as coordenadas geográficas são úteis no dia a dia?","modelAnswer":"Porque permitem localizar com exatidão qualquer ponto da Terra. O GPS do celular, os aplicativos de mapa, aviões e navios usam coordenadas para saber onde estão e traçar rotas.","keywords":["localizar","localizacao","exata","gps","mapa","ponto","rota"],"hints":["Pense no celular.","Que aplicativo usa sua localização?","Fale em localizar ou em GPS."],"explanation":"Elas localizam qualquer ponto com exatidão — é o que o GPS faz."}],"review":["Paralelos → latitude (0° a 90°, N/S), referência: Equador","Meridianos → longitude (0° a 180°, L/O), referência: Greenwich","Coordenada = latitude + longitude","Brasil: todo no Ocidental, maior parte no Sul"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Geografia","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Natureza e paisagem","subtopic":"Biomas do Brasil","relatedQuestions":["Quais são os biomas brasileiros?","Qual é o maior bioma do Brasil?","O que é a Caatinga?","O que é o Cerrado?"],"id":"geo-biomas-brasileiros","subject":"geografia","title":"Biomas brasileiros","levels":["fund1","fund2","medio"],"grade":"4º ao 7º ano","aliases":["biomas","biomas brasileiros","amazonia","cerrado","mata atlantica","caatinga","pampa","pantanal","vegetacao do brasil"],"summary":"Conheça os seis biomas do Brasil e o que torna cada um especial.","intro":"O Brasil tem florestas, savanas, sertão, campos e áreas alagadas. São seis biomas diferentes.","skills":{"conceito":"O que é bioma","florestas":"Amazônia e Mata Atlântica","outros":"Cerrado, Caatinga, Pampa e Pantanal","preservacao":"Ameaças e preservação"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é um bioma","text":"Bioma é uma grande região com clima, vegetação e animais parecidos. Segundo o IBGE, o Brasil tem seis: Amazônia, Cerrado, Mata Atlântica, Caatinga, Pampa e Pantanal.","example":"A Amazônia é o maior, com cerca de 49,5% do território; o Pantanal é o menor, com cerca de 1,8%.","variants":{"simples":"Bioma é um grande \"tipo de paisagem\" com seu clima, plantas e bichos. O Brasil tem seis."}},{"id":"b2","skill":"florestas","title":"As florestas","text":"A Amazônia é uma floresta tropical quente e úmida, com enorme biodiversidade e a maior bacia hidrográfica do mundo. A Mata Atlântica acompanha o litoral; é um dos biomas mais devastados, pois ali se concentram grandes cidades.","example":"Onças-pintadas e botos vivem na Amazônia; o mico-leão-dourado é símbolo da Mata Atlântica.","variants":{"simples":"Amazônia: a maior floresta, muito quente e úmida. Mata Atlântica: floresta perto do mar, que perdeu muita área."}},{"id":"b3","skill":"outros","title":"Cerrado, Caatinga, Pampa e Pantanal","text":"Cerrado: savana do Brasil Central, com árvores de troncos retorcidos e muitas nascentes. Caatinga: bioma semiárido do Nordeste, o único exclusivamente brasileiro. Pampa: campos do sul do Rio Grande do Sul. Pantanal: maior área úmida continental do planeta, que alaga em parte do ano.","example":"O mandacaru é típico da Caatinga; o tuiuiú é símbolo do Pantanal.","variants":{"simples":"Cerrado tem árvores tortinhas. Caatinga é seca. Pampa é campo. Pantanal alaga."}},{"id":"b4","skill":"preservacao","title":"Ameaças e preservação","text":"Desmatamento, queimadas, expansão agropecuária sem controle e poluição ameaçam os biomas. Unidades de conservação, fiscalização e uso sustentável ajudam a protegê-los.","example":"Parques nacionais, como o da Chapada dos Veadeiros (Cerrado), protegem áreas naturais."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Quantos biomas o Brasil tem, segundo o IBGE?","options":["4","5","6","8"],"answer":2,"hints":["Amazônia, Cerrado, Mata Atlântica…","…Caatinga, Pampa e Pantanal.","Conte."],"explanation":"São 6 biomas."},{"id":"q2","type":"mc","difficulty":1,"skill":"florestas","prompt":"Qual é o maior bioma brasileiro?","options":["Cerrado","Amazônia","Pantanal","Caatinga"],"answer":1,"hints":["É uma floresta.","Fica no Norte.","Tem o rio mais volumoso do mundo."],"explanation":"A Amazônia, com cerca de 49,5% do território."},{"id":"q3","type":"tf","difficulty":1,"skill":"outros","prompt":"A Caatinga é o único bioma exclusivamente brasileiro.","answer":true,"hints":["Fica no Nordeste.","Não aparece em outros países.","É 100% brasileira."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"outros","prompt":"Ligue cada bioma à sua característica.","pairs":[["Cerrado","Árvores de troncos retorcidos"],["Caatinga","Clima semiárido"],["Pantanal","Maior área úmida continental"],["Pampa","Campos do sul do Brasil"]],"hints":["Semiárido = pouca chuva.","Área úmida alaga.","Campos = Pampa."],"explanation":"Cerrado: troncos retorcidos · Caatinga: semiárido · Pantanal: alagado · Pampa: campos."},{"id":"q5","type":"fill","difficulty":2,"skill":"conceito","prompt":"O menor bioma do Brasil é o ________.","answers":["pantanal"],"hints":["Ocupa cerca de 1,8% do país.","É uma área alagada.","Fica em MT e MS."],"explanation":"O Pantanal."},{"id":"q6","type":"mc","difficulty":2,"skill":"florestas","prompt":"Por que a Mata Atlântica é um dos biomas mais devastados?","options":["Porque fica no deserto","Porque ali se concentram grandes cidades e ocupação humana antiga","Porque não tem árvores","Porque é o maior bioma"],"answer":1,"hints":["Onde ela fica?","No litoral.","Onde vive a maior parte da população."],"explanation":"A ocupação humana e as cidades se concentram no litoral."},{"id":"q7","type":"tf","difficulty":2,"skill":"outros","prompt":"O Pampa aparece no Brasil apenas no Rio Grande do Sul.","answer":true,"hints":["É um bioma do extremo sul.","Estende-se ao Uruguai e à Argentina.","No Brasil, só em um estado."],"explanation":"Verdadeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"outros","prompt":"Qual bioma é chamado de \"berço das águas\" por ter muitas nascentes de rios importantes?","options":["Pampa","Cerrado","Caatinga","Mata Atlântica"],"answer":1,"hints":["Fica no Brasil Central.","Tem árvores retorcidas.","Savana brasileira."],"explanation":"O Cerrado."},{"id":"q9","type":"mc","difficulty":3,"skill":"preservacao","prompt":"Qual destas ações ajuda a preservar os biomas?","options":["Queimadas para limpar o terreno","Criação de unidades de conservação","Desmatamento para pastagem","Descarte de lixo nos rios"],"answer":1,"hints":["Três opções causam danos.","Procure uma forma de proteger áreas.","Parques e reservas."],"explanation":"Unidades de conservação protegem áreas naturais."},{"id":"q10","type":"open","difficulty":3,"skill":"preservacao","prompt":"Escolha um bioma brasileiro e explique uma ameaça que ele sofre.","modelAnswer":"A Amazônia sofre com o desmatamento e as queimadas para abrir áreas de pasto e garimpo, o que destrói habitats, reduz a biodiversidade e afeta o clima.","keywords":["desmatamento","queimada","garimpo","pasto","poluicao","biodiversidade","agropecuaria"],"hints":["Escolha um bioma.","O que as pessoas fazem que o prejudica?","Fale de desmatamento ou queimadas."],"explanation":"Desmatamento e queimadas estão entre as principais ameaças."}],"review":["6 biomas: Amazônia, Cerrado, Mata Atlântica, Caatinga, Pampa, Pantanal","Amazônia é o maior (~49,5%); Pantanal, o menor (~1,8%)","Caatinga: exclusiva do Brasil","Ameaças: desmatamento e queimadas"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Geografia","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"IBGE Educa — Os biomas brasileiros","url":"https://educa.ibge.gov.br/jovens/materias-especiais/21592-os-biomas-brasileiros.html","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Espaço brasileiro","subtopic":"Regiões do Brasil","relatedQuestions":["Quais são as regiões do Brasil?","Quantos estados tem o Brasil?","Quais estados ficam no Nordeste?","Em que região fica Santa Catarina?"],"id":"geo-regioes-brasil","subject":"geografia","title":"Regiões do Brasil","levels":["fund1","fund2"],"grade":"4º e 7º ano","aliases":["regioes do brasil","regioes brasileiras","estados e capitais","divisao regional","norte nordeste sudeste sul centro oeste","ibge regioes"],"summary":"As cinco regiões do IBGE, seus estados e características principais.","intro":"O Brasil é enorme: para estudar melhor, o IBGE o dividiu em cinco regiões.","skills":{"divisao":"A divisão do IBGE","estados":"Estados de cada região","caracteristicas":"Características das regiões"},"blocks":[{"id":"b1","skill":"divisao","title":"Cinco regiões","text":"O Brasil tem 26 estados e o Distrito Federal, onde fica Brasília, a capital do país. O IBGE agrupa os estados em cinco regiões: Norte, Nordeste, Centro-Oeste, Sudeste e Sul.","example":"A divisão atual está em vigor desde 1988, quando Tocantins foi criado.","variants":{"simples":"O Brasil tem 5 regiões: Norte, Nordeste, Centro-Oeste, Sudeste e Sul."}},{"id":"b2","skill":"estados","title":"Quem está em cada região","text":"Norte: AM, PA, AC, RO, RR, AP, TO. Nordeste: MA, PI, CE, RN, PB, PE, AL, SE, BA. Centro-Oeste: MT, MS, GO e DF. Sudeste: SP, RJ, MG, ES. Sul: PR, SC, RS.","example":"Santa Catarina fica na Região Sul; a Bahia, no Nordeste.","variants":{"simples":"O Nordeste tem mais estados (9). O Sul tem menos (3): Paraná, Santa Catarina e Rio Grande do Sul."}},{"id":"b3","skill":"caracteristicas","title":"Cada região tem seu jeito","text":"O Norte é a maior região e abriga grande parte da Amazônia. O Nordeste tem o maior número de estados e um litoral extenso. O Centro-Oeste se destaca na agropecuária. O Sudeste é a região mais populosa e industrializada. O Sul tem clima subtropical, com invernos mais frios.","example":"São Paulo, no Sudeste, é a cidade mais populosa do país.","variants":{"simples":"Norte: maior e com floresta. Sudeste: mais gente. Sul: mais frio."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"divisao","prompt":"Em quantas regiões o IBGE divide o Brasil?","options":["3","4","5","27"],"answer":2,"hints":["Norte, Nordeste…","…Centro-Oeste, Sudeste, Sul.","Conte."],"explanation":"Cinco regiões."},{"id":"q2","type":"mc","difficulty":1,"skill":"estados","prompt":"Santa Catarina fica em qual região?","options":["Sudeste","Sul","Nordeste","Centro-Oeste"],"answer":1,"hints":["É uma das regiões mais frias.","Tem só 3 estados.","Junto com Paraná e RS."],"explanation":"Região Sul."},{"id":"q3","type":"tf","difficulty":1,"skill":"divisao","prompt":"Brasília, a capital do país, fica no Distrito Federal.","answer":true,"hints":["O DF não é um estado comum.","É onde fica a capital.","Região Centro-Oeste."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":2,"skill":"divisao","prompt":"O Brasil tem ____ estados, além do Distrito Federal.","answers":["26","vinte e seis"],"hints":["São 27 unidades da federação ao todo.","Tire o DF.","27 − 1."],"explanation":"26 estados + DF."},{"id":"q5","type":"match","difficulty":2,"skill":"caracteristicas","prompt":"Ligue cada região à característica.","pairs":[["Norte","Maior região, com grande parte da Amazônia"],["Sudeste","Mais populosa e industrializada"],["Nordeste","Maior número de estados"],["Sul","Clima subtropical, invernos frios"]],"hints":["A floresta fica no Norte.","São Paulo está no Sudeste.","O Nordeste tem 9 estados."],"explanation":"Norte: Amazônia · Sudeste: população · Nordeste: 9 estados · Sul: frio."},{"id":"q6","type":"mc","difficulty":2,"skill":"estados","prompt":"Qual região tem mais estados?","options":["Norte","Nordeste","Sudeste","Sul"],"answer":1,"hints":["São nove estados.","Inclui Bahia e Pernambuco.","Nord…"],"explanation":"O Nordeste, com 9 estados."},{"id":"q7","type":"tf","difficulty":2,"skill":"estados","prompt":"Minas Gerais fica na Região Centro-Oeste.","answer":false,"hints":["MG faz divisa com SP e RJ.","Está na região mais populosa.","Sudeste."],"explanation":"Falso. Minas Gerais fica no Sudeste."},{"id":"q8","type":"mc","difficulty":3,"skill":"estados","prompt":"Quais estados formam a Região Sudeste?","options":["SP, RJ, MG e ES","SP, PR, SC e RS","MG, GO, MT e MS","RJ, BA, ES e SP"],"answer":0,"hints":["São quatro estados.","Inclui o Espírito Santo.","Não inclui Paraná."],"explanation":"São Paulo, Rio de Janeiro, Minas Gerais e Espírito Santo."},{"id":"q9","type":"fill","difficulty":3,"skill":"estados","prompt":"O estado criado em 1988, que hoje faz parte da Região Norte, é o ________.","answers":["tocantins"],"hints":["Foi desmembrado de Goiás.","Capital: Palmas.","Toca…"],"explanation":"Tocantins."},{"id":"q10","type":"mc","difficulty":3,"skill":"caracteristicas","prompt":"A Região Centro-Oeste se destaca principalmente por:","options":["Pesca em alto-mar","Agropecuária (soja, milho e gado)","Clima frio com neve","Maior população do país"],"answer":1,"hints":["Tem grandes áreas planas no Cerrado.","Produz muitos grãos.","E cria gado."],"explanation":"Agropecuária: soja, milho e gado."}],"review":["26 estados + DF; 5 regiões do IBGE","Nordeste: 9 estados · Sul: 3","Norte: maior · Sudeste: mais populoso","Centro-Oeste: agropecuária · Sul: subtropical"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Geografia","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"IBGE Educa — Divisão Territorial","url":"https://educa.ibge.gov.br/jovens/conheca-o-brasil/territorio/19637-divisao-territorial.html","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Gramática","subtopic":"Verb to be","relatedQuestions":["Quando usar am, is e are?","Como fazer pergunta com verbo to be?","Como negar em inglês?"],"id":"ing-verb-to-be","subject":"ingles","title":"Verb to be","levels":["fund1","fund2","medio"],"grade":"6º ano","aliases":["verb to be","verbo to be","to be","am is are","ingles basico","verbo ser estar ingles"],"summary":"Aprenda o verbo mais usado do inglês: to be (ser/estar), nas formas afirmativa, negativa e interrogativa.","intro":"Let's start! O verbo \"to be\" significa \"ser\" ou \"estar\". Com ele você já consegue se apresentar e descrever coisas.","skills":{"afirmativa":"Forma afirmativa","contracao":"Contrações","negativa":"Forma negativa","interrogativa":"Perguntas e respostas curtas"},"blocks":[{"id":"b1","skill":"afirmativa","title":"Am, is, are","text":"O verbo to be tem três formas no presente: I am (eu sou/estou); he is, she is, it is (ele/ela é/está); you are, we are, they are (você é, nós somos, eles são).","example":"I am a student. = Eu sou estudante. · She is happy. = Ela está feliz. · They are my friends. = Eles são meus amigos.","variants":{"simples":"I → am. He, she, it → is. You, we, they → are. Decore essas três duplas e pronto!","exemplo":"I am 12 years old. (Eu tenho 12 anos — em inglês se usa \"ser\" para idade!) · My dog is small. · We are at school.","outra":"Pense em três caixas: a caixa do \"am\" só tem o I. A caixa do \"is\" tem uma pessoa ou coisa só (he, she, it). A caixa do \"are\" tem o resto.","detalhado":"Em inglês, \"you\" serve para \"você\" e \"vocês\", e sempre usa \"are\". \"It\" é usado para coisas e animais. Diferente do português, o inglês usa \"to be\" para idade (I am 12), fome (I am hungry) e frio (I am cold)."}},{"id":"b2","skill":"contracao","title":"Contrações","text":"Na fala e em textos informais, juntamos o pronome e o verbo com um apóstrofo: I'm, you're, he's, she's, it's, we're, they're.","example":"I'm tired = I am tired. · They're here = They are here.","variants":{"simples":"É um \"atalho\": tira uma letra e coloca um apóstrofo ('). I am → I'm.","exemplo":"Numa música ou série você vai ouvir \"I'm fine\", \"You're welcome\", \"It's OK\".","outra":"O apóstrofo marca o lugar da letra que sumiu: I am → I'm (sumiu o \"a\"); he is → he's (sumiu o \"i\").","detalhado":"Não confunda \"it's\" (it is) com \"its\" (possessivo: \"dele/dela\" para coisas e animais): \"It's a dog. Its name is Rex.\" O mesmo vale para \"they're\" (they are) × \"their\" (deles)."}},{"id":"b3","skill":"negativa","title":"Forma negativa","text":"Para negar, coloque \"not\" depois do verbo: I am not, he is not, they are not. Contrações: isn't (is not) e aren't (are not). Com \"I\", usamos I'm not.","example":"He isn't tired. = Ele não está cansado. · We aren't late. = Nós não estamos atrasados.","variants":{"simples":"É só colocar \"not\" depois de am, is ou are. Is not = isn't. Are not = aren't.","exemplo":"I'm not hungry. (Não estou com fome.) · It isn't cold today. (Não está frio hoje.)","outra":"No português o \"não\" vem antes do verbo (\"não está\"). No inglês, o \"not\" vem depois do to be (\"is not\").","detalhado":"Existem duas contrações possíveis para a negativa: \"he's not\" ou \"he isn't\"; \"they're not\" ou \"they aren't\". Para \"I am not\" não existe \"amn't\" no inglês padrão — usamos \"I'm not\"."}},{"id":"b4","skill":"interrogativa","title":"Perguntas e respostas curtas","text":"Para perguntar, troque a ordem: o verbo vem antes do pronome. You are ready → Are you ready? Nas respostas curtas, repetimos o verbo: Yes, I am. / No, I'm not.","example":"Is she a doctor? — Yes, she is. / No, she isn't.","variants":{"simples":"Pergunta: o verbo pula para a frente. \"She is\" → \"Is she…?\"","exemplo":"Are they from Brazil? — Yes, they are. · Is it your book? — No, it isn't.","outra":"É como trocar duas peças de lugar: [she] [is] vira [is] [she]. E coloque o ponto de interrogação no fim.","detalhado":"Na resposta curta afirmativa não se usa contração: diz-se \"Yes, she is\", nunca \"Yes, she's\". Na negativa, a contração é normal: \"No, she isn't\"."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"afirmativa","prompt":"Complete: I ___ a student.","options":["am","is","are","be"],"answer":0,"hints":["Qual forma combina com \"I\"?","O \"I\" tem uma forma só dele.","A caixa que só tem o \"I\"."],"explanation":"Com \"I\" usamos \"am\": I am a student."},{"id":"q2","type":"mc","difficulty":1,"skill":"afirmativa","prompt":"Complete: She ___ happy.","options":["am","is","are","be"],"answer":1,"hints":["\"She\" é uma pessoa só.","He, she, it usam a mesma forma.","Tem duas letras."],"explanation":"Com \"she\" usamos \"is\"."},{"id":"q3","type":"fill","difficulty":1,"skill":"afirmativa","prompt":"Complete: They ___ my friends.","answers":["are"],"hints":["\"They\" é mais de uma pessoa.","You, we e they usam a mesma forma.","Tem três letras."],"explanation":"Com \"they\" usamos \"are\"."},{"id":"q4","type":"tf","difficulty":1,"skill":"afirmativa","prompt":"A frase \"We is at school\" está correta.","answer":false,"hints":["\"We\" é de qual caixa?","We = nós (mais de uma pessoa).","We usa \"are\"."],"explanation":"Falso. O correto é \"We are at school\"."},{"id":"q5","type":"match","difficulty":2,"skill":"contracao","prompt":"Ligue cada forma à sua contração.","pairs":[["I am","I'm"],["You are","You're"],["He is","He's"],["They are","They're"]],"hints":["Some uma letra do verbo.","Am → 'm.","Are → 're e is → 's."],"explanation":"I'm, You're, He's, They're."},{"id":"q6","type":"mc","difficulty":2,"skill":"negativa","prompt":"Qual é a negativa de \"He is tired\"?","options":["He aren't tired.","He isn't tired.","He not is tired.","He amn't tired."],"answer":1,"hints":["\"Not\" vem depois do verbo.","He usa \"is\".","Is + not = ?"],"explanation":"He is not tired = He isn't tired."},{"id":"q7","type":"mc","difficulty":2,"skill":"interrogativa","prompt":"Qual é a forma interrogativa de \"You are ready\"?","options":["You are ready?","Are you ready?","Ready you are?","Is you ready?"],"answer":1,"hints":["Na pergunta, duas palavras trocam de lugar.","O verbo vai para a frente.","Are + you."],"explanation":"\"Are you ready?\" — o verbo vem antes do pronome."},{"id":"q8","type":"fill","difficulty":2,"skill":"negativa","prompt":"Complete: I ___ not sad.","answers":["am"],"hints":["Com \"I\" o verbo é sempre o mesmo.","O \"not\" vem depois dele.","I ___ = eu sou/estou."],"explanation":"I am not sad (I'm not sad)."},{"id":"q9","type":"tf","difficulty":1,"skill":"contracao","prompt":"\"I'm\" é a contração de \"I am\".","answer":true,"hints":["O apóstrofo marca uma letra que sumiu.","Qual letra sumiu de \"am\"?","O \"a\"."],"explanation":"Verdadeiro."},{"id":"q10","type":"mc","difficulty":3,"skill":"interrogativa","prompt":"Qual é a resposta curta afirmativa correta para \"Is she a doctor?\"","options":["Yes, she's.","Yes, she is.","Yes, she are.","Yes, is she."],"answer":1,"hints":["Repita o verbo da pergunta.","Na resposta curta afirmativa, sem contração.","She + is."],"explanation":"\"Yes, she is.\" Não se usa contração na resposta curta afirmativa."},{"id":"q11","type":"mc","difficulty":3,"skill":"afirmativa","prompt":"Qual é a tradução de \"The books are on the table\"?","options":["O livro é da mesa.","Os livros estão na mesa.","Os livros são mesas.","A mesa está nos livros."],"answer":1,"hints":["\"Books\" está no plural.","\"On the table\" = em cima da mesa.","\"Are\" aqui é \"estão\"."],"explanation":"\"Os livros estão na mesa.\""},{"id":"q12","type":"fill","difficulty":3,"skill":"interrogativa","prompt":"Complete a pergunta: ___ they from Brazil?","answers":["are"],"hints":["Na pergunta o verbo vem primeiro.","\"They\" usa qual forma?","A mesma de \"you\" e \"we\"."],"explanation":"\"Are they from Brazil?\""}],"review":["I am · he/she/it is · you/we/they are","Contrações: I'm, you're, he's, they're","Negativa: not depois do verbo (isn't, aren't, I'm not)","Pergunta: verbo antes do pronome (Are you…?)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Gramática","subtopic":"Simple present","relatedQuestions":["Quando usar do e does?","Quando colocar s no verbo em inglês?","Como falar da rotina em inglês?"],"id":"ing-simple-present","subject":"ingles","title":"Simple present","levels":["fund2","medio"],"grade":"6º e 7º ano","aliases":["simple present","presente simples","do does","rotina em ingles","terceira pessoa ingles"],"summary":"Fale sobre rotinas e verdades em inglês usando o simple present, com do/does.","intro":"I study, she studies… Vamos aprender o tempo verbal da rotina!","skills":{"uso":"Quando usar","terceira":"Terceira pessoa (he/she/it)","negativa":"Negativa com don't/doesn't","interrogativa":"Perguntas com do/does"},"blocks":[{"id":"b1","skill":"uso","title":"Rotinas e verdades","text":"Usamos o simple present para hábitos, rotinas e fatos que são sempre verdadeiros. Palavras como always, usually, every day e never costumam aparecer.","example":"I go to school every day. · Water boils at 100 °C."},{"id":"b2","skill":"terceira","title":"He, she, it ganham -s","text":"Com he, she e it, o verbo recebe -s (works). Verbos terminados em -o, -s, -sh, -ch, -x recebem -es (goes, watches). Consoante + y vira -ies (study → studies). Have vira has.","example":"She plays guitar. · He watches TV. · It has four legs."},{"id":"b3","skill":"negativa","title":"Negativa","text":"Use don't (do not) com I, you, we, they e doesn't (does not) com he, she, it. Depois de doesn't, o verbo volta à forma base, sem -s.","example":"I don't like coffee. · She doesn't like coffee (e não \"doesn't likes\")."},{"id":"b4","skill":"interrogativa","title":"Perguntas","text":"Coloque Do ou Does no início. Does é para he, she, it — e o verbo também fica sem -s. Respostas curtas: Yes, I do. / No, she doesn't.","example":"Do you speak English? — Yes, I do. · Does he work here? — No, he doesn't."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"terceira","prompt":"Complete: She ___ guitar.","options":["play","plays","playes","playing"],"answer":1,"hints":["\"She\" é terceira pessoa.","Terceira pessoa ganha uma letra.","Play + s."],"explanation":"She plays."},{"id":"q2","type":"mc","difficulty":1,"skill":"uso","prompt":"O simple present é usado principalmente para:","options":["Ações acontecendo neste exato momento","Rotinas e hábitos","Ações que já terminaram","Planos futuros certos"],"answer":1,"hints":["Pense em \"every day\".","Coisas que se repetem.","Hábitos."],"explanation":"Rotinas, hábitos e verdades gerais."},{"id":"q3","type":"fill","difficulty":1,"skill":"terceira","prompt":"Complete: He ___ (go) to school by bus.","answers":["goes"],"hints":["Terceira pessoa.","Go termina em -o.","-o recebe -es."],"explanation":"He goes."},{"id":"q4","type":"tf","difficulty":1,"skill":"negativa","prompt":"A frase \"She doesn't likes pizza\" está correta.","answer":false,"hints":["Depois de doesn't, o verbo muda?","Ele volta à forma base.","Sem -s."],"explanation":"Falso. O correto é \"She doesn't like pizza\"."},{"id":"q5","type":"match","difficulty":2,"skill":"terceira","prompt":"Ligue cada verbo à forma com he/she/it.","pairs":[["study","studies"],["watch","watches"],["have","has"],["read","reads"]],"hints":["Consoante + y vira -ies.","-ch recebe -es.","Have é irregular."],"explanation":"studies · watches · has · reads."},{"id":"q6","type":"mc","difficulty":2,"skill":"negativa","prompt":"Qual é a negativa de \"They play soccer\"?","options":["They doesn't play soccer.","They don't play soccer.","They don't plays soccer.","They not play soccer."],"answer":1,"hints":["\"They\" usa do ou does?","They → do.","Do + not = don't."],"explanation":"They don't play soccer."},{"id":"q7","type":"mc","difficulty":2,"skill":"interrogativa","prompt":"Complete a pergunta: ___ she speak Spanish?","options":["Do","Does","Is","Are"],"answer":1,"hints":["A pergunta usa um auxiliar.","\"She\" é terceira pessoa.","Do → does."],"explanation":"Does she speak Spanish?"},{"id":"q8","type":"fill","difficulty":2,"skill":"interrogativa","prompt":"Responda curto (afirmativo): \"Do you like music?\" — Yes, I ___.","answers":["do"],"hints":["Repita o auxiliar da pergunta.","A pergunta usa \"Do\".","Yes, I…"],"explanation":"Yes, I do."},{"id":"q9","type":"mc","difficulty":3,"skill":"interrogativa","prompt":"Qual pergunta está correta?","options":["Does he works here?","Do he work here?","Does he work here?","He does work here?"],"answer":2,"hints":["He → does.","Depois de does, o verbo perde o -s.","Does + he + work."],"explanation":"Does he work here?"},{"id":"q10","type":"mc","difficulty":3,"skill":"uso","prompt":"Qual frase expressa uma verdade geral?","options":["I am reading now.","The sun rises in the east.","I watched a movie.","I will travel tomorrow."],"answer":1,"hints":["Procure algo que é sempre verdade.","Não depende do momento.","Um fato da natureza."],"explanation":"\"The sun rises in the east\" — verdade geral no simple present."}],"review":["Rotinas, hábitos e verdades","He/she/it: -s, -es, -ies; have → has","Negativa: don't / doesn't + verbo base","Pergunta: Do/Does + sujeito + verbo base"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Dinâmica","subtopic":"Leis de Newton","relatedQuestions":["O que é inércia?","O que diz a segunda lei de Newton?","O que é ação e reação?","Como calcular força?"],"id":"fis-leis-de-newton","subject":"fisica","title":"Leis de Newton","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["leis de newton","inercia","principio fundamental da dinamica","f = m a","forca","acao e reacao","dinamica","newton"],"summary":"Entenda as três leis que explicam como as forças mudam o movimento dos corpos.","intro":"Por que você vai para a frente quando o ônibus freia? Isaac Newton explicou isso com três leis. Vamos a elas.","skills":{"inercia":"1ª lei — Inércia","fundamental":"2ª lei — F = m · a","acao_reacao":"3ª lei — Ação e reação","unidades":"Unidades de medida"},"blocks":[{"id":"b1","skill":"inercia","title":"1ª lei: Inércia","text":"Um corpo tende a manter seu estado: se está parado, continua parado; se está em movimento retilíneo e uniforme, continua assim — a não ser que uma força resultante atue sobre ele.","example":"Quando o ônibus freia de repente, seu corpo \"quer\" continuar em movimento e é jogado para a frente.","variants":{"simples":"As coisas são \"preguiçosas\" para mudar: o que está parado quer ficar parado, e o que está andando quer continuar andando.","exemplo":"Puxe rápido uma toalha de baixo de um copo: o copo tende a ficar no lugar. É a inércia.","outra":"Para mudar o movimento de algo — acelerar, frear ou fazer uma curva — é preciso uma força. Sem força resultante, nada muda.","detalhado":"Inércia é a tendência de um corpo resistir a mudanças na sua velocidade (vetorial). Força resultante nula implica velocidade constante: repouso ou MRU. Quanto maior a massa, maior a inércia."}},{"id":"b2","skill":"fundamental","title":"2ª lei: F = m · a","text":"A força resultante sobre um corpo é igual à sua massa vezes a aceleração: F = m · a. Com a mesma força, quem tem mais massa acelera menos.","example":"Empurrar um carrinho de supermercado vazio é fácil; cheio, a mesma força gera uma aceleração bem menor.","variants":{"simples":"Força = massa × aceleração. Mais força → mais aceleração. Mais massa → menos aceleração.","exemplo":"Uma força de 20 N empurra uma caixa de 4 kg: a = F ÷ m = 20 ÷ 4 = 5 m/s².","outra":"Pense na fórmula como uma balança: se a massa dobra e a força é a mesma, a aceleração cai pela metade.","detalhado":"A 2ª lei é vetorial: a aceleração tem a mesma direção e sentido da força resultante. Para calcular a aceleração a partir da variação de velocidade: a = Δv ÷ Δt. Ex.: um carro de 1000 kg vai de 0 a 20 m/s em 10 s → a = 2 m/s² → F = 2000 N."}},{"id":"b3","skill":"acao_reacao","title":"3ª lei: Ação e reação","text":"Toda ação tem uma reação de mesma intensidade, mesma direção e sentido oposto. As duas forças atuam em corpos diferentes, por isso não se anulam.","example":"Ao nadar, você empurra a água para trás, e a água empurra você para a frente.","variants":{"simples":"Se você empurra algo, esse algo empurra você de volta com a mesma força.","exemplo":"Um foguete empurra os gases para baixo; os gases empurram o foguete para cima.","outra":"Forças sempre vêm em pares. Se A empurra B, B empurra A. Uma força nunca aparece sozinha.","detalhado":"O par ação-reação atua em corpos diferentes; por isso não faz sentido \"somá-los\" para dizer que se anulam. Já forças que se equilibram (como peso e normal num livro sobre a mesa) atuam no mesmo corpo e não são par ação-reação."}},{"id":"b4","skill":"unidades","title":"Unidades de medida","text":"No Sistema Internacional: força em newton (N), massa em quilograma (kg) e aceleração em metros por segundo ao quadrado (m/s²). 1 N = 1 kg · m/s².","example":"Segurar uma maçã de 100 g exige, aproximadamente, uma força de 1 N.","variants":{"simples":"Força se mede em newton (N). Massa em kg. Aceleração em m/s².","exemplo":"Se a massa está em gramas, converta para kg antes: 500 g = 0,5 kg.","outra":"O \"newton\" é uma homenagem a Isaac Newton. 1 N é a força que acelera 1 kg a 1 m/s².","detalhado":"Não confunda massa (kg, quantidade de matéria) com peso (força, em N). Peso P = m · g, com g ≈ 10 m/s² na Terra: uma pessoa de 50 kg pesa cerca de 500 N."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"inercia","prompt":"Quando o ônibus freia, os passageiros são \"jogados\" para a frente. Isso é explicado pela:","options":["Inércia","Ação e reação","Gravidade","Eletricidade"],"answer":0,"hints":["O corpo \"quer\" continuar como estava.","É a 1ª lei.","Começa com \"I\"."],"explanation":"Pela inércia, o corpo tende a manter o movimento que tinha."},{"id":"q2","type":"mc","difficulty":1,"skill":"fundamental","prompt":"Qual é a fórmula da 2ª lei de Newton?","options":["F = m + a","F = m · a","F = m ÷ a","F = a − m"],"answer":1,"hints":["Relaciona força, massa e aceleração.","Envolve multiplicação.","Massa vezes aceleração."],"explanation":"F = m · a."},{"id":"q3","type":"tf","difficulty":1,"skill":"acao_reacao","prompt":"As forças de ação e reação atuam no mesmo corpo e, por isso, se anulam.","answer":false,"hints":["Pense no nadador e na água.","Uma força está no nadador, outra na água.","São corpos diferentes."],"explanation":"Falso. Ação e reação atuam em corpos diferentes e não se anulam."},{"id":"q4","type":"fill","difficulty":2,"skill":"fundamental","prompt":"Um corpo de 2 kg tem aceleração de 3 m/s². Qual é a força resultante, em newtons?","answers":["6","6 n"],"hints":["Use F = m · a.","m = 2, a = 3.","2 × 3."],"explanation":"F = 2 · 3 = 6 N."},{"id":"q5","type":"mc","difficulty":2,"skill":"fundamental","prompt":"Uma força de 20 N age sobre uma massa de 4 kg. Qual é a aceleração?","options":["80 m/s²","5 m/s²","16 m/s²","24 m/s²"],"answer":1,"hints":["Isole a aceleração: a = F ÷ m.","20 ÷ 4.","Quanto é 20 dividido por 4?"],"explanation":"a = 20 ÷ 4 = 5 m/s²."},{"id":"q6","type":"match","difficulty":2,"skill":"unidades","prompt":"Ligue cada item à descrição.","pairs":[["1ª lei","Inércia"],["2ª lei","F = m · a"],["3ª lei","Ação e reação"],["Newton (N)","Unidade de força"]],"hints":["A 1ª fala de \"preguiça\" para mudar.","A 2ª tem uma fórmula.","A 3ª fala de pares de forças."],"explanation":"1ª → inércia; 2ª → F = m·a; 3ª → ação e reação; N → unidade de força."},{"id":"q7","type":"mc","difficulty":2,"skill":"acao_reacao","prompt":"Ao nadar, a pessoa empurra a água para trás. O que acontece?","options":["A água fica parada","A água empurra a pessoa para a frente","A pessoa afunda","Nada, as forças se anulam"],"answer":1,"hints":["Toda ação tem uma reação.","A reação tem sentido oposto.","Oposto de \"para trás\"?"],"explanation":"Pela 3ª lei, a água empurra a pessoa para a frente."},{"id":"q8","type":"tf","difficulty":2,"skill":"inercia","prompt":"Um corpo em movimento retilíneo uniforme pode ter força resultante nula.","answer":true,"hints":["O que a 1ª lei diz sobre MRU?","Sem força, o movimento se mantém.","MRU = velocidade constante."],"explanation":"Verdadeiro. Com resultante nula, o corpo fica parado ou em MRU."},{"id":"q9","type":"mc","difficulty":3,"skill":"fundamental","prompt":"A mesma força age sobre dois blocos, de 2 kg e de 4 kg. O que se pode dizer das acelerações?","options":["São iguais","A do bloco de 2 kg é o dobro","A do bloco de 4 kg é o dobro","Nenhum acelera"],"answer":1,"hints":["a = F ÷ m.","Mesma força, massas diferentes.","Metade da massa → ?"],"explanation":"Com metade da massa, o bloco de 2 kg acelera o dobro."},{"id":"q10","type":"fill","difficulty":3,"skill":"unidades","prompt":"A unidade de força no Sistema Internacional é o ________.","answers":["newton","n"],"hints":["Homenageia um cientista.","O mesmo das três leis.","Símbolo: N."],"explanation":"O newton (N)."},{"id":"q11","type":"mc","difficulty":3,"skill":"fundamental","prompt":"Um carro de 1000 kg vai de 0 a 20 m/s em 10 s. Qual é a força resultante média?","options":["200 N","2000 N","20000 N","100 N"],"answer":1,"hints":["Calcule a aceleração primeiro.","a = Δv ÷ Δt = 20 ÷ 10.","F = 1000 × 2."],"explanation":"a = 2 m/s² → F = 1000 · 2 = 2000 N."},{"id":"q12","type":"open","difficulty":3,"skill":"inercia","prompt":"Use a 1ª lei de Newton para explicar por que devemos usar o cinto de segurança.","modelAnswer":"Pela inércia, numa freada brusca o corpo tende a continuar em movimento para a frente. O cinto aplica uma força que segura o corpo e impede que ele seja lançado contra o painel ou o para-brisa.","keywords":["inercia","movimento","continuar","frente","freada","forca"],"hints":["O que acontece com o corpo numa freada?","Ele tende a continuar…","Quem \"segura\" o corpo?"],"explanation":"O corpo tende a seguir em frente por inércia; o cinto aplica a força que o segura."}],"review":["1ª lei: inércia — sem força resultante, nada muda","2ª lei: F = m · a","3ª lei: ação e reação em corpos diferentes","Força em newton (N) · massa em kg · aceleração em m/s²"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Cinemática","subtopic":"Velocidade média","relatedQuestions":["Como calcular velocidade média?","Como transformar km/h em m/s?","O que é movimento uniforme?"],"id":"fis-velocidade-media","subject":"fisica","title":"Velocidade média","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["velocidade media","cinematica","movimento uniforme","mru","km/h para m/s","deslocamento e tempo","distancia tempo velocidade"],"summary":"Calcule a velocidade média e converta entre km/h e m/s.","intro":"Se uma viagem de 300 km leva 3 horas, qual foi a velocidade? Vamos descobrir.","skills":{"conceito":"Conceito de velocidade média","calculo":"Calcular v = Δs/Δt","unidades":"Conversão km/h ↔ m/s","mru":"Movimento uniforme"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é velocidade média","text":"Velocidade média é quanto um corpo se desloca, em média, por unidade de tempo. Ela não diz se o carro parou ou acelerou no caminho — só o resultado geral.","example":"Mesmo parando num pedágio, se você percorreu 120 km em 2 h, sua velocidade média foi 60 km/h."},{"id":"b2","skill":"calculo","title":"A fórmula","text":"v = Δs ÷ Δt, em que Δs é o deslocamento (variação da posição) e Δt é o intervalo de tempo. Isolando: Δs = v · Δt e Δt = Δs ÷ v.","example":"300 km em 3 h → v = 300 ÷ 3 = 100 km/h."},{"id":"b3","skill":"unidades","title":"km/h e m/s","text":"No Sistema Internacional, velocidade é medida em m/s. Para passar de km/h para m/s, divida por 3,6; de m/s para km/h, multiplique por 3,6.","example":"72 km/h ÷ 3,6 = 20 m/s · 10 m/s × 3,6 = 36 km/h."},{"id":"b4","skill":"mru","title":"Movimento uniforme","text":"No movimento retilíneo uniforme (MRU), a velocidade é constante: o corpo percorre distâncias iguais em tempos iguais. A posição segue s = s₀ + v·t.","example":"Um carro a 20 m/s constantes, saindo do marco 100 m, estará em s = 100 + 20·5 = 200 m após 5 s."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"calculo","prompt":"Um carro percorre 300 km em 3 horas. Qual foi sua velocidade média?","options":["900 km/h","100 km/h","303 km/h","60 km/h"],"answer":1,"hints":["v = Δs ÷ Δt.","300 ÷ 3.","Resultado em km/h."],"explanation":"v = 300 ÷ 3 = 100 km/h."},{"id":"q2","type":"mc","difficulty":1,"skill":"calculo","prompt":"Qual é a fórmula da velocidade média?","options":["v = Δs × Δt","v = Δs ÷ Δt","v = Δt ÷ Δs","v = Δs + Δt"],"answer":1,"hints":["km/h = quilômetros POR hora.","\"Por\" indica divisão.","Distância dividida por tempo."],"explanation":"v = Δs ÷ Δt."},{"id":"q3","type":"tf","difficulty":1,"skill":"unidades","prompt":"Para converter km/h em m/s, dividimos por 3,6.","answer":true,"hints":["1 km = 1000 m; 1 h = 3600 s.","1000 ÷ 3600 = 1/3,6.","Divide."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":2,"skill":"unidades","prompt":"Converta 72 km/h para m/s.","answers":["20","20 m/s"],"hints":["Divida por 3,6.","72 ÷ 3,6.","Dá um número redondo."],"explanation":"72 ÷ 3,6 = 20 m/s."},{"id":"q5","type":"fill","difficulty":2,"skill":"calculo","prompt":"Um ciclista anda a 15 km/h durante 2 horas. Quantos km ele percorre?","answers":["30","30 km"],"hints":["Δs = v × Δt.","15 × 2.","Resultado em km."],"explanation":"Δs = 15 × 2 = 30 km."},{"id":"q6","type":"match","difficulty":2,"skill":"unidades","prompt":"Ligue cada velocidade à equivalente.","pairs":[["36 km/h","10 m/s"],["72 km/h","20 m/s"],["108 km/h","30 m/s"],["18 km/h","5 m/s"]],"hints":["Divida cada valor por 3,6.","36 ÷ 3,6 = 10.","18 ÷ 3,6 = 5."],"explanation":"36→10 · 72→20 · 108→30 · 18→5."},{"id":"q7","type":"mc","difficulty":2,"skill":"conceito","prompt":"Numa viagem, um carro parou 30 minutos no posto. A velocidade média considera esse tempo parado?","options":["Não, só o tempo em movimento","Sim, conta o tempo total da viagem","Só se a parada for maior que 1 h","Depende do motorista"],"answer":1,"hints":["Δt é o intervalo total.","Do início ao fim.","Inclui as paradas."],"explanation":"Sim: Δt é o tempo total."},{"id":"q8","type":"mc","difficulty":3,"skill":"calculo","prompt":"Quanto tempo leva para percorrer 240 km a 80 km/h?","options":["2 h","3 h","4 h","320 h"],"answer":1,"hints":["Δt = Δs ÷ v.","240 ÷ 80.","Resultado em horas."],"explanation":"Δt = 240 ÷ 80 = 3 h."},{"id":"q9","type":"tf","difficulty":3,"skill":"mru","prompt":"No MRU, o corpo percorre distâncias iguais em intervalos de tempo iguais.","answer":true,"hints":["Uniforme = constante.","A velocidade não muda.","Mesma distância a cada segundo."],"explanation":"Verdadeiro."},{"id":"q10","type":"fill","difficulty":3,"skill":"mru","prompt":"Um corpo em MRU parte de s₀ = 100 m com v = 20 m/s. Qual sua posição, em metros, após 5 s?","answers":["200","200 m"],"hints":["s = s₀ + v·t.","100 + 20·5.","100 + 100."],"explanation":"s = 100 + 100 = 200 m."}],"review":["v = Δs ÷ Δt (tempo total)","Δs = v·Δt · Δt = Δs ÷ v","km/h ÷ 3,6 = m/s","MRU: velocidade constante, s = s₀ + v·t"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Estrutura da matéria","subtopic":"Átomo e tabela periódica","relatedQuestions":["Do que o átomo é formado?","O que é número atômico?","Como a tabela periódica é organizada?"],"id":"qui-atomo-tabela","subject":"quimica","title":"Átomo e tabela periódica","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["atomo","tabela periodica","protons","eletrons","neutrons","numero atomico","numero de massa","elementos quimicos","familias","periodos","gases nobres"],"summary":"Conheça as partes do átomo, número atômico, número de massa e como a tabela periódica é organizada.","intro":"Tudo o que existe é feito de átomos. E a tabela periódica é o \"mapa\" que organiza todos os tipos de átomo.","skills":{"estrutura":"Estrutura do átomo","numeros":"Número atômico e de massa","tabela":"Organização da tabela","classificacao":"Metais, ametais e gases nobres"},"blocks":[{"id":"b1","skill":"estrutura","title":"As partes do átomo","text":"O átomo tem um núcleo, com prótons (carga positiva) e nêutrons (sem carga), e uma região ao redor chamada eletrosfera, onde ficam os elétrons (carga negativa).","example":"Quase toda a massa do átomo está no núcleo, mesmo ele sendo muito pequeno em comparação ao átomo inteiro.","variants":{"simples":"No centro (núcleo): prótons (+) e nêutrons (sem carga). Em volta: elétrons (−).","exemplo":"Se o núcleo fosse do tamanho de uma formiga no meio de um estádio, o átomo inteiro seria o estádio — quase tudo é espaço vazio.","outra":"Um jeito de lembrar: Próton = Positivo. Nêutron = Neutro. Elétron = o que sobra, negativo.","detalhado":"Prótons e nêutrons têm massas parecidas; o elétron tem massa cerca de 1836 vezes menor que a do próton. Por isso a massa se concentra no núcleo. O modelo atual descreve os elétrons em orbitais, regiões de maior probabilidade de encontrá-los."}},{"id":"b2","skill":"numeros","title":"Número atômico (Z) e de massa (A)","text":"O número atômico (Z) é a quantidade de prótons e identifica o elemento. O número de massa (A) é a soma de prótons e nêutrons: A = Z + N. Num átomo neutro, o número de elétrons é igual ao de prótons.","example":"O sódio tem Z = 11 e, em geral, 12 nêutrons: A = 11 + 12 = 23.","variants":{"simples":"Z = número de prótons. A = prótons + nêutrons. Átomo neutro: elétrons = prótons.","exemplo":"O cloro tem A = 35 e Z = 17. Nêutrons: N = 35 − 17 = 18.","outra":"Z é como o \"RG\" do elemento: todo átomo com 6 prótons é carbono, sempre. Já A pode mudar, porque o número de nêutrons pode variar.","detalhado":"Átomos de um mesmo elemento com números de massa diferentes são isótopos (ex.: carbono-12 e carbono-14). Quando um átomo ganha ou perde elétrons, vira um íon: cátion (+, perdeu elétrons) ou ânion (−, ganhou elétrons)."}},{"id":"b3","skill":"tabela","title":"Como a tabela é organizada","text":"Os elementos estão em ordem crescente de número atômico. As linhas horizontais são os períodos (7 no total) e as colunas verticais são os grupos ou famílias (18 no total). Elementos da mesma família têm propriedades químicas parecidas.","example":"Lítio, sódio e potássio estão na mesma família (grupo 1) e reagem de forma parecida com a água.","variants":{"simples":"Linha deitada = período. Coluna em pé = família. Quem está na mesma coluna se parece.","exemplo":"Hélio, neônio e argônio estão na mesma coluna (grupo 18): todos são gases que quase não reagem.","outra":"Pense num prédio: cada andar é um período, e cada coluna de apartamentos \"empilhados\" é uma família com características em comum.","detalhado":"O período indica o número de camadas eletrônicas; nos elementos representativos, o grupo se relaciona com o número de elétrons na camada de valência — por isso a semelhança química dentro da família."}},{"id":"b4","skill":"classificacao","title":"Metais, ametais e gases nobres","text":"A maioria dos elementos é metal (bons condutores de calor e eletricidade, brilhantes). Os ametais ficam à direita da tabela. Os gases nobres (grupo 18), como hélio e neônio, são muito estáveis e quase não reagem.","example":"Ferro, cobre e alumínio são metais. Oxigênio e carbono são ametais. Hélio é gás nobre.","variants":{"simples":"Metais: brilham e conduzem eletricidade (ferro, cobre). Ametais: do lado direito (oxigênio). Gases nobres: última coluna, quase não reagem.","exemplo":"O fio de cobre conduz eletricidade porque o cobre é metal. O hélio enche balões e não pega fogo porque é gás nobre.","outra":"Olhe a tabela como um mapa: a maior parte do território (esquerda e centro) é dos metais; o cantinho da direita é dos ametais; a última coluna é dos gases nobres.","detalhado":"O hidrogênio fica no grupo 1, mas não é metal. Existem ainda os semimetais (ou metaloides), como silício e germânio, com propriedades intermediárias. A estabilidade dos gases nobres está ligada à camada de valência completa."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"estrutura","prompt":"Qual partícula do átomo tem carga negativa?","options":["Próton","Nêutron","Elétron","Núcleo"],"answer":2,"hints":["Próton = positivo.","Nêutron = neutro.","Sobrou qual?"],"explanation":"O elétron tem carga negativa."},{"id":"q2","type":"mc","difficulty":1,"skill":"numeros","prompt":"O número atômico (Z) indica a quantidade de:","options":["Nêutrons","Prótons","Elétrons + nêutrons","Camadas"],"answer":1,"hints":["É o \"RG\" do elemento.","Fica no núcleo e tem carga positiva.","Pró…"],"explanation":"Z é o número de prótons."},{"id":"q3","type":"tf","difficulty":1,"skill":"tabela","prompt":"As linhas horizontais da tabela periódica se chamam períodos.","answer":true,"hints":["Linha deitada ou coluna em pé?","Colunas são famílias.","Então as linhas são…"],"explanation":"Verdadeiro. São 7 períodos."},{"id":"q4","type":"fill","difficulty":2,"skill":"numeros","prompt":"Um átomo tem Z = 11 e 12 nêutrons. Qual é o número de massa (A)?","answers":["23"],"hints":["A = Z + N.","Z = 11, N = 12.","11 + 12."],"explanation":"A = 11 + 12 = 23 (é o sódio)."},{"id":"q5","type":"mc","difficulty":2,"skill":"tabela","prompt":"As colunas verticais da tabela periódica são chamadas de:","options":["Períodos","Grupos ou famílias","Camadas","Séries"],"answer":1,"hints":["As linhas são períodos.","Quem está na mesma coluna \"se parece\".","Como parentes."],"explanation":"Grupos ou famílias (são 18)."},{"id":"q6","type":"match","difficulty":2,"skill":"estrutura","prompt":"Ligue cada parte à sua característica.","pairs":[["Próton","Carga positiva, no núcleo"],["Nêutron","Sem carga, no núcleo"],["Elétron","Carga negativa, na eletrosfera"],["Núcleo","Concentra quase toda a massa"]],"hints":["Próton = Positivo.","Nêutron = Neutro.","Os elétrons ficam em volta."],"explanation":"Próton (+, núcleo), nêutron (0, núcleo), elétron (−, eletrosfera), núcleo (massa)."},{"id":"q7","type":"mc","difficulty":2,"skill":"classificacao","prompt":"Qual destes elementos é um gás nobre?","options":["Oxigênio","Sódio","Hélio","Ferro"],"answer":2,"hints":["Gases nobres quase não reagem.","Ficam na última coluna.","É usado para encher balões."],"explanation":"O hélio (He) é um gás nobre."},{"id":"q8","type":"tf","difficulty":2,"skill":"numeros","prompt":"Em um átomo neutro, o número de elétrons é igual ao número de prótons.","answer":true,"hints":["Neutro = cargas se equilibram.","Prótons são +, elétrons são −.","Quantidades iguais se anulam."],"explanation":"Verdadeiro. As cargas positivas e negativas se equilibram."},{"id":"q9","type":"fill","difficulty":3,"skill":"numeros","prompt":"Um átomo tem A = 35 e Z = 17. Quantos nêutrons ele tem?","answers":["18"],"hints":["A = Z + N.","Isole o N: N = A − Z.","35 − 17."],"explanation":"N = 35 − 17 = 18 (é o cloro-35)."},{"id":"q10","type":"mc","difficulty":3,"skill":"tabela","prompt":"Os elementos da tabela periódica atual estão organizados em ordem crescente de:","options":["Massa","Número atômico","Nêutrons","Descoberta"],"answer":1,"hints":["É o \"RG\" do elemento.","É o número de prótons.","É o Z."],"explanation":"Em ordem crescente de número atômico (Z)."},{"id":"q11","type":"mc","difficulty":3,"skill":"tabela","prompt":"Por que os elementos de uma mesma família têm propriedades químicas parecidas?","options":["Porque têm a mesma massa","Porque têm o mesmo número de elétrons na camada de valência","Porque foram descobertos juntos","Porque têm o mesmo número de nêutrons"],"answer":1,"hints":["Reações químicas envolvem elétrons.","Principalmente os da última camada.","Essa camada se chama valência."],"explanation":"Mesma família → mesmo número de elétrons de valência → comportamento químico parecido."},{"id":"q12","type":"tf","difficulty":3,"skill":"classificacao","prompt":"A maioria dos elementos da tabela periódica é metal.","answer":true,"hints":["Olhe para a esquerda e o centro da tabela.","Ferro, cobre, ouro, alumínio…","Os ametais ficam num canto."],"explanation":"Verdadeiro. Os metais são a grande maioria."}],"review":["Núcleo: prótons (+) e nêutrons (0) · Eletrosfera: elétrons (−)","Z = prótons · A = Z + N","Períodos = linhas (7) · Famílias = colunas (18)","Maioria metais · Gases nobres no grupo 18"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Estrutura da matéria","subtopic":"Ligações químicas","relatedQuestions":["O que é ligação iônica?","O que é ligação covalente?","O que é a regra do octeto?","Por que os átomos se ligam?"],"id":"qui-ligacoes-quimicas","subject":"quimica","title":"Ligações químicas","levels":["medio"],"grade":"1ª série","aliases":["ligacoes quimicas","ligacao ionica","ligacao covalente","ligacao metalica","regra do octeto","ions","compartilhamento de eletrons"],"summary":"Entenda por que os átomos se ligam e diferencie as ligações iônica, covalente e metálica.","intro":"Por que o sal é sólido e a água é líquida? A resposta está no jeito como os átomos se ligam.","skills":{"octeto":"Regra do octeto","ionica":"Ligação iônica","covalente":"Ligação covalente","metalica":"Ligação metálica"},"blocks":[{"id":"b1","skill":"octeto","title":"Por que os átomos se ligam","text":"Os átomos tendem a ficar estáveis com 8 elétrons na camada de valência (ou 2, no caso do hidrogênio e do hélio), como os gases nobres. Para isso, eles ganham, perdem ou compartilham elétrons: é a regra do octeto.","example":"O sódio tem 1 elétron de valência e tende a perdê-lo; o cloro tem 7 e tende a ganhar 1."},{"id":"b2","skill":"ionica","title":"Ligação iônica","text":"Ocorre entre um metal e um ametal: o metal perde elétrons (vira cátion, +) e o ametal ganha (vira ânion, −). Os íons de cargas opostas se atraem. Compostos iônicos costumam ser sólidos e conduzir eletricidade quando dissolvidos em água.","example":"NaCl (sal de cozinha): Na perde 1 elétron → Na⁺; Cl ganha → Cl⁻."},{"id":"b3","skill":"covalente","title":"Ligação covalente","text":"Ocorre entre ametais (e hidrogênio), que compartilham pares de elétrons. Forma moléculas. Pode ser simples, dupla ou tripla, conforme o número de pares compartilhados.","example":"H₂O: o oxigênio compartilha um par de elétrons com cada hidrogênio. O₂ tem ligação dupla."},{"id":"b4","skill":"metalica","title":"Ligação metálica","text":"Ocorre entre átomos de metais. Os elétrons de valência ficam livres, formando um \"mar de elétrons\" ao redor dos cátions. Isso explica o brilho e a boa condução de calor e eletricidade dos metais.","example":"Fios de cobre conduzem eletricidade graças à ligação metálica."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"octeto","prompt":"Segundo a regra do octeto, os átomos tendem a ficar estáveis com quantos elétrons na camada de valência?","options":["2","4","8","18"],"answer":2,"hints":["\"Octeto\" lembra qual número?","Octógono tem 8 lados.","Oito."],"explanation":"8 elétrons (2 para H e He)."},{"id":"q2","type":"mc","difficulty":1,"skill":"ionica","prompt":"A ligação iônica ocorre geralmente entre:","options":["Dois metais","Metal e ametal","Dois gases nobres","Dois ametais"],"answer":1,"hints":["Um átomo perde e outro ganha elétrons.","Metais tendem a perder.","Ametais tendem a ganhar."],"explanation":"Entre metal e ametal."},{"id":"q3","type":"tf","difficulty":1,"skill":"covalente","prompt":"Na ligação covalente, os átomos compartilham elétrons.","answer":true,"hints":["Co-valente: valência em conjunto.","Ninguém perde nem ganha.","Dividem."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"metalica","prompt":"Ligue cada substância ao tipo de ligação.","pairs":[["NaCl (sal)","Iônica"],["H₂O (água)","Covalente"],["Fio de cobre","Metálica"]],"hints":["Na é metal e Cl é ametal.","H e O são ametais.","Cobre é metal puro."],"explanation":"NaCl: iônica · H₂O: covalente · Cu: metálica."},{"id":"q5","type":"fill","difficulty":2,"skill":"ionica","prompt":"Um átomo que perde elétrons fica com carga positiva e é chamado de ________.","answers":["cation","cátion"],"hints":["Íon positivo.","O oposto de ânion.","Cát…"],"explanation":"Cátion."},{"id":"q6","type":"mc","difficulty":2,"skill":"octeto","prompt":"O sódio (Na) tem 1 elétron na camada de valência. Para ficar estável, ele tende a:","options":["Ganhar 7 elétrons","Perder 1 elétron","Compartilhar 4 elétrons","Não se ligar"],"answer":1,"hints":["O que é mais fácil: perder 1 ou ganhar 7?","Metais tendem a perder.","Perder 1."],"explanation":"Perde 1 elétron e vira Na⁺."},{"id":"q7","type":"mc","difficulty":2,"skill":"metalica","prompt":"O que explica a boa condução elétrica dos metais?","options":["Elétrons livres (\"mar de elétrons\")","Compartilhamento de pares fixos","Ausência de elétrons","Presença de ânions"],"answer":0,"hints":["Corrente elétrica é movimento de cargas.","Os elétrons precisam se mover.","Nos metais eles ficam livres."],"explanation":"O \"mar de elétrons\" livres."},{"id":"q8","type":"tf","difficulty":3,"skill":"ionica","prompt":"O sal de cozinha dissolvido em água conduz eletricidade.","answer":true,"hints":["Na água, os íons se separam.","Íons têm carga.","Cargas livres conduzem."],"explanation":"Verdadeiro: os íons livres conduzem."},{"id":"q9","type":"mc","difficulty":3,"skill":"covalente","prompt":"Na molécula de O₂, os dois oxigênios compartilham:","options":["1 par de elétrons (ligação simples)","2 pares de elétrons (ligação dupla)","3 pares de elétrons (ligação tripla)","Nenhum elétron"],"answer":1,"hints":["O oxigênio tem 6 elétrons de valência.","Faltam 2 para o octeto.","Cada um \"divide\" 2 elétrons."],"explanation":"Ligação dupla: 2 pares compartilhados."},{"id":"q10","type":"open","difficulty":3,"skill":"octeto","prompt":"Explique a diferença entre ligação iônica e covalente.","modelAnswer":"Na ligação iônica há transferência de elétrons: um átomo (geralmente metal) perde e outro (ametal) ganha, formando íons que se atraem. Na covalente, átomos de ametais compartilham pares de elétrons, formando moléculas.","keywords":["transferencia","perde","ganha","ions","compartilh","metal","ametal","molecula"],"hints":["Em uma, os elétrons mudam de dono.","Na outra, são divididos.","Fale de íons e de compartilhamento."],"explanation":"Iônica: transferência e íons · covalente: compartilhamento."}],"review":["Regra do octeto: 8 elétrons de valência","Iônica: metal + ametal, transferência, íons","Covalente: ametais, compartilhamento","Metálica: mar de elétrons, conduz"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — Ligações Químicas","url":"https://www.todamateria.com.br/ligacoes-quimicas/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Citologia","subtopic":"Célula e organelas","relatedQuestions":["O que é célula?","Para que serve a mitocôndria?","Qual a diferença entre célula animal e vegetal?"],"id":"bio-celula","subject":"biologia","title":"Célula","levels":["fund2","medio"],"grade":"6º ano e 1ª série","aliases":["celula","celulas","organelas","mitocondria","citologia","celula animal","celula vegetal","procarionte","eucarionte"],"summary":"A célula é a unidade básica da vida. Conheça suas partes e organelas.","intro":"Todo ser vivo é formado por células — de uma bactéria a uma baleia. Vamos olhar lá dentro.","skills":{"conceito":"Célula como unidade da vida","tipos":"Procariontes e eucariontes","estruturas":"Membrana, citoplasma e núcleo","organelas":"Organelas e funções","animal_vegetal":"Célula animal × vegetal"},"blocks":[{"id":"b1","skill":"conceito","title":"A unidade da vida","text":"A célula é a menor unidade viva. Alguns seres têm uma só célula (unicelulares, como bactérias); outros têm trilhões (pluricelulares, como nós).","example":"O corpo humano tem cerca de 30 trilhões de células.","variants":{"simples":"Assim como uma casa é feita de tijolos, os seres vivos são feitos de células.","exemplo":"Uma bactéria é uma célula sozinha fazendo tudo. Você é um \"time\" enorme de células trabalhando juntas.","outra":"Se você dividir um ser vivo em partes cada vez menores, a menor parte que ainda está viva é a célula.","detalhado":"A teoria celular afirma que todos os seres vivos são formados por células, que a célula é a unidade estrutural e funcional da vida, e que toda célula surge de outra célula preexistente. Vírus não têm células."}},{"id":"b2","skill":"estruturas","title":"As três partes básicas","text":"Toda célula tem membrana plasmática (que envolve e controla o que entra e sai), citoplasma (o interior, onde ficam as organelas) e material genético (DNA). Nas células eucariontes, o DNA fica dentro do núcleo.","example":"A membrana funciona como o portão de um condomínio: decide quem entra e quem sai.","variants":{"simples":"Membrana = a \"pele\" da célula. Citoplasma = o recheio. Núcleo = o \"chefe\", que guarda as instruções.","exemplo":"Como um ovo: a casca lembra a membrana, a clara lembra o citoplasma e a gema lembra o núcleo. (É só uma comparação!)","outra":"Pense numa fábrica: os muros (membrana), o galpão com as máquinas (citoplasma) e a sala com os projetos (núcleo com o DNA).","detalhado":"A membrana plasmática é formada por uma bicamada de fosfolipídios com proteínas e tem permeabilidade seletiva. O núcleo é delimitado pela carioteca, e o citoplasma contém o citosol e as organelas."}},{"id":"b3","skill":"tipos","title":"Procariontes e eucariontes","text":"Células procariontes não têm núcleo organizado: o DNA fica solto no citoplasma. É o caso das bactérias. Células eucariontes têm núcleo delimitado por membrana e várias organelas. É o caso de animais, plantas e fungos.","example":"\"Pro\" lembra \"primeiro\": as procariontes são células mais simples.","variants":{"simples":"Procarionte: sem núcleo (bactérias). Eucarionte: com núcleo (animais, plantas, fungos).","exemplo":"A bactéria que estraga o leite é procarionte. As células da sua pele são eucariontes.","outra":"É como uma casa sem quartos (tudo junto num cômodo só) e uma casa com quartos separados. A eucarionte é a com quartos.","detalhado":"Procariontes têm ribossomos, mas não possuem organelas membranosas como mitocôndrias. O DNA fica numa região chamada nucleoide. Eucariontes surgiram depois e têm compartimentos internos especializados."}},{"id":"b4","skill":"organelas","title":"Organelas e suas funções","text":"Mitocôndria: libera energia (respiração celular). Ribossomo: produz proteínas. Cloroplasto: faz fotossíntese (só em plantas e algas). Núcleo: guarda o DNA e controla a célula.","example":"Células dos músculos têm muitas mitocôndrias porque precisam de muita energia.","variants":{"simples":"Mitocôndria = usina de energia. Ribossomo = fábrica de proteínas. Cloroplasto = painel solar da planta.","exemplo":"Quando você corre, as mitocôndrias dos músculos trabalham muito para liberar energia a partir da glicose.","outra":"Cada organela é como um setor de uma empresa: um produz (ribossomo), outro gera energia (mitocôndria), outro guarda os documentos (núcleo).","detalhado":"Na mitocôndria ocorre a respiração celular aeróbica, que produz ATP. Ribossomos podem estar livres ou no retículo endoplasmático rugoso. O complexo golgiense modifica e empacota substâncias, e os lisossomos fazem a digestão intracelular."}},{"id":"b5","skill":"animal_vegetal","title":"Célula animal × vegetal","text":"A célula vegetal tem parede celular (de celulose), cloroplastos e um grande vacúolo. A célula animal não tem essas estruturas. As duas têm membrana, citoplasma, núcleo e mitocôndrias.","example":"A parede celular é o que deixa o talo de uma planta mais firme.","variants":{"simples":"Planta tem três coisas a mais: parede, cloroplasto e um vacúolo grande. O resto é parecido.","exemplo":"Uma folha de alface é crocante por causa da parede celular e da água no vacúolo.","outra":"A célula vegetal é como a animal usando uma \"armadura\" (parede celular) e \"painéis solares\" (cloroplastos).","detalhado":"A parede celular fica por fora da membrana plasmática e dá sustentação. Células animais têm centríolos e lisossomos mais evidentes. As células vegetais também têm mitocôndrias, pois precisam liberar energia pela respiração."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Qual é a unidade básica da vida?","options":["O átomo","A célula","O órgão","O tecido"],"answer":1,"hints":["É a menor parte que ainda está viva.","Os seres vivos são feitos delas.","Como tijolos de uma casa."],"explanation":"A célula é a menor unidade viva."},{"id":"q2","type":"mc","difficulty":1,"skill":"organelas","prompt":"Qual organela libera energia para a célula?","options":["Ribossomo","Mitocôndria","Núcleo","Membrana"],"answer":1,"hints":["É chamada de \"usina de energia\".","Nela acontece a respiração celular.","Começa com M e não é membrana."],"explanation":"A mitocôndria realiza a respiração celular e libera energia."},{"id":"q3","type":"tf","difficulty":1,"skill":"tipos","prompt":"As bactérias são seres procariontes.","answer":true,"hints":["Bactérias têm núcleo organizado?","Não têm.","Sem núcleo = procarionte."],"explanation":"Verdadeiro. As bactérias não têm núcleo organizado."},{"id":"q4","type":"fill","difficulty":2,"skill":"estruturas","prompt":"A estrutura que envolve a célula e controla o que entra e sai é a membrana ________.","answers":["plasmatica","plasmática"],"hints":["É como o portão de um condomínio.","Toda célula tem uma.","Membrana plas…"],"explanation":"A membrana plasmática tem permeabilidade seletiva."},{"id":"q5","type":"mc","difficulty":2,"skill":"tipos","prompt":"O que diferencia uma célula procarionte de uma eucarionte?","options":["A procarionte não tem núcleo organizado","A procarionte não tem membrana","A eucarionte não tem DNA","A eucarionte não tem citoplasma"],"answer":0,"hints":["As duas têm membrana, citoplasma e DNA.","A diferença está em onde o DNA fica.","Na procarionte o DNA fica solto."],"explanation":"A procarionte não tem núcleo delimitado por membrana; o DNA fica no citoplasma."},{"id":"q6","type":"match","difficulty":2,"skill":"organelas","prompt":"Ligue cada organela à sua função.","pairs":[["Mitocôndria","Respiração celular"],["Ribossomo","Produção de proteínas"],["Cloroplasto","Fotossíntese"],["Núcleo","Guarda o DNA"]],"hints":["Mitocôndria = energia.","Cloroplasto tem clorofila.","O \"chefe\" guarda as instruções."],"explanation":"Mitocôndria → respiração; Ribossomo → proteínas; Cloroplasto → fotossíntese; Núcleo → DNA."},{"id":"q7","type":"mc","difficulty":2,"skill":"animal_vegetal","prompt":"Qual destas estruturas existe na célula vegetal, mas não na animal?","options":["Membrana plasmática","Parede celular","Ribossomo","Mitocôndria"],"answer":1,"hints":["A planta tem uma \"armadura\".","Ela é feita de celulose.","Fica por fora da membrana."],"explanation":"A parede celular de celulose é exclusiva da célula vegetal (entre as opções)."},{"id":"q8","type":"tf","difficulty":2,"skill":"animal_vegetal","prompt":"As células animais possuem cloroplastos.","answer":false,"hints":["Cloroplasto serve para quê?","Animais fazem fotossíntese?","Não fazem."],"explanation":"Falso. Cloroplastos existem em plantas e algas."},{"id":"q9","type":"fill","difficulty":3,"skill":"organelas","prompt":"A organela responsável pela produção de proteínas é o ________.","answers":["ribossomo","ribossomos"],"hints":["Está presente até nas bactérias.","É a \"fábrica de proteínas\".","Ribo…"],"explanation":"O ribossomo produz proteínas."},{"id":"q10","type":"tf","difficulty":3,"skill":"animal_vegetal","prompt":"As células vegetais também possuem mitocôndrias.","answer":true,"hints":["A planta precisa liberar energia?","Plantas também respiram.","A respiração celular ocorre na mitocôndria."],"explanation":"Verdadeiro. Plantas fazem fotossíntese e também respiração celular."},{"id":"q11","type":"mc","difficulty":3,"skill":"estruturas","prompt":"Nas células eucariontes, onde fica a maior parte do DNA?","options":["Na membrana","No núcleo","Na parede celular","No vacúolo"],"answer":1,"hints":["Eucarionte = núcleo verdadeiro.","O núcleo é o \"chefe\".","Ele guarda as instruções."],"explanation":"No núcleo, delimitado pela carioteca."},{"id":"q12","type":"open","difficulty":3,"skill":"organelas","prompt":"Por que as células dos músculos têm muitas mitocôndrias?","modelAnswer":"Porque os músculos precisam de muita energia para se movimentar, e as mitocôndrias são as organelas que liberam energia pela respiração celular.","keywords":["energia","respiracao","movimento","contracao","esforco"],"hints":["O que o músculo faz o tempo todo?","Movimento gasta o quê?","Quem libera isso na célula?"],"explanation":"Músculos gastam muita energia, e a mitocôndria é quem a libera."}],"review":["Célula = unidade da vida","Membrana, citoplasma e DNA (no núcleo nas eucariontes)","Procarionte (sem núcleo) × eucarionte (com núcleo)","Mitocôndria = energia · Ribossomo = proteínas · Cloroplasto = fotossíntese","Vegetal tem parede celular, cloroplasto e vacúolo grande"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Ecologia","subtopic":"Cadeias e teias alimentares","relatedQuestions":["O que é cadeia alimentar?","O que são produtores e consumidores?","Quem são os decompositores?","Quem come quem na natureza?"],"id":"bio-cadeias-alimentares","subject":"biologia","title":"Cadeias alimentares","levels":["fund1","fund2","medio"],"grade":"5º ao 7º ano","aliases":["cadeia alimentar","teia alimentar","ecologia","produtores consumidores decompositores","niveis troficos","quem come quem"],"summary":"Entenda como a energia passa dos produtores aos consumidores e o papel dos decompositores.","intro":"Na natureza, todo mundo depende de alguém para se alimentar. Vamos montar essa corrente!","skills":{"produtores":"Produtores","consumidores":"Consumidores","decompositores":"Decompositores","teias":"Teias alimentares e energia"},"blocks":[{"id":"b1","skill":"produtores","title":"Os produtores","text":"Produtores são seres que fabricam o próprio alimento, como as plantas e as algas, usando a luz na fotossíntese. Eles são sempre o começo da cadeia alimentar.","example":"O capim é produtor: faz o próprio alimento com a luz do Sol.","variants":{"simples":"As plantas fazem a própria comida. Por isso ficam no começo da corrente."}},{"id":"b2","skill":"consumidores","title":"Os consumidores","text":"Consumidores se alimentam de outros seres. Os primários comem produtores (herbívoros). Os secundários comem os primários, e assim por diante.","example":"Capim → gafanhoto (primário) → sapo (secundário) → cobra (terciário).","variants":{"simples":"Quem come planta é consumidor primário. Quem come esse bicho é o secundário."}},{"id":"b3","skill":"decompositores","title":"Os decompositores","text":"Fungos e bactérias decompõem restos de seres mortos, fezes e folhas caídas, devolvendo nutrientes ao solo. Eles atuam em todos os níveis da cadeia.","example":"Uma fruta esquecida fica mofada: são fungos decompondo.","variants":{"simples":"Fungos e bactérias \"reciclam\" o que morre e devolvem alimento para a terra."}},{"id":"b4","skill":"teias","title":"Teias e energia","text":"Na natureza as cadeias se cruzam formando teias alimentares, porque um animal come vários tipos de alimento. A cada nível, parte da energia é gasta, por isso há menos energia disponível no topo.","example":"O sapo come gafanhotos e moscas; e pode ser comido por cobras ou garças."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"produtores","prompt":"Qual destes é um produtor?","options":["Gafanhoto","Capim","Cobra","Fungo"],"answer":1,"hints":["Produtor faz o próprio alimento.","Usa a luz do Sol.","É uma planta."],"explanation":"O capim é uma planta, produtor."},{"id":"q2","type":"tf","difficulty":1,"skill":"produtores","prompt":"Toda cadeia alimentar começa com um produtor.","answer":true,"hints":["De onde vem a primeira energia?","Da luz captada pelas plantas.","Plantas são produtoras."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"decompositores","prompt":"Quem são os decompositores?","options":["Leões e onças","Fungos e bactérias","Plantas","Pássaros"],"answer":1,"hints":["Eles fazem o mofo.","São muito pequenos.","Reciclam restos de seres vivos."],"explanation":"Fungos e bactérias."},{"id":"q4","type":"fill","difficulty":2,"skill":"consumidores","prompt":"Na cadeia capim → gafanhoto → sapo, o gafanhoto é consumidor ________.","answers":["primario","primário"],"hints":["Ele come o produtor.","É o primeiro a consumir.","Primeiro = …"],"explanation":"Consumidor primário."},{"id":"q5","type":"match","difficulty":2,"skill":"consumidores","prompt":"Na cadeia capim → gafanhoto → sapo → cobra, ligue cada ser ao seu papel.","pairs":[["Capim","Produtor"],["Gafanhoto","Consumidor primário"],["Sapo","Consumidor secundário"],["Cobra","Consumidor terciário"]],"hints":["Comece pelo produtor.","Quem come o capim?","Depois conte os níveis."],"explanation":"Produtor → primário → secundário → terciário."},{"id":"q6","type":"tf","difficulty":2,"skill":"decompositores","prompt":"Os decompositores devolvem nutrientes ao solo.","answer":true,"hints":["O que acontece com uma folha caída?","Ela se decompõe.","Vira adubo."],"explanation":"Verdadeiro."},{"id":"q7","type":"mc","difficulty":2,"skill":"consumidores","prompt":"Um animal que se alimenta apenas de plantas é chamado de:","options":["Carnívoro","Herbívoro","Decompositor","Produtor"],"answer":1,"hints":["\"Herba\" lembra erva.","Come plantas.","Herbí…"],"explanation":"Herbívoro."},{"id":"q8","type":"mc","difficulty":3,"skill":"teias","prompt":"Por que há menos energia disponível no topo da cadeia alimentar?","options":["Porque os predadores comem pouco","Porque em cada nível parte da energia é gasta pelos seres","Porque o Sol não chega lá","Porque os decompositores roubam energia"],"answer":1,"hints":["Todo ser vivo gasta energia para viver.","Respirar, se mover…","Nem tudo passa adiante."],"explanation":"Cada nível usa parte da energia; só uma fração passa ao seguinte."},{"id":"q9","type":"tf","difficulty":3,"skill":"teias","prompt":"Uma teia alimentar é formada por várias cadeias alimentares interligadas.","answer":true,"hints":["Um animal come um só tipo de alimento?","Não, come vários.","As cadeias se cruzam."],"explanation":"Verdadeiro."},{"id":"q10","type":"open","difficulty":3,"skill":"teias","prompt":"O que poderia acontecer com uma cadeia alimentar se todos os sapos desaparecessem?","modelAnswer":"Os gafanhotos, que eram comidos pelos sapos, poderiam aumentar muito e comer mais capim. Já as cobras, que comiam sapos, teriam menos alimento e poderiam diminuir. O equilíbrio seria afetado.","keywords":["aumentar","diminuir","gafanhoto","cobra","equilibrio","alimento"],"hints":["Pense em quem os sapos comiam.","E em quem comia os sapos.","Um aumenta, outro diminui."],"explanation":"Presas aumentam, predadores diminuem: desequilíbrio."}],"review":["Produtores fazem o próprio alimento","Consumidores: primário, secundário, terciário","Decompositores reciclam nutrientes","Teias = cadeias interligadas; energia diminui a cada nível"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Genética","subtopic":"1ª Lei de Mendel","relatedQuestions":["O que é gene dominante e recessivo?","O que diz a primeira lei de Mendel?","Como fazer o quadro de Punnett?","O que é genótipo e fenótipo?"],"id":"bio-primeira-lei-mendel","subject":"biologia","title":"Genética: 1ª Lei de Mendel","levels":["medio"],"grade":"3ª série","aliases":["genetica","mendel","primeira lei de mendel","lei da segregacao","dominante e recessivo","heranca genetica","alelos","genotipo fenotipo","quadro de punnett"],"summary":"Genes, alelos dominantes e recessivos, genótipo, fenótipo e a proporção 3:1.","intro":"Por que você tem olhos parecidos com os do seu pai ou da sua mãe? Um monge e suas ervilhas ajudaram a explicar.","skills":{"conceitos":"Gene, alelo, genótipo e fenótipo","dominancia":"Dominante e recessivo","mendel":"Experimentos de Mendel","cruzamentos":"Cruzamentos e proporções"},"blocks":[{"id":"b1","skill":"conceitos","title":"Vocabulário básico","text":"Gene é um trecho de DNA que influencia uma característica. Alelos são versões de um gene. Recebemos um alelo da mãe e um do pai. Genótipo é o conjunto de alelos (ex.: Aa); fenótipo é a característica observada (ex.: semente amarela).","example":"Para a cor da semente de ervilha, A = amarelo e a = verde."},{"id":"b2","skill":"dominancia","title":"Dominante e recessivo","text":"O alelo dominante (letra maiúscula) se manifesta mesmo em dose única (AA ou Aa). O recessivo (minúscula) só aparece em dose dupla (aa). Quem tem alelos iguais é homozigoto; diferentes, heterozigoto.","example":"Aa tem semente amarela (A domina), mas carrega o alelo a."},{"id":"b3","skill":"mendel","title":"Mendel e as ervilhas","text":"Gregor Mendel cruzou ervilhas puras amarelas com verdes: todas as filhas (F1) nasceram amarelas. Cruzando as F1 entre si, na F2 surgiram amarelas e verdes na proporção de 3 para 1. Ele concluiu que cada característica depende de um par de fatores, que se separam na formação dos gametas: a Lei da Segregação.","example":"Em cada 4 plantas da F2, cerca de 3 eram amarelas e 1 verde."},{"id":"b4","skill":"cruzamentos","title":"O quadro de Punnett","text":"Para prever os descendentes, cruzamos os gametas num quadro. Aa × Aa dá AA, Aa, Aa, aa: genótipos 1:2:1 e fenótipos 3 dominantes : 1 recessivo (75% e 25%).","example":"Aa × aa dá 50% Aa (amarelas) e 50% aa (verdes)."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"mendel","prompt":"Com que planta Mendel fez seus experimentos?","options":["Feijão","Ervilha","Milho","Rosa"],"answer":1,"hints":["É uma leguminosa.","Tem sementes amarelas ou verdes.","Erv…"],"explanation":"Com ervilhas."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceitos","prompt":"Recebemos um alelo de cada gene da mãe e outro do pai.","answer":true,"hints":["Os genes vêm em pares.","Um de cada genitor.","Metade de cada."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"dominancia","prompt":"Um alelo recessivo só se manifesta quando:","options":["Está em dose única","Está em dose dupla (aa)","Está junto do dominante","Nunca se manifesta"],"answer":1,"hints":["O dominante \"esconde\" o recessivo.","Então não pode haver dominante.","Os dois alelos precisam ser recessivos."],"explanation":"Só no homozigoto recessivo (aa)."},{"id":"q4","type":"match","difficulty":2,"skill":"conceitos","prompt":"Ligue cada termo ao significado.","pairs":[["Genótipo","Conjunto de alelos (ex.: Aa)"],["Fenótipo","Característica observável"],["Homozigoto","Alelos iguais (AA ou aa)"],["Heterozigoto","Alelos diferentes (Aa)"]],"hints":["\"Geno\" lembra gene.","\"Feno\" lembra o que aparece.","Homo = igual; hetero = diferente."],"explanation":"Genótipo: alelos · fenótipo: característica · homo: iguais · hetero: diferentes."},{"id":"q5","type":"fill","difficulty":2,"skill":"mendel","prompt":"Na geração F2 de Mendel, a proporção entre amarelas e verdes foi de ___ para 1.","answers":["3"],"hints":["Em cada 4 plantas…","…uma era verde.","As outras eram amarelas."],"explanation":"3 : 1."},{"id":"q6","type":"mc","difficulty":2,"skill":"cruzamentos","prompt":"No cruzamento Aa × Aa, qual a porcentagem esperada de descendentes aa?","options":["0%","25%","50%","75%"],"answer":1,"hints":["Monte o quadro: AA, Aa, Aa, aa.","Quantos aa em 4?","1 em 4."],"explanation":"1/4 = 25%."},{"id":"q7","type":"tf","difficulty":2,"skill":"dominancia","prompt":"Uma ervilha Aa tem sementes verdes.","answer":false,"hints":["A (amarelo) é dominante.","Em Aa, quem se manifesta?","O dominante."],"explanation":"Falso. Aa é amarela."},{"id":"q8","type":"mc","difficulty":3,"skill":"cruzamentos","prompt":"No cruzamento Aa × aa, qual a proporção de fenótipos?","options":["100% amarelas","75% amarelas e 25% verdes","50% amarelas e 50% verdes","100% verdes"],"answer":2,"hints":["Gametas: A e a × a e a.","Resultados: Aa, Aa, aa, aa.","Metade de cada."],"explanation":"50% Aa (amarelas) e 50% aa (verdes)."},{"id":"q9","type":"fill","difficulty":3,"skill":"mendel","prompt":"A 1ª Lei de Mendel também é chamada de Lei da ________.","answers":["segregacao","segregação","segregacao dos fatores"],"hints":["Os fatores se separam nos gametas.","Separar = segregar.","Segreg…"],"explanation":"Lei da Segregação."},{"id":"q10","type":"open","difficulty":3,"skill":"dominancia","prompt":"Explique como dois pais de sementes amarelas podem ter descendentes com sementes verdes.","modelAnswer":"Se os dois pais forem heterozigotos (Aa), cada um pode passar o alelo recessivo a. O descendente que receber a de cada um será aa e terá semente verde, o que acontece em cerca de 25% dos casos.","keywords":["heterozigot","aa","recessivo","25","alelo","cada"],"hints":["Qual o genótipo dos pais?","Eles \"escondem\" um alelo.","O filho recebe um de cada."],"explanation":"Pais Aa podem gerar filhos aa (25%)."}],"review":["Gene, alelo, genótipo (Aa) e fenótipo (característica)","Dominante aparece em AA/Aa; recessivo só em aa","Mendel: F1 toda dominante; F2 3:1","Aa × Aa → 1:2:1 (genótipos), 3:1 (fenótipos)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — Primeira Lei de Mendel","url":"https://www.todamateria.com.br/primeira-lei-de-mendel/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Escolas literárias","subtopic":"Modernismo brasileiro","relatedQuestions":["O que foi a Semana de Arte Moderna?","Quais são as fases do Modernismo?","Quem foi Mário de Andrade?"],"id":"lit-modernismo","subject":"literatura","title":"Modernismo brasileiro","levels":["medio"],"grade":"3ª série","aliases":["modernismo","semana de arte moderna","semana de 22","mario de andrade","oswald de andrade","antropofagia","geracao de 30","literatura modernista"],"summary":"A Semana de Arte Moderna de 1922, as fases do Modernismo e seus principais autores.","intro":"Em 1922, um grupo de artistas decidiu romper com as regras e criar uma arte \"com a cara do Brasil\".","skills":{"semana":"Semana de Arte Moderna","ideias":"Propostas modernistas","fases":"Fases do Modernismo","autores":"Autores e obras"},"blocks":[{"id":"b1","skill":"semana","title":"A Semana de 1922","text":"A Semana de Arte Moderna aconteceu no Theatro Municipal de São Paulo, de 13 a 17 de fevereiro de 1922, com exposições, conferências e concertos. Participaram Mário de Andrade, Oswald de Andrade, Anita Malfatti, Di Cavalcanti, Heitor Villa-Lobos, Menotti Del Picchia, entre outros.","example":"Coincidiu com o centenário da Independência, e muitos artistas queriam uma \"independência cultural\"."},{"id":"b2","skill":"ideias","title":"O que os modernistas queriam","text":"Romper com o academicismo e o Parnasianismo, usar verso livre, linguagem coloquial e humor, e valorizar a cultura e a identidade brasileiras de forma crítica.","example":"O \"Manifesto Antropófago\" (1928), de Oswald, propunha \"devorar\" a cultura estrangeira e transformá-la em algo brasileiro."},{"id":"b3","skill":"fases","title":"As fases","text":"1ª fase (1922–1930): heroica, de ruptura e experimentação. 2ª fase (1930–1945): Geração de 30, com o romance regionalista de denúncia social e poesia mais madura. 3ª fase (a partir de 1945): Geração de 45, com experimentação da linguagem, como em Guimarães Rosa e Clarice Lispector.","example":"\"Vidas Secas\" (1938), de Graciliano Ramos, retrata a seca no sertão nordestino."},{"id":"b4","skill":"autores","title":"Autores e obras","text":"Mário de Andrade (Macunaíma), Oswald de Andrade (Manifesto Antropófago), Manuel Bandeira, Carlos Drummond de Andrade, Cecília Meireles, Graciliano Ramos (Vidas Secas), Rachel de Queiroz (O Quinze), Jorge Amado, Guimarães Rosa (Grande Sertão: Veredas) e Clarice Lispector.","example":"Macunaíma é o \"herói sem nenhum caráter\", que mistura lendas e culturas brasileiras."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"semana","prompt":"Em que ano aconteceu a Semana de Arte Moderna?","options":["1822","1922","1930","1945"],"answer":1,"hints":["Foi no centenário da Independência.","A Independência foi em 1822.","100 anos depois."],"explanation":"Em 1922."},{"id":"q2","type":"mc","difficulty":1,"skill":"semana","prompt":"Onde foi realizada a Semana de Arte Moderna?","options":["Theatro Municipal do Rio de Janeiro","Theatro Municipal de São Paulo","Salvador","Brasília"],"answer":1,"hints":["Na maior cidade do país.","Num teatro.","Em São Paulo."],"explanation":"No Theatro Municipal de São Paulo."},{"id":"q3","type":"tf","difficulty":1,"skill":"ideias","prompt":"Os modernistas defendiam o uso do verso livre e da linguagem coloquial.","answer":true,"hints":["Eles queriam romper regras.","Rimas e métricas rígidas eram regra de quem?","Dos parnasianos."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"autores","prompt":"Ligue cada obra ao autor.","pairs":[["Macunaíma","Mário de Andrade"],["Vidas Secas","Graciliano Ramos"],["O Quinze","Rachel de Queiroz"],["Grande Sertão: Veredas","Guimarães Rosa"]],"hints":["Macunaíma é de um dos organizadores da Semana.","O Quinze fala da seca de 1915.","Grande Sertão é da 3ª fase."],"explanation":"Mário · Graciliano · Rachel · Guimarães Rosa."},{"id":"q5","type":"fill","difficulty":2,"skill":"ideias","prompt":"O manifesto de Oswald de Andrade que propunha \"devorar\" a cultura estrangeira é o Manifesto ________.","answers":["antropofago","antropófago"],"hints":["Lembra canibalismo.","Antropo = homem; fago = comer.","Antropó…"],"explanation":"Manifesto Antropófago (1928)."},{"id":"q6","type":"mc","difficulty":2,"skill":"fases","prompt":"A 2ª fase do Modernismo (Geração de 30) se destacou pelo:","options":["Romance regionalista de denúncia social","Retorno às formas parnasianas","Fim da prosa","Teatro medieval"],"answer":0,"hints":["Pense em Vidas Secas.","Retrata problemas sociais.","Em regiões do Brasil."],"explanation":"Romance regionalista e crítica social."},{"id":"q7","type":"tf","difficulty":2,"skill":"fases","prompt":"Clarice Lispector é uma autora da primeira fase do Modernismo.","answer":false,"hints":["Ela estreou em 1943.","A 1ª fase vai até 1930.","É associada à Geração de 45."],"explanation":"Falso. É associada à 3ª fase."},{"id":"q8","type":"mc","difficulty":3,"skill":"ideias","prompt":"Qual escola literária os modernistas mais criticavam?","options":["Parnasianismo","Barroco","Arcadismo","Trovadorismo"],"answer":0,"hints":["Era a escola \"oficial\" no início do século XX.","Valorizava rima rica e métrica perfeita.","\"Arte pela arte\"."],"explanation":"O Parnasianismo."},{"id":"q9","type":"mc","difficulty":3,"skill":"semana","prompt":"Qual pintora teve uma exposição em 1917 considerada precursora do Modernismo e participou da Semana?","options":["Tarsila do Amaral","Anita Malfatti","Cecília Meireles","Pagu"],"answer":1,"hints":["Sua exposição foi criticada por Monteiro Lobato.","Participou da Semana de 22.","Anita…"],"explanation":"Anita Malfatti. (Tarsila não participou da Semana.)"},{"id":"q10","type":"open","difficulty":3,"skill":"ideias","prompt":"Por que a Semana de 1922 foi importante para a cultura brasileira?","modelAnswer":"Porque rompeu com os modelos acadêmicos e europeus, trouxe liberdade de forma, linguagem coloquial e a valorização crítica da identidade e da cultura brasileiras, abrindo caminho para o Modernismo.","keywords":["romp","identidade","brasileira","liberdade","academic","europ","cultura","verso livre"],"hints":["Com o que ela rompeu?","O que passou a ser valorizado?","Fale de identidade brasileira."],"explanation":"Ruptura com o academicismo e valorização da identidade nacional."}],"review":["Semana de 1922: Theatro Municipal de SP, 13 a 17/2","Ruptura: verso livre, coloquialismo, identidade","3 fases: heroica, Geração de 30, Geração de 45","Mário, Oswald, Drummond, Graciliano, Rachel, Rosa, Clarice"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Linguagens","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Agência Brasil — Centenário: conheça os artistas e o que queriam os modernistas de 1922","url":"https://agenciabrasil.ebc.com.br/geral/noticia/2022-02/centenario-conheca-os-artistas-e-o-que-queriam-os-modernistas-de-22","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Filosofia antiga","subtopic":"Período clássico","relatedQuestions":["Quem foi Sócrates?","O que é o mito da caverna?","O que Aristóteles pensava sobre a virtude?","O que é maiêutica?"],"id":"fil-socrates-platao-aristoteles","subject":"filosofia","title":"Sócrates, Platão e Aristóteles","levels":["medio"],"grade":"1ª série","aliases":["socrates","platao","aristoteles","filosofia grega","filosofia antiga","maieutica","mito da caverna","alegoria da caverna","so sei que nada sei"],"summary":"O método de Sócrates, a teoria das ideias de Platão e a ética de Aristóteles.","intro":"Três pensadores gregos, mestre e alunos, influenciam o jeito como pensamos até hoje.","skills":{"socrates":"Sócrates e a maiêutica","platao":"Platão e o mundo das ideias","aristoteles":"Aristóteles e a ética","relacao":"Relações entre os três"},"blocks":[{"id":"b1","skill":"socrates","title":"Sócrates: perguntar para pensar","text":"Sócrates (c. 470–399 a.C.) não deixou nada escrito. Ele conversava fazendo perguntas: primeiro mostrava que a pessoa não sabia tanto quanto pensava (ironia) e depois a ajudava a \"dar à luz\" as próprias ideias (maiêutica). É associado à frase \"só sei que nada sei\".","example":"Em vez de dizer o que é justiça, Sócrates perguntava: \"O que você entende por justo?\""},{"id":"b2","skill":"platao","title":"Platão: o mundo das ideias","text":"Platão (c. 428–348 a.C.), discípulo de Sócrates, dividiu a realidade em mundo sensível (das coisas que percebemos, que mudam) e mundo das ideias (verdadeiro e eterno). Na Alegoria da Caverna, prisioneiros veem só sombras e as tomam como realidade. Fundou a Academia.","example":"Existem muitos cavalos diferentes, mas todos lembram a ideia perfeita de \"cavalo\"."},{"id":"b3","skill":"aristoteles","title":"Aristóteles: observar e o meio-termo","text":"Aristóteles (384–322 a.C.), aluno de Platão, valorizava a observação do mundo real. Organizou a lógica e escreveu sobre ética, política e ciências. Para ele, a virtude é o meio-termo entre dois extremos, e o fim da vida humana é a felicidade (eudaimonia). Fundou o Liceu.","example":"A coragem é o meio-termo entre a covardia (falta) e a imprudência (excesso)."},{"id":"b4","skill":"relacao","title":"Mestre e alunos","text":"Sócrates foi mestre de Platão, que foi mestre de Aristóteles. Aristóteles, por sua vez, foi tutor de Alexandre, o Grande. Sócrates foi condenado à morte em Atenas, acusado de corromper a juventude e desrespeitar os deuses.","example":"Conhecemos as ideias de Sócrates principalmente pelos diálogos escritos por Platão."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"socrates","prompt":"A frase \"só sei que nada sei\" é associada a:","options":["Aristóteles","Sócrates","Platão","Tales"],"answer":1,"hints":["Ele fazia muitas perguntas.","Não deixou nada escrito.","Mestre de Platão."],"explanation":"Sócrates."},{"id":"q2","type":"mc","difficulty":1,"skill":"platao","prompt":"A Alegoria da Caverna foi escrita por:","options":["Sócrates","Platão","Aristóteles","Descartes"],"answer":1,"hints":["Fala do mundo das ideias.","Discípulo de Sócrates.","Fundou a Academia."],"explanation":"Platão, na obra A República."},{"id":"q3","type":"tf","difficulty":1,"skill":"relacao","prompt":"Aristóteles foi aluno de Platão.","answer":true,"hints":["Pense na sequência mestre → aluno.","Sócrates → Platão → …","Aristóteles."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":2,"skill":"socrates","prompt":"O método socrático de ajudar o outro a \"dar à luz\" as ideias se chama ________.","answers":["maieutica","maiêutica"],"hints":["Vem da ideia de parto.","A mãe de Sócrates era parteira.","Maiêu…"],"explanation":"Maiêutica."},{"id":"q5","type":"match","difficulty":2,"skill":"relacao","prompt":"Ligue cada filósofo a uma ideia.","pairs":[["Sócrates","Maiêutica e ironia"],["Platão","Mundo das ideias"],["Aristóteles","Virtude como meio-termo"]],"hints":["O das perguntas.","O da caverna.","O da ética do equilíbrio."],"explanation":"Sócrates: maiêutica · Platão: ideias · Aristóteles: meio-termo."},{"id":"q6","type":"mc","difficulty":2,"skill":"aristoteles","prompt":"Para Aristóteles, a coragem é o meio-termo entre:","options":["Alegria e tristeza","Covardia e imprudência","Riqueza e pobreza","Razão e emoção"],"answer":1,"hints":["Um extremo é faltar coragem.","O outro é ter coragem demais.","Sem medo nenhum = imprudente."],"explanation":"Entre a covardia (falta) e a imprudência (excesso)."},{"id":"q7","type":"tf","difficulty":2,"skill":"socrates","prompt":"Sócrates escreveu vários livros com suas ideias.","answer":false,"hints":["Como conhecemos suas ideias?","Por meio de outra pessoa.","Pelos diálogos de Platão."],"explanation":"Falso. Sócrates não deixou nada escrito."},{"id":"q8","type":"mc","difficulty":3,"skill":"platao","prompt":"Na Alegoria da Caverna, as sombras vistas pelos prisioneiros representam:","options":["O mundo das ideias","As aparências do mundo sensível tomadas como verdade","A felicidade","A lógica"],"answer":1,"hints":["Os prisioneiros acham que as sombras são reais.","Mas são só aparências.","Mundo sensível."],"explanation":"As aparências do mundo sensível confundidas com a realidade."},{"id":"q9","type":"fill","difficulty":3,"skill":"aristoteles","prompt":"A escola fundada por Aristóteles em Atenas se chamava ________.","answers":["liceu"],"hints":["Platão fundou a Academia.","A de Aristóteles tem outro nome.","Lic…"],"explanation":"O Liceu."},{"id":"q10","type":"open","difficulty":3,"skill":"socrates","prompt":"Por que fazer perguntas, como Sócrates, pode ajudar alguém a aprender?","modelAnswer":"Porque as perguntas fazem a pessoa examinar o que pensa, perceber contradições e o que não sabe, e chegar por conta própria a ideias mais claras, em vez de só receber respostas prontas.","keywords":["pensar","refletir","contradic","propria","descobrir","nao sabe","examinar"],"hints":["O que acontece quando alguém te pergunta algo difícil?","Você precisa pensar.","E descobre sozinho."],"explanation":"Perguntar leva a pessoa a refletir e descobrir."}],"review":["Sócrates: ironia, maiêutica, \"só sei que nada sei\"","Platão: mundo das ideias × sensível; caverna; Academia","Aristóteles: observação, lógica, virtude como meio-termo; Liceu","Sócrates → Platão → Aristóteles"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências Humanas e Sociais Aplicadas","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Filosofia em Resumo — Sócrates, Platão e Aristóteles","url":"https://filosofiaemresumo.com.br/pt/sinteses/02_socrates-platao-aristoteles/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Teoria sociológica","subtopic":"Clássicos da Sociologia","relatedQuestions":["O que é fato social?","O que é ação social para Weber?","O que é luta de classes?","O que é mais-valia?"],"id":"soc-classicos-sociologia","subject":"sociologia","title":"Clássicos da Sociologia: Durkheim, Weber e Marx","levels":["medio"],"grade":"1ª série","aliases":["sociologia","durkheim","weber","marx","fato social","acao social","luta de classes","classicos da sociologia"],"summary":"Fato social (Durkheim), ação social (Weber) e luta de classes (Marx).","intro":"Como a sociedade influencia o que fazemos? Três pensadores deram respostas diferentes.","skills":{"durkheim":"Durkheim e o fato social","weber":"Weber e a ação social","marx":"Marx e a luta de classes","comparacao":"Comparando os três"},"blocks":[{"id":"b1","skill":"durkheim","title":"Durkheim: o fato social","text":"Émile Durkheim definiu fato social como as formas de agir, pensar e sentir que existem fora do indivíduo e se impõem a ele. Tem três características: coercitividade (pressiona o indivíduo), exterioridade (já existia antes dele) e generalidade (atinge a todos).","example":"A língua que falamos já existia antes de nascermos e somos pressionados a usá-la corretamente."},{"id":"b2","skill":"weber","title":"Weber: a ação social","text":"Max Weber estudou a ação social: toda ação que o indivíduo orienta levando em conta o comportamento dos outros. Para entender a sociedade, é preciso compreender o sentido que as pessoas dão às suas ações.","example":"Cumprimentar alguém na rua é uma ação social: considera o outro e tem um sentido."},{"id":"b3","skill":"marx","title":"Marx: luta de classes","text":"Karl Marx analisou o capitalismo a partir das relações de produção. A burguesia é dona dos meios de produção; o proletariado vende sua força de trabalho. O conflito entre essas classes — a luta de classes — seria o motor das transformações históricas.","example":"Para Marx, o lucro vem em parte do trabalho não pago ao operário (mais-valia)."},{"id":"b4","skill":"comparacao","title":"Três olhares","text":"Durkheim enfatiza como a sociedade molda o indivíduo; Weber, o sentido das ações individuais; Marx, os conflitos econômicos entre classes. São perspectivas complementares para entender a vida social.","example":"Um mesmo tema, como o trabalho, pode ser estudado pelos três ângulos."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"durkheim","prompt":"O conceito de \"fato social\" foi formulado por:","options":["Karl Marx","Émile Durkheim","Max Weber","Auguste Comte"],"answer":1,"hints":["Sociólogo francês.","Fala de coercitividade.","Émile…"],"explanation":"Émile Durkheim."},{"id":"q2","type":"match","difficulty":2,"skill":"comparacao","prompt":"Ligue cada pensador ao conceito central.","pairs":[["Durkheim","Fato social"],["Weber","Ação social"],["Marx","Luta de classes"]],"hints":["O francês: fato social.","O alemão da \"compreensão\": ação social.","O do Manifesto Comunista: classes."],"explanation":"Durkheim: fato social · Weber: ação social · Marx: luta de classes."},{"id":"q3","type":"tf","difficulty":1,"skill":"durkheim","prompt":"A generalidade é uma das características do fato social.","answer":true,"hints":["São três características.","Coercitividade, exterioridade e…","Atinge a todos."],"explanation":"Verdadeiro."},{"id":"q4","type":"mc","difficulty":2,"skill":"durkheim","prompt":"A língua que falamos já existia antes de nascermos. Isso ilustra qual característica do fato social?","options":["Exterioridade","Ação social","Mais-valia","Luta de classes"],"answer":0,"hints":["Existe fora e antes do indivíduo.","Não fomos nós que criamos.","Exter…"],"explanation":"Exterioridade."},{"id":"q5","type":"fill","difficulty":2,"skill":"marx","prompt":"Para Marx, a classe dona dos meios de produção é a ________.","answers":["burguesia"],"hints":["A outra é o proletariado.","Donos das fábricas.","Burgu…"],"explanation":"A burguesia."},{"id":"q6","type":"mc","difficulty":2,"skill":"weber","prompt":"Para Weber, uma ação é social quando:","options":["É obrigatória por lei","É orientada levando em conta o comportamento de outras pessoas","É feita por muitas pessoas ao mesmo tempo","Envolve dinheiro"],"answer":1,"hints":["Considera os outros.","Tem um sentido.","Não basta ser coletiva."],"explanation":"Quando é orientada pela ação de outros."},{"id":"q7","type":"tf","difficulty":2,"skill":"marx","prompt":"Para Marx, a luta de classes é o motor das transformações históricas.","answer":true,"hints":["Conflito entre burguesia e proletariado.","Isso mudaria a história.","É a tese central."],"explanation":"Verdadeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"durkheim","prompt":"A coercitividade do fato social significa que ele:","options":["Só existe em pequenos grupos","Exerce pressão sobre o indivíduo para que se comporte de certa forma","Depende da vontade de cada um","Não muda nunca"],"answer":1,"hints":["Coerção = pressão.","O indivíduo sente essa força.","Ex.: regras de conduta."],"explanation":"Exerce pressão sobre o indivíduo."},{"id":"q9","type":"fill","difficulty":3,"skill":"marx","prompt":"O valor produzido pelo trabalhador e não pago a ele, segundo Marx, é a ________.","answers":["mais-valia","mais valia","maisvalia"],"hints":["Explica o lucro.","Mais-…","…valia."],"explanation":"Mais-valia."},{"id":"q10","type":"open","difficulty":3,"skill":"comparacao","prompt":"Dê um exemplo de fato social do seu dia a dia e explique por quê.","modelAnswer":"O uso de uniforme na escola é um fato social: a regra já existia antes de o aluno chegar (exterioridade), vale para todos (generalidade) e quem não usa sofre alguma sanção (coercitividade).","keywords":["exterior","geral","coerc","todos","regra","antes","pressao","sancao"],"hints":["Pense numa regra ou costume.","Ele já existia antes de você?","Vale para todos? Há pressão?"],"explanation":"Um bom exemplo mostra exterioridade, generalidade e coercitividade."}],"review":["Durkheim: fato social (coercitivo, exterior, geral)","Weber: ação social e seu sentido","Marx: burguesia × proletariado, mais-valia","Olhares complementares sobre a sociedade"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências Humanas e Sociais Aplicadas","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — O que é Fato Social?","url":"https://www.todamateria.com.br/o-que-e-fato-social/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Artes visuais","subtopic":"Teoria das cores","relatedQuestions":["Quais são as cores primárias?","Que cor dá azul com amarelo?","O que são cores quentes e frias?","O que são cores complementares?"],"id":"art-cores","subject":"artes","title":"Cores primárias, secundárias e complementares","levels":["fund1","fund2"],"grade":"2º ao 6º ano","aliases":["cores primarias","cores secundarias","circulo cromatico","cores quentes e frias","cores complementares","misturar cores","teoria das cores"],"summary":"Descubra como as cores se misturam, o círculo cromático e as cores quentes e frias.","intro":"Com só três cores de tinta dá para fazer muitas outras. Vamos misturar!","skills":{"primarias":"Cores primárias","secundarias":"Cores secundárias","quentes_frias":"Cores quentes e frias","complementares":"Cores complementares"},"blocks":[{"id":"b1","skill":"primarias","title":"As cores primárias","text":"Nas tintas escolares, as cores primárias são vermelho, amarelo e azul. Elas não podem ser obtidas misturando outras cores de tinta — e a partir delas fazemos muitas outras.","example":"Com uma caixinha de vermelho, amarelo e azul já dá para pintar um arco-íris inteiro.","variants":{"simples":"Vermelho, amarelo e azul são as cores \"mães\": misturando elas, nascem as outras."}},{"id":"b2","skill":"secundarias","title":"As cores secundárias","text":"Misturando duas primárias em partes iguais, obtemos as secundárias: vermelho + amarelo = laranja; amarelo + azul = verde; azul + vermelho = roxo (violeta).","example":"Para pintar uma folha de árvore, misture amarelo com azul.","variants":{"simples":"Vermelho + amarelo = laranja. Amarelo + azul = verde. Azul + vermelho = roxo."}},{"id":"b3","skill":"quentes_frias","title":"Quentes e frias","text":"Cores quentes (vermelho, laranja, amarelo) lembram fogo e sol e passam sensação de calor e energia. Cores frias (azul, verde, roxo) lembram água e gelo e passam calma.","example":"Um pôr do sol é pintado com cores quentes; o fundo do mar, com cores frias.","variants":{"simples":"Quentes lembram o sol: vermelho, laranja, amarelo. Frias lembram a água: azul, verde, roxo."}},{"id":"b4","skill":"complementares","title":"Cores complementares","text":"No círculo cromático, as cores que ficam uma de frente para a outra são complementares: vermelho e verde, azul e laranja, amarelo e roxo. Juntas, uma destaca a outra.","example":"Muitos logotipos usam azul com laranja para chamar atenção.","variants":{"simples":"Algumas cores são \"opostas\" e combinam para chamar atenção: azul e laranja, vermelho e verde, amarelo e roxo."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"primarias","prompt":"Quais são as cores primárias das tintas escolares?","options":["Verde, laranja e roxo","Vermelho, amarelo e azul","Preto, branco e cinza","Rosa, azul e verde"],"answer":1,"hints":["São as cores \"mães\".","Não dá para fazê-las misturando outras.","Uma delas é o amarelo."],"explanation":"Vermelho, amarelo e azul."},{"id":"q2","type":"mc","difficulty":1,"skill":"secundarias","prompt":"Amarelo + azul dá:","options":["Laranja","Roxo","Verde","Marrom"],"answer":2,"hints":["É a cor das folhas.","Também é cor da grama.","Começa com V."],"explanation":"Amarelo + azul = verde."},{"id":"q3","type":"tf","difficulty":1,"skill":"quentes_frias","prompt":"O vermelho é uma cor quente.","answer":true,"hints":["Lembra fogo ou água?","Lembra fogo.","Fogo → quente."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":1,"skill":"secundarias","prompt":"Vermelho + amarelo dá a cor ________.","answers":["laranja"],"hints":["É a cor de uma fruta.","Também é o nome da fruta.","Laran…"],"explanation":"Laranja."},{"id":"q5","type":"match","difficulty":2,"skill":"secundarias","prompt":"Ligue cada mistura à cor que ela forma.","pairs":[["Vermelho + amarelo","Laranja"],["Amarelo + azul","Verde"],["Azul + vermelho","Roxo"]],"hints":["Pense no sol se pondo: vermelho e amarelo.","Folhas: amarelo e azul.","Uva: azul e vermelho."],"explanation":"Laranja, verde e roxo."},{"id":"q6","type":"mc","difficulty":2,"skill":"quentes_frias","prompt":"Qual destas é uma cor fria?","options":["Laranja","Amarelo","Azul","Vermelho"],"answer":2,"hints":["Cores frias lembram água.","Qual é a cor do mar?","Azul."],"explanation":"Azul é fria."},{"id":"q7","type":"tf","difficulty":2,"skill":"primarias","prompt":"Dá para fazer tinta amarela misturando outras duas cores de tinta.","answer":false,"hints":["O amarelo é primário ou secundário?","Primário.","Primárias não são feitas por mistura."],"explanation":"Falso. O amarelo é primário."},{"id":"q8","type":"mc","difficulty":3,"skill":"complementares","prompt":"Qual é a cor complementar do azul?","options":["Verde","Roxo","Laranja","Amarelo"],"answer":2,"hints":["É a cor oposta no círculo.","Ela é quente.","É secundária, feita com vermelho e amarelo."],"explanation":"Azul e laranja são complementares."},{"id":"q9","type":"mc","difficulty":3,"skill":"quentes_frias","prompt":"Para pintar um quadro que passe calma e tranquilidade, o mais indicado é usar:","options":["Cores quentes","Cores frias","Só preto","Só vermelho"],"answer":1,"hints":["Pense no mar e no céu.","Essas cores acalmam.","São as frias."],"explanation":"Cores frias passam calma."},{"id":"q10","type":"tf","difficulty":3,"skill":"complementares","prompt":"Vermelho e verde são cores complementares.","answer":true,"hints":["Verde é feito com amarelo e azul.","Falta qual primária?","A que falta é a complementar."],"explanation":"Verdadeiro."}],"review":["Primárias: vermelho, amarelo, azul","Secundárias: laranja, verde, roxo","Quentes (sol) × frias (água)","Complementares ficam opostas no círculo"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Arte","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
